'use client';
import { STORE_TOKENS } from '@/components/store/constants/tokens';

import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { createClient } from '@/lib/supabase/client'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { HeartHandshake } from 'lucide-react'
import { AdminAffiliatesContent } from '@/components/store/sections/admin-affiliates-content'

/**
 * AdminAfiliadosPage: Standardized entry point.
 * Logic is decoupled into AdminAffiliatesContent section.
 */
import { RegistryProvider } from '@/components/store/advanced/registry-context'

export default function AdminAfiliadosPage() {
    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="GESTÃO DE AFILIADOS"
                    subtitle="Administração de parceiros comerciais, comissões e indicações."
                    icon={HeartHandshake}
                    contextLabel="Painel Admin"
                    showTabs={false}
                >
                    <AdminAffiliatesContent />
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

'use client'

import { STORE_TOKENS } from '@/components/store/constants/tokens'

import { useState, useTransition } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import {
    getAllUsers, deleteUser, impersonateUser, grantAutoTraining
} from '@/actions/admin-actions'
import { createClient } from '@/lib/supabase/client'
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Modal } from '@/components/store/advanced/modal'
import { Stack } from '@/components/store/base/stack'
import { UserListItem } from '@/components/store/intermediary/user-list-item'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { Font } from '@/components/store/base/font'
import { Input } from '@/components/store/base/input'
import { useToast } from '@/hooks/use-toast'
import { GraduationCap, Search, XCircle } from 'lucide-react'

export default function AdminAlunosPage() {
    const queryClient = useQueryClient()
    const [search, setSearch] = useState('')
    const [isPending, startTransition] = useTransition()
    const [deleteModal, setDeleteModal] = useState<{ open: boolean, id: string, name: string }>({
        open: false,
        id: '',
        name: ''
    })
    const { toast } = useToast()

    const { data: allUsers = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.admin.students,
        queryFn: () => getAllUsers()
    })

    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    async function handleImpersonate(userId: string) {
        startTransition(async () => {
            const res = await impersonateUser(userId)
            if (res?.error) toast({ variant: 'destructive', title: 'Erro ao inspecionar', description: res.error })
        })
    }

    async function handleDeleteUser(userId: string, userName: string) {
        setDeleteModal({ open: true, id: userId, name: userName })
    }

    async function confirmDeleteUser() {
        if (!deleteModal.id) return
        startTransition(async () => {
            const res = await deleteUser(deleteModal.id)
            if (res.error) {
                toast({ variant: 'destructive', title: 'Erro', description: res.error })
            } else {
                toast({ title: 'Aluno deletado com sucesso!' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.students })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview })
            }
            setDeleteModal({ open: false, id: '', name: '' })
        })
    }

    async function handleGrantAutoTraining(studentId: string, currentStatus: string) {
        const newStatus = currentStatus === 'active' ? 'none' : 'active'
        startTransition(async () => {
            const res = await grantAutoTraining(studentId, newStatus)
            if (res.error) toast({ variant: 'destructive', title: 'Erro', description: res.error })
            else {
                toast({ title: newStatus === 'active' ? 'Auto-Treino concedido!' : 'Auto-Treino removido' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.students })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview })
            }
        })
    }

    const students = allUsers
        .filter(s => s.role === 'student')
        .filter(s =>
            !search ||
            s.full_name?.toLowerCase().includes(search.toLowerCase()) ||
            s.email?.toLowerCase().includes(search.toLowerCase())
        )

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="GESTÃO DE ALUNOS"
                    subtitle="Monitoramento da base de alunos e ativação de planos automatizados."
                    icon={GraduationCap}
                    contextLabel="Painel Admin"
                    showTabs={false}
                >
                    <RegistrySection
                        title="Matrículas e Acessos"
                        subtitle="Monitore a base de alunos e gerencie privilégios de acesso."
                        icon={GraduationCap}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            {/* Search */}
                            <Input
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                placeholder="Buscar aluno por nome ou email..."
                                icon={<Search size={16} />}
                                rounded={STORE_TOKENS.RADIUS.FULL}
                            />

                            {isLoading && <EmptyState icon={GraduationCap} title="Carregando..." description="Buscando alunos cadastrados." />}

                            {!isLoading && students.map(student => (
                                <UserListItem
                                    key={student.id}
                                    name={student.full_name || 'Sem nome'}
                                    email={student.email || ''}
                                    registrationDate={new Date(student.created_at).toLocaleDateString('pt-BR')}
                                    role="aluno"
                                    roleLabel={(student as any).auto_training_status === 'active' ? 'AUTO-TREINO' : 'ALUNO'}
                                    initials={(student.full_name || '??').substring(0, 2).toUpperCase()}
                                    avatarVariant="emerald"
                                    avatarUrl={student.avatar_url}
                                    onInspect={() => handleImpersonate(student.id)}
                                    onAction={() => handleGrantAutoTraining(student.id, (student as any).auto_training_status)}
                                    isActionActive={(student as any).auto_training_status === 'active'}
                                    onDelete={() => handleDeleteUser(student.id, student.full_name || student.email)}
                                />
                            ))}

                            {!isLoading && students.length === 0 && (
                                <EmptyState icon={Search} title="Nenhum aluno encontrado" description="Tente ajustar os filtros de busca." />
                            )}
                        </Stack>
                    </RegistrySection>

                    <Modal
                        isOpen={deleteModal.open}
                        onClose={() => setDeleteModal({ ...deleteModal, open: false })}
                        title="Deletar Aluno"
                        subtitle={`Deseja deletar permanentemente ${deleteModal.name}?`}
                        icon={XCircle}
                        variant="red"
                        onConfirm={confirmDeleteUser}
                        confirmLabel="Deletar"
                    >
                        <Font variant="body" color={STORE_TOKENS.COLORS.TEXT.SECONDARY}>
                            Esta ação é irreversível e removerá todos os dados do aluno, incluindo histórico de treinos e assinaturas vinculadas.
                        </Font>
                    </Modal>
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

'use client'

import { STORE_TOKENS } from '@/components/store/constants/tokens'

import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useTransition } from 'react'
import { QUERY_KEYS } from '@/lib/query-keys'
import {
    BarChart3, TrendingUp, CreditCard, Activity,
    AlertCircle, HeartHandshake, Users2, Users, ShoppingBag
} from 'lucide-react'
import { 
    getAdminOverview, getOperationalCosts,
    addOperationalCost, deleteOperationalCost
} from '@/actions/admin-actions'
import { getAdminPayouts, updatePayoutStatus } from '@/actions/admin-affiliate-actions'
import { createClient } from '@/lib/supabase/client'
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Stack } from '@/components/store/base/stack'
import { Grid } from '@/components/store/base/grid'
import { StatsCard } from '@/components/store/intermediary/stats-card'
import { useToast } from '@/hooks/use-toast'

import { AdminPayoutsManagement } from '@/components/store/sections/admin-payouts-management'
import { AdminOperationalCosts } from '@/components/store/sections/admin-operational-costs'
import { AdminTopProducts } from '@/components/store/sections/admin-top-products'

export default function AdminDashboardPage() {
    const queryClient = useQueryClient()
    const [isPending, startTransition] = useTransition()
    const { toast } = useToast()

    const { data: stats } = useQuery({
        queryKey: QUERY_KEYS.admin.overview,
        queryFn: () => getAdminOverview()
    })

    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    const { data: payouts } = useQuery({
        queryKey: QUERY_KEYS.admin.payouts,
        queryFn: () => getAdminPayouts()
    })

    const { data: costs } = useQuery({
        queryKey: QUERY_KEYS.admin.costs,
        queryFn: () => getOperationalCosts()
    })

    const loadAll = () => {
        startTransition(async () => {
            await Promise.all([
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview }),
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.payouts }),
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.costs }),
            ])
            toast({ title: 'Dados atualizados!' })
        })
    }

    const handlePayoutAction = async (id: string, status: 'completed' | 'rejected') => {
        const res = await updatePayoutStatus(id, status)
        if (res.success) {
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.payouts })
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview })
            toast({ title: status === 'completed' ? 'Saque confirmado!' : 'Saque rejeitado.' })
        } else {
            toast({ title: 'Erro ao processar saque', description: res.error, variant: 'destructive' })
        }
    }

    const handleAddCost = async (data: any) => {
        const res = await addOperationalCost(data)
        if (res.success) {
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.costs })
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview })
            toast({ title: 'Custo adicionado!' })
        } else {
            toast({ title: 'Erro ao adicionar custo', description: res.error, variant: 'destructive' })
        }
    }

    const handleDeleteCost = async (id: string) => {
        const res = await deleteOperationalCost(id)
        if (res.success) {
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.costs })
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.overview })
            toast({ title: 'Custo removido.' })
        } else {
            toast({ title: 'Erro ao remover custo', description: res.error, variant: 'destructive' })
        }
    }

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="Visão Geral"
                    subtitle="Visão geral financeira e operacional da plataforma RepTrail."
                    icon={BarChart3}
                    contextLabel="Painel Admin"
                    showTabs={false}
                >
                    <Stack gap={STORE_TOKENS.SPACING.SECTION}>
                        {/* Indicadores de Performance */}
                        <RegistrySection
                            title="Indicadores de Performance"
                            subtitle="Visão consolidada de usuários, loja, finanças e parceiros."
                            icon={Activity}
                        >
                            <Grid cols={1} mdCols={2} lgCols={4} gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <StatsCard
                                    label="Personais"
                                    value={String(stats?.trainers || 0)}
                                    description={`${stats?.trialTrainers || 0} EM TESTE`}
                                    icon={Users2}
                                    color={STORE_TOKENS.COLORS.INFO}
                                />
                                <StatsCard
                                    label="Alunos"
                                    value={String(stats?.students || 0)}
                                    description={`${stats?.studentsWithTrainer || 0} C/ PERS. | ${stats?.autoTrainingCount || 0} AUTO`}
                                    icon={Users}
                                    color={STORE_TOKENS.COLORS.SUCCESS}
                                />
                                <StatsCard
                                    label="Produtos Loja"
                                    value={String(stats?.totalProducts || 0)}
                                    description={`${stats?.productClicks || 0} CLIQUES`}
                                    icon={ShoppingBag}
                                    color={STORE_TOKENS.COLORS.BRAND}
                                />
                                <StatsCard
                                    label="Lucro Líquido"
                                    value={`R$ ${Number(stats?.monthlyPlatformProfit || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    description={`CUSTOS: R$ ${Number(stats?.monthlyOperationalCosts || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    icon={TrendingUp}
                                    color={STORE_TOKENS.COLORS.SUCCESS}
                                />
                                <StatsCard
                                    label="Faturamento Personais"
                                    value={`R$ ${Number(stats?.monthlyTrainerVolume || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    description={`MÉDIO: R$ ${Number(stats?.trainerAverageTicket || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    icon={CreditCard}
                                    color={STORE_TOKENS.COLORS.INFO}
                                />
                                <StatsCard
                                    label="Ticket Médio"
                                    value={`R$ ${Number(stats?.platformTicketPerTrainer || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    description="POR PERSONAL"
                                    icon={Activity}
                                    color={STORE_TOKENS.COLORS.WARNING}
                                />
                                <StatsCard
                                    label="Comissões Pendentes"
                                    value={`R$ ${Number(stats?.pendingCommissions || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    description={`MÊS: R$ ${Number(stats?.commissionsThisMonth || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    icon={AlertCircle}
                                    color={STORE_TOKENS.COLORS.ERROR}
                                />
                                <StatsCard
                                    label="Afiliados"
                                    value={String(stats?.affiliatesCount || 0)}
                                    description={`LUCRO: R$ ${Number(stats?.affiliateTotalEarnings || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                                    icon={HeartHandshake}
                                    color={STORE_TOKENS.COLORS.BRAND}
                                />
                            </Grid>
                        </RegistrySection>

                        {/* Gestão Financeira: Saques e Custos */}
                        <AdminPayoutsManagement
                            initialPayouts={payouts?.data || []}
                        />

                        <AdminOperationalCosts
                            initialCosts={costs || []}
                            totalMonthly={stats?.monthlyOperationalCosts || 0}
                            totalAllTime={stats?.totalOperationalCosts || 0}
                        />

                        <AdminTopProducts />

                    </Stack>
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

import { createClient } from '@/lib/supabase/server'
import { redirect } from 'next/navigation'

export default async function AdminLayout({
    children,
}: {
    children: React.ReactNode
}) {
    const supabase = /* ❌ OUTBOX VIOLATION */ await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        redirect('/auth/login')
    }

    const { data: profile } = await supabase
        .from('profiles')
        .select('is_admin')
        .eq('id', user.id)
        .single()

    if (!profile?.is_admin) {
        redirect('/dashboard')
    }

    return <>{children}</>
}

'use client'

import { STORE_TOKENS } from '@/components/store/constants/tokens'

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getAdminLogs } from '@/actions/admin-actions'
import { createClient } from '@/lib/supabase/client'
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Stack } from '@/components/store/base/stack'
import { LogItem } from '@/components/store/intermediary/log-item'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { Input } from '@/components/store/base/input'
import { Activity, Search } from 'lucide-react'

const ACTION_VARIANT_MAP: Record<string, 'blue' | 'orange' | 'red'> = {
    UPDATE_USER_ROLE:    'blue',
    ACTIVATE_ONDEMAND:  'orange',
    DELETE_PRODUCT:     'red',
    DELETE_USER:        'red',
    GRANT_ELITE:        'orange',
    REVOKE_ELITE:       'red',
    GRANT_TRIAL:        'blue',
}

export default function AdminLogsPage() {
    const [search, setSearch] = useState('')
    const { data: logs = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.admin.logs,
        queryFn: () => getAdminLogs()
    })

    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    const filtered = logs.filter(log => 
        !search || 
        log.action.toLowerCase().includes(search.toLowerCase()) || 
        log.admin?.full_name?.toLowerCase().includes(search.toLowerCase())
    )

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="LOGS DE ATIVIDADE"
                    subtitle="Rastro de auditoria de todas as ações realizadas no painel administrativo."
                    icon={Activity}
                    contextLabel="Auditoria do Sistema"
                    showTabs={false}
                >
                    <RegistrySection
                        title="Registro de Eventos"
                        subtitle="Acompanhe todas as ações administrativas realizadas na plataforma."
                        icon={Activity}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Input
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                placeholder="Filtrar logs por ação ou administrador..."
                                icon={<Search size={16} />}
                                rounded={STORE_TOKENS.RADIUS.FULL}
                            />

                            {isLoading && (
                                <EmptyState icon={Activity} title="Carregando logs..." description="Buscando registros de auditoria." />
                            )}

                            {!isLoading && filtered.map(log => (
                                <LogItem
                                    key={log.id}
                                    action={log.action}
                                    admin={log.admin?.full_name || 'Sistema'}
                                    target={log.target_id || '—'}
                                    details={log.details || undefined}
                                    date={new Date(log.created_at).toLocaleString('pt-BR')}
                                    variant={ACTION_VARIANT_MAP[log.action] ?? 'blue'}
                                />
                            ))}

                            {!isLoading && filtered.length === 0 && (
                                <EmptyState icon={Activity} title="Sem atividades" description="Não há registros de auditoria para o período selecionado." />
                            )}
                        </Stack>
                    </RegistrySection>
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

'use client'

import { STORE_TOKENS } from '@/components/store/constants/tokens'

import { useState, useTransition } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { 
    getAllStoreProducts, toggleProductStatus, deleteStoreProduct,
    addStoreProduct, updateStoreProduct, fetchProductFromUrl
} from '@/actions/admin-actions'
import { createClient } from '@/lib/supabase/client'
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Modal } from '@/components/store/advanced/modal'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Grid } from '@/components/store/base/grid'
import { Button } from '@/components/store/base/button'
import { Input } from '@/components/store/base/input'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { ProductCard } from '@/components/store/intermediary/product-card'
import { AdminProductEditor } from '@/components/store/advanced/admin-product-editor'
import { useToast } from '@/hooks/use-toast'
import { ShoppingBag, Search, Plus, Package, XCircle } from 'lucide-react'

export default function AdminLojaPage() {
    const queryClient = useQueryClient()
    const [search, setSearch] = useState('')
    const [productModalOpen, setProductModalOpen] = useState(false)
    const [editingProduct, setEditingProduct] = useState<any>(null)
    const [deleteModal, setDeleteModal] = useState<{ open: boolean, id: string }>({
        open: false,
        id: ''
    })
    const [isPending, startTransition] = useTransition()
    const { toast } = useToast()

    const { data: products = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.store.products,
        queryFn: () => getAllStoreProducts()
    })

    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    async function handleProductToggle(productId: string, current: boolean) {
        startTransition(async () => {
            const res = await toggleProductStatus(productId, !current)
            if (res.error) toast({ variant: 'destructive', title: 'Erro', description: res.error })
            else {
                toast({ title: !current ? 'Produto ativado!' : 'Produto desativado' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.store.products })
            }
        })
    }

    async function handleDeleteProduct(productId: string) {
        setDeleteModal({ open: true, id: productId })
        return false
    }

    async function confirmDeleteProduct() {
        if (!deleteModal.id) return
        startTransition(async () => {
            const res = await deleteStoreProduct(deleteModal.id)
            if (res.error) toast({ title: 'Erro ao deletar', description: res.error, variant: 'destructive' })
            else {
                toast({ title: 'Produto removido com sucesso!' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.store.products })
            }
            setDeleteModal({ open: false, id: '' })
        })
    }

    const filtered = products.filter(p => !search || p.name?.toLowerCase().includes(search.toLowerCase()))

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="CATÁLOGO DA LOJA"
                    subtitle="Gestão de itens da loja oficial, suplementação e equipamentos."
                    icon={ShoppingBag}
                    contextLabel="Painel Admin"
                    showTabs={false}
                >
                    <RegistrySection
                        title="Inventário Disponível"
                        subtitle="Gerencie os itens disponíveis na loja, preços e estoque."
                        icon={ShoppingBag}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            {/* Toolbar */}
                            <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <Box flex1>
                                    <Input 
                                        value={search}
                                        onChange={e => setSearch(e.target.value)}
                                        placeholder="Buscar produto..."
                                        icon={<Search size={16} />}
                                        rounded={STORE_TOKENS.RADIUS.FULL}
                                    />
                                </Box>
                                <Button
                                    onClick={() => { setEditingProduct(null); setProductModalOpen(true) }}
                                    variant="white"
                                    size="lg"
                                    rounded={STORE_TOKENS.RADIUS.FULL}
                                    shrink={0}
                                >
                                    <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Plus className="w-4 h-4" />
                                        <Box display={{base: 'none', md: 'block'}}>Novo Produto</Box>
                                    </Stack>
                                </Button>
                            </Stack>

                            {isLoading && <EmptyState icon={ShoppingBag} title="Carregando..." description="Buscando produtos da loja." />}

                            {!isLoading && (
                                <Grid cols={1} mdCols={2} lgCols={4} gap={STORE_TOKENS.SPACING.CONTAINER}>
                                    {filtered.map(product => (
                                        <ProductCard
                                            key={product.id}
                                            name={product.name}
                                            description={product.description}
                                            price={product.official_price ? `R$ ${Number(product.official_price).toFixed(2)}` : 'Sob consulta'}
                                            category={product.category}
                                            image={product.image_url}
                                            isActive={product.is_active}
                                            onToggleActive={() => handleProductToggle(product.id, product.is_active)}
                                            onDelete={() => handleDeleteProduct(product.id)}
                                            onEdit={() => { setEditingProduct(product); setProductModalOpen(true) }}
                                        />
                                    ))}
                                </Grid>
                            )}

                            {!isLoading && filtered.length === 0 && (
                                <EmptyState icon={Package} title="Nenhum produto encontrado" description="Adicione um novo produto ou ajuste a busca." />
                            )}
                        </Stack>
                    </RegistrySection>

                    <Modal
                        isOpen={deleteModal.open}
                        onClose={() => setDeleteModal({ ...deleteModal, open: false })}
                        title="Deletar Produto"
                        subtitle="Deseja remover este item permanentemente?"
                        icon={XCircle}
                        variant="red"
                        onConfirm={confirmDeleteProduct}
                        confirmLabel="Remover"
                    >
                        <Font variant="body" color={STORE_TOKENS.COLORS.TEXT.SECONDARY}>
                            Esta ação removerá o produto do catálogo e não poderá ser desfeita. Vendas anteriores permanecerão no histórico.
                        </Font>
                    </Modal>

                    <AdminProductEditor
                        isOpen={productModalOpen}
                        onClose={() => setProductModalOpen(false)}
                        product={editingProduct}
                        onImport={fetchProductFromUrl}
                        onSave={async (data: any) => {
                            startTransition(async () => {
                                const res = editingProduct
                                    ? await updateStoreProduct(editingProduct.id, data)
                                    : await addStoreProduct(data)
                                if ((res as any).error) toast({ variant: 'destructive', title: 'Erro', description: (res as any).error })
                                else {
                                    toast({ title: editingProduct ? 'Produto atualizado!' : 'Produto adicionado!' })
                                    queryClient.invalidateQueries({ queryKey: QUERY_KEYS.store.products })
                                    setProductModalOpen(false)
                                }
                            })
                        }}
                    />
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

'use client'

import { STORE_TOKENS } from '@/components/store/constants/tokens'

import { useState, useTransition } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import {
    getAllTrainers, updateUserPlanTier, impersonateUser, deleteUser
} from '@/actions/admin-actions'
import { createClient } from '@/lib/supabase/client'
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { DashboardShell } from '@/components/store/advanced/dashboard-shell'
import { RegistryMain } from '@/components/store/advanced/registry-main'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Modal } from '@/components/store/advanced/modal'
import { Stack } from '@/components/store/base/stack'
import { UserListItem } from '@/components/store/intermediary/user-list-item'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { Font } from '@/components/store/base/font'
import { Input } from '@/components/store/base/input'
import { useToast } from '@/hooks/use-toast'
import { UserCheck, Search, XCircle } from 'lucide-react'

export default function AdminPersonaisPage() {
    const queryClient = useQueryClient()
    const [search, setSearch] = useState('')
    const [isPending, startTransition] = useTransition()
    const [deleteModal, setDeleteModal] = useState<{ open: boolean, id: string, name: string }>({
        open: false,
        id: '',
        name: ''
    })
    const { toast } = useToast()

    const { data: trainers = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.admin.trainers,
        queryFn: () => getAllTrainers()
    })

    const { data: adminUser } = useQuery({
        queryKey: QUERY_KEYS.auth.user,
        queryFn: async () => {
            const supabase = createClient()
            const { data: { user: authUser } } = await supabase.auth.getUser()
            if (!authUser) return null
            const { data: profile } = await supabase.from('profiles').select('*').eq('id', authUser.id).single()
            return profile || authUser
        }
    })

    async function handleOnDemandToggle(userId: string, currentTier: string) {
        startTransition(async () => {
            const newTier = currentTier === 'on_demand' ? 'free' : 'on_demand'
            const res = await updateUserPlanTier(userId, newTier)
            if (res.error) toast({ variant: 'destructive', title: 'Erro', description: res.error })
            else {
                toast({ title: newTier === 'on_demand' ? 'Plano On-Demand ativado!' : 'Plano removido' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.trainers })
            }
        })
    }

    async function handleImpersonate(userId: string) {
        startTransition(async () => {
            const res = await impersonateUser(userId)
            if (res?.error) toast({ variant: 'destructive', title: 'Erro ao inspecionar', description: res.error })
        })
    }

    async function handleDeleteUser(userId: string, userName: string) {
        setDeleteModal({ open: true, id: userId, name: userName })
    }

    async function confirmDeleteUser() {
        if (!deleteModal.id) return
        startTransition(async () => {
            const res = await deleteUser(deleteModal.id)
            if (res.error) {
                toast({ variant: 'destructive', title: 'Erro', description: res.error })
            } else {
                toast({ title: 'Personal deletado com sucesso!' })
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.admin.trainers })
            }
            setDeleteModal({ open: false, id: '', name: '' })
        })
    }

    const filtered = trainers.filter(t => t.full_name?.toLowerCase().includes(search.toLowerCase()) || t.email?.toLowerCase().includes(search.toLowerCase()))

    return (
        <RegistryProvider defaultColor="red">
            <DashboardShell
                color={STORE_TOKENS.COLORS.ERROR}
                links={[
                    { href: '/admin/dashboard', label: 'Início', icon: 'BarChart3', exact: true },
                    { href: '/admin/personais', label: 'Personais', icon: 'UserCheck' },
                    { href: '/admin/alunos', label: 'Alunos', icon: 'Users' },
                    { href: '/admin/afiliados', label: 'Afiliados', icon: 'HeartHandshake' },
                    { href: '/admin/loja', label: 'Loja', icon: 'ShoppingBag' },
                    { href: '/admin/logs', label: 'Logs', icon: 'Activity' },
                ]}
                user={{
                    id: adminUser?.id || 'admin',
                    name: adminUser?.full_name || 'Admin RepTrail',
                    email: adminUser?.email || 'admin@reptrail.com.br',
                    avatar_url: adminUser?.avatar_url || null,
                    isAdmin: true,
                    isAffiliate: adminUser?.is_affiliate || false,
                }}
                profileHref="/dashboard"
                profileIcon="ArrowRightLeft"
            >
                <RegistryMain
                    title="GESTÃO DE PERSONAIS"
                    subtitle="Administração de profissionais parceiros e planos On-Demand."
                    icon={UserCheck}
                    contextLabel="Painel Admin"
                    showTabs={false}
                >
                    <RegistrySection
                        title="Diretório de Profissionais"
                        subtitle="Administre os profissionais parceiros e suas credenciais de acesso."
                        icon={UserCheck}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Input
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                placeholder="Buscar personal por nome ou email..."
                                icon={<Search size={16} />}
                                rounded={STORE_TOKENS.RADIUS.FULL}
                            />

                            {isLoading && <EmptyState icon={UserCheck} title="Carregando..." description="Buscando personais cadastrados." />}

                            {!isLoading && filtered.map(trainer => (
                                <UserListItem
                                    key={trainer.id}
                                    name={trainer.full_name || 'Sem nome'}
                                    email={trainer.email || ''}
                                    registrationDate={new Date(trainer.created_at).toLocaleDateString('pt-BR')}
                                    role="personal"
                                    roleLabel={trainer.students ? `${trainer.students.length} ALUNO${trainer.students.length !== 1 ? 'S' : ''}` : "0 ALUNOS"}
                                    initials={(trainer.full_name || '??').substring(0, 2).toUpperCase()}
                                    avatarVariant="orange"
                                    avatarUrl={trainer.avatar_url}
                                    onInspect={() => handleImpersonate(trainer.id)}
                                    onAction={() => handleOnDemandToggle(trainer.id, trainer.plan_tier || 'free')}
                                    isActionActive={trainer.plan_tier === 'on_demand'}
                                    onDelete={() => handleDeleteUser(trainer.id, trainer.full_name || trainer.email)}
                                />
                            ))}

                            {!isLoading && filtered.length === 0 && (
                                <EmptyState icon={Search} title="Nenhum personal encontrado" description="Tente ajustar os filtros de busca." />
                            )}
                        </Stack>
                    </RegistrySection>

                    <Modal
                        isOpen={deleteModal.open}
                        onClose={() => setDeleteModal({ ...deleteModal, open: false })}
                        title="Deletar Personal"
                        subtitle={`Deseja deletar permanentemente ${deleteModal.name}?`}
                        icon={XCircle}
                        variant="red"
                        onConfirm={confirmDeleteUser}
                        confirmLabel="Deletar"
                    >
                        <Font variant="body" color={STORE_TOKENS.COLORS.TEXT.SECONDARY}>
                            Esta ação é irreversível e removerá todos os dados do profissional, incluindo acesso à plataforma de gestão.
                        </Font>
                    </Modal>
                </RegistryMain>
            </DashboardShell>
        </RegistryProvider>
    );
}

'use client';
import { STORE_TOKENS } from '@/components/store/constants/tokens';

import { useState, Suspense } from 'react'
import { useRouter } from 'next/navigation'
import { loginAndActivateAffiliate } from '@/actions/affiliate-actions'

// Design System V2 Components
import { RegistryProvider } from '@/components/store/advanced/registry-context'
import { AuthShell } from '@/components/store/advanced/auth-shell'
import { AuthLoginForm } from '@/components/store/advanced/auth-login-form'


export default function AffiliadosLoginPage() {
    const router = useRouter()

    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState<string | null>(null)

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        setError(null)

        const result = await loginAndActivateAffiliate(email, password)

        if (result.error) {
            setError(result.error)
            setLoading(false)
            return
        }

        router.replace('/dashboard/affiliate')
    }

    return (
        <RegistryProvider defaultColor="amber">
            <AuthShell>
                <Suspense fallback={null}>
                    <AuthLoginForm 
                        email={email}
                        setEmail={setEmail}
                        password={password}
                        setPassword={setPassword}
                        onSubmit={handleSubmit}
                        loading={loading}
                        error={error}
                        color={STORE_TOKENS.COLORS.WARNING}
                        signupHref="/afiliados/cadastro"
                    />
                </Suspense>
            </AuthShell>
        </RegistryProvider>
    );
}

