// Design System Primitives
import { Surface } from '@/components/store/base/surface'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Badge } from '@/components/store/base/badge'
import { Icon } from '@/components/store/base/icon'
import { Scaffold } from '@/components/store/base/main'
import { Button } from '@/components/store/base/button'
import { BackgroundEffects } from '@/components/store/base/background-effects'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

export default function WorkoutPlayerClient({
    userId,
    workoutId,
    isForced = false
}: {
    userId: string,
    workoutId: string,
    isForced?: boolean
}) {
    // ─── DATA FETCHING (LOCAL-FIRST ELITE) ───────────────────────────────────
    const { data: workoutData, isLoading: workoutLoading } = useWorkoutWithExercises(workoutId)

    const { data: logsStatus, isLoading: logsLoading } = useWorkoutStatus(userId, workoutId)

    const { data: activeSession, isLoading: activeLoading } = useActiveWorkoutSession()

    const [isResting, setIsResting] = useState(false)

    if (workoutLoading || logsLoading || activeLoading) {
        return null
    }

    if (!workoutData) return notFound()

    const workout = workoutData
    const exercises = workoutData.workout_exercises || workoutData.exercises || []

    if (exercises.length === 0) {
        return (
            <Box display="flex" align="center" justify="center" minHeight="screen" width="full">
                <BackgroundEffects variant="all" />
                {/* eslint-disable-next-line no-restricted-syntax */}
                <Stack align="center" justify="center" gap={STORE_TOKENS.SPACING.CONTAINER} position="relative" zIndex={10} padding={STORE_TOKENS.PADDING.CONTAINER}>
                    <Surface variant="glass" padding={STORE_TOKENS.PADDING.CONTAINER} rounded={STORE_TOKENS.RADIUS.FULL} border="standard">
                        <Box>
                            <Icon icon={Dumbbell} size="lg" color={STORE_TOKENS.COLORS.TEXT.DIM} />
                        </Box>
                    </Surface>
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                        <Font variant="h3" weight="black" uppercase italic tracking="tight">Sem exercícios</Font>
                        <Font variant="sub-tiny" color={STORE_TOKENS.COLORS.TEXT.MUTED} weight="black" uppercase tracking="widest" align="center">
                            Este treino ainda não possui exercícios cadastrados.
                        </Font>
                    </Stack>
                </Stack>
            </Box>
        )
    }

    if (logsStatus?.status === 'completed' && !isForced) {
        return (
            <Box display="flex" align="center" justify="center" minHeight="screen" width="full">
                <BackgroundEffects variant="all" />
                {/* eslint-disable-next-line no-restricted-syntax */}
                <Box position="relative" zIndex={10} width="full" padding={STORE_TOKENS.PADDING.CONTAINER}>
                    <MissionCompletedView />
                </Box>
            </Box>
        )
    }

    let initialExerciseIndex = 0
    let initialLogId: string | undefined = undefined
    let initialSet = 1
    let initialSetType: 'WARMUP' | 'FEEDER' | 'WORKING' | undefined = undefined
    let initialIsResting = false
    let initialRestEndTime: number | undefined = undefined

    if (activeSession && activeSession.workout_id === workoutId) {
        initialLogId = activeSession.id
        if (activeSession.current_state) {
            const state = activeSession.current_state as any
            initialExerciseIndex = state.exerciseIndex || 0
            initialSet = state.set || 1
            initialSetType = state.type
            initialIsResting = state.isResting || false
            initialRestEndTime = state.restEndTime
        }
    }

    return (
        <Scaffold
            position={{ base: 'fixed', md: 'relative' }}
            pin={{ base: 'inset', md: undefined }}
            zIndex={STORE_TOKENS.Z_INDEX.OVERLAY}
            minHeight="screen"
            display="flex"
            direction="col"
            bg={STORE_TOKENS.COLORS.BACKGROUND}
            overflowY="auto"
            paddingLeft={{ base: 'none', md: 'sidebar-wide' }}
        >
            {/* Background Effects: Grid & Orbs */}
            <BackgroundEffects variant="all" />

            {/* Header: Full-width sticky bar */}
            {!isResting && (
                // eslint-disable-next-line no-restricted-syntax
                <Box position="sticky" top={0} zIndex={50} width="full">
                    <Surface variant="glass" border="standard" padding={STORE_TOKENS.PADDING.CONTAINER} rounded={STORE_TOKENS.RADIUS.NONE}>
                        <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                            {/* Mobile Top Bar: Badge + Back Button */}
                            <Box display={{ base: 'flex', md: 'none' }} justify="between" fullWidth direction="row" align="center">
                                <Badge
                                    label="Em progresso"
                                    variant="glass"
                                    color={STORE_TOKENS.COLORS.SUCCESS}
                                    icon={Activity}
                                    animatePulse
                                />
                                <Link href="/dashboard/student" passHref>
                                    <Button variant="outline-zinc" size="sm" rounded={STORE_TOKENS.RADIUS.FULL}>
                                        <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                            <Icon icon={ArrowLeft} size="xs" />
                                            <Font variant="sub-tiny" weight="black" uppercase tracking="wider">Voltar</Font>
                                        </Stack>
                                    </Button>
                                </Link>
                            </Box>

                            <Stack direction="row" align="center" justify="between">
                                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                    <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Box width={8} height={8} bg={STORE_TOKENS.COLORS.SUCCESS} rounded={STORE_TOKENS.RADIUS.FULL} style={{ boxShadow: '0 0 10px rgba(16,185,129,0.5)' }} />
                                        <Font variant="h3" weight="black" color={STORE_TOKENS.COLORS.WHITE} uppercase italic tracking="tight" truncate>
                                            {workout.name}
                                        </Font>
                                    </Stack>
                                    <Box>
                                        <Font variant="tiny" color={STORE_TOKENS.COLORS.TEXT.MUTED} weight="black" uppercase tracking="widest">
                                            Player de Treino • Foco e Intensidade
                                        </Font>
                                    </Box>
                                </Stack>

                                {/* Desktop Badge */}
                                <Box display={{ base: 'none', md: 'block' }}>
                                    <Badge
                                        label="Em progresso"
                                        variant="glass"
                                        color={STORE_TOKENS.COLORS.SUCCESS}
                                        icon={Activity}
                                        animatePulse
                                    />
                                </Box>
                            </Stack>
                        </Stack>
                    </Surface>
                </Box>
            )}

            {/* Main Player Content: Vertically Centered */}
            {/* eslint-disable-next-line no-restricted-syntax */}
            <Box flex1 display="flex" align={{ base: 'start', md: 'center' }} justify="center" padding={STORE_TOKENS.PADDING.NONE} position="relative" zIndex={10}>
                <WorkoutPlayer
                    userId={userId}
                    workout={workout}
                    exercises={exercises}
                    initialExerciseIndex={initialExerciseIndex}
                    initialLogId={initialLogId}
                    initialSet={initialSet}
                    initialSetType={initialSetType}
                    initialIsResting={initialIsResting}
                    initialRestEndTime={initialRestEndTime}
                    onRestChange={setIsResting}
                />
            </Box>
        </Scaffold>
    )
}

