export default async function TrainerPublicProfilePage({
    params,
}: {
    params: Promise<{ slug: string }>
}) {
    const { slug } = await params
    const supabase = await createClient()
    const headerList = await headers()
    const viewerId = headerList.get('x-user-id')

    // Normalize slug - remove null, undefined, or empty strings
    const normalizedSlug = slug?.trim().toUpperCase() || ''

    if (!normalizedSlug || normalizedSlug === 'NULL' || normalizedSlug === 'UNDEFINED') {
        notFound()
    }

    // Use the RPC to fetch all data at once securely
    const { data: publicData, error: rpcError } = await supabase
        .rpc('get_trainer_public_profile', { trainer_slug: normalizedSlug })

    if (rpcError || !publicData) {
        console.error('Error fetching public profile via RPC:', rpcError)
        notFound()
    }

    const { trainer, reviews, photos } = publicData

    if (!trainer || !trainer.trainer_code) {
        notFound()
    }

    // ── Get Viewer Profile if Logged In (to determine sidebar role/color) ───────
    let viewerProfile: any = null
    if (viewerId) {
        const { data } = await supabase
            .from('profiles')
            .select('role, full_name, avatar_url, email, is_admin, is_affiliate')
            .eq('id', viewerId)
            .single()
        viewerProfile = data
    }

    // ── Enforce default trainer 'emerald' theme for content elements ───────────
    const mainContent = (
        <RegistryProvider defaultColor="emerald">
            <RegistryMain
                title="PERFIL DO TREINADOR"
                subtitle="Acompanhe a biografia, metodologia, depoimentos e transformações do seu coach."
                icon="UserCheck"
                contextLabel="Perfil Público"
                showTabs={false}
            >
                <TrainerPublicProfileMain
                    trainer={trainer}
                    reviews={reviews || []}
                    photos={photos || []}
                />
            </RegistryMain>
        </RegistryProvider>
    )

    // ── Render with Sidebar Shell if Logged In, otherwise render pure page ──────
    if (viewerProfile) {
        const isTrainer = viewerProfile.role === 'trainer'
        const shellColor = isTrainer ? 'emerald' : 'orange'
        const links = isTrainer ? TRAINER_LINKS : STUDENT_LINKS
        const mobileLinks = isTrainer ? TRAINER_MOBILE_LINKS : STUDENT_MOBILE_LINKS
        const profileHref = isTrainer ? '/dashboard/trainer/profile' : '/dashboard/student/profile'

        return (
            <RegistryProvider defaultColor={shellColor}>
                <DashboardShell
                    color={shellColor}
                    links={links}
                    mobileLinks={mobileLinks}
                    profileHref={profileHref}
                    user={{
                        id: viewerId!,
                        name: viewerProfile.full_name,
                        email: viewerProfile.email,
                        avatar_url: viewerProfile.avatar_url,
                        isAdmin: viewerProfile.is_admin,
                        isAffiliate: viewerProfile.is_affiliate,
                    }}
                >
                    {mainContent}
                </DashboardShell>
            </RegistryProvider>
        )
    }

    return (
        <Surface
            minHeight="screen"
            bg={STORE_TOKENS.COLORS.BACKGROUND}
            bgOpacity={STORE_TOKENS.OPACITY.BACKGROUND}
            overflowX="hidden"
            display="flex"
            direction="col"
            position="relative"
        >
            <BackgroundEffects variant="all" />
            <Box position="relative" zIndex={STORE_TOKENS.Z_INDEX.CONTENT} flex1>
                {mainContent}
            </Box>
        </Surface>
    );
}

'use client'

import { useEffect } from 'react'
import { ActivityItem, getTrainerActivityFeed } from '@/actions/trainer-actions'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { createClient, removeChannelWithGrace } from '@/lib/supabase/client'
import {
    Clock,
    Activity as ActivityIcon
} from 'lucide-react'

// Design System imports
import { GlassPanel, CardHeader, CardContent } from '@/components/store/base/surface'
import { Box } from '@/components/store/base/box'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Inline } from '@/components/store/base/layout'
import { IconBox } from '@/components/store/base/icon'
import { Badge } from '@/components/store/base/badge'
import { BaseAvatar } from '@/components/store/base/avatar'
import { ActionableListCard } from '@/components/store/intermediary/actionable-list-card'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

interface ActivityFeedProps {
    userId: string
    initialData?: ActivityItem[]
}

export function ActivityFeed({ userId, initialData }: ActivityFeedProps) {
    const queryClient = useQueryClient()
    const supabase = createClient()

    const { data: activities = [] } = useQuery({
        queryKey: QUERY_KEYS.trainer.activity(userId),
        queryFn: () => getTrainerActivityFeed(userId),
        initialData
    })

    // ─── Realtime Logic ──────────────────────────────────────────────────────
    useEffect(() => {
        const channel = supabase
            .channel('trainer-activity-refetch')
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'workout_logs' },
                () => queryClient.invalidateQueries({ queryKey: QUERY_KEYS.trainer.activity(userId) })
            )
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'meal_logs' },
                () => queryClient.invalidateQueries({ queryKey: QUERY_KEYS.trainer.activity(userId) })
            )
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'cardio_logs' },
                () => queryClient.invalidateQueries({ queryKey: QUERY_KEYS.trainer.activity(userId) })
            )
            .subscribe()

        return () => {
            removeChannelWithGrace(supabase, channel)
        }
    }, [supabase, queryClient, userId])

    // Render all activities and let the custom scrollbar handle the overflow limit dynamically

    const getTypeStyles = (type: string, subType?: string) => {
        switch (type) {
            case 'workout':
                if (subType === 'started') return { color: 'blue', label: 'Iniciou' }
                if (subType === 'success') return { color: 'orange', label: 'Sucesso' }
                if (subType === 'partial') return { color: 'orange', label: 'Parcial' }
                if (subType === 'fail') return { color: 'red', label: 'Falhou' }
                if (subType === 'note') return { color: 'zinc', label: 'Nota' }
                return { color: 'orange', label: 'Treinou' }
            case 'meal':
                return { color: 'orange', label: 'Dieta' }
            case 'cardio':
                if (subType === 'started') return { color: 'blue', label: 'Iniciou' }
                return { color: 'orange', label: 'Cardio' }
            case 'weight':
                return { color: 'zinc', label: 'Peso' }
            case 'photo':
                return { color: 'zinc', label: 'Foto' }
            case 'ergogenic':
                return { color: 'orange', label: 'Ergo' }
            case 'milestone':
                return { color: 'amber', label: 'Meta 100%' }
            case 'alert':
                return { color: 'orange', label: 'Modo Ilha' }
            default:
                return { color: 'zinc', label: 'Atividade' }
        }
    }

    const formatRelativeTime = (timestamp: string) => {
        const date = new Date(timestamp)
        const diff = Date.now() - date.getTime()
        const mins = Math.floor(diff / 60000)
        const hours = Math.floor(mins / 60)
        const days = Math.floor(hours / 24)

        if (mins < 1) return 'Agora mesmo'
        if (mins < 60) return `Há ${mins} min`
        if (hours < 24) return `Há ${hours} hr`
        return `Há ${days} d`
    }

    return (
        <GlassPanel fullWidth padding={STORE_TOKENS.PADDING.NONE} display="flex" direction="col" flex1>
            <CardHeader>
                <Inline justify="between" fullWidth>
                    <Inline gap={STORE_TOKENS.SPACING.ELEMENT}>
                        <IconBox
                            icon={ActivityIcon}
                            variant="primary"
                            size="md"
                            rounded={STORE_TOKENS.RADIUS.SYSTEM}
                        />
                        <Font variant="heading" weight="black" uppercase italic>
                            Atividade Recente
                        </Font>
                    </Inline>
                </Inline>
            </CardHeader>
            <CardContent
                flex1
                display="flex"
                direction="col"
                {...{
                    padding: "none",
                    minHeight: 0,
                }}>
                <Box
                    fullWidth
                    display="flex"
                    direction="col"
                >
                    {activities.length > 0 ? (
                        <Stack gap={STORE_TOKENS.SPACING.ELEMENT} padding={STORE_TOKENS.PADDING.CONTAINER} fullWidth>
                            {activities.map((activity) => {
                                const { color, label } = getTypeStyles(activity.type, activity.subType)
                                const initials = activity.studentName ? activity.studentName.substring(0, 2).toUpperCase() : 'AL'
                                return (
                                    <ActionableListCard
                                        key={activity.id}
                                        badges={
                                            <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                                <Badge
                                                    label={label}
                                                    color={color as any}
                                                    variant="glass"
                                                    size="xs"
                                                />
                                                <Badge
                                                    label={formatRelativeTime(activity.timestamp)}
                                                    color={STORE_TOKENS.COLORS.BACKGROUND}
                                                    variant="glass"
                                                    size="xs"
                                                    icon={Clock}
                                                />
                                            </Inline>
                                        }
                                    >
                                        {/* Mobile Layout */}
                                        <Box display={{ base: 'flex', lg: 'none' }} direction="col" gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth>
                                            <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                                <BaseAvatar
                                                    initials={initials}
                                                    src={activity.studentAvatar || undefined}
                                                    size="sm"
                                                    variant="zinc"
                                                />
                                                <Font
                                                    variant="body-sm"
                                                    weight="black"
                                                    uppercase
                                                    italic
                                                    {...{
                                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                    }}>
                                                    {activity.studentName}
                                                </Font>
                                            </Inline>
                                            <Font
                                                variant="sub-tiny"
                                                weight="bold"
                                                uppercase
                                                tracking="wide"
                                                {...{
                                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                                }}>
                                                {activity.contentName}
                                            </Font>
                                        </Box>
                                        {/* Desktop Layout */}
                                        <Box display={{ base: 'none', lg: 'flex' }} align="center" gap={STORE_TOKENS.SPACING.CONTAINER}>
                                            <BaseAvatar
                                                initials={initials}
                                                src={activity.studentAvatar || undefined}
                                                size="sm"
                                                variant="zinc"
                                            />
                                            <Stack gap={STORE_TOKENS.SPACING.NONE}>
                                                <Font
                                                    variant="body-sm"
                                                    weight="black"
                                                    uppercase
                                                    italic
                                                    {...{
                                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                    }}>
                                                    {activity.studentName}
                                                </Font>
                                                <Font
                                                    variant="sub-tiny"
                                                    weight="bold"
                                                    uppercase
                                                    tracking="wide"
                                                    {...{
                                                        color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                                    }}>
                                                    {activity.contentName}
                                                </Font>
                                            </Stack>
                                        </Box>
                                    </ActionableListCard>
                                );
                            })}
                        </Stack>
                    ) : (
                        <Box padding={STORE_TOKENS.PADDING.CONTAINER} fullWidth>
                            <EmptyState
                                icon={Clock}
                                title="Nenhuma Atividade"
                                description="Nenhuma atividade registrada hoje por seus alunos."
                            />
                        </Box>
                    )}
                </Box>
            </CardContent>
        </GlassPanel>
    );
}

'use client'

import React, { useState } from 'react'
import { getAdminAffiliates, removeAffiliate } from '@/actions/admin-affiliate-actions'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Input } from '@/components/store/base/input'
import { Modal } from '@/components/store/advanced/modal'
import { AffiliateListItem } from '@/components/store/intermediary/affiliate-list-item'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { HeartHandshake, Search, XCircle } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { useToast } from '@/hooks/use-toast'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

/**
 * AdminAffiliatesList: Encapsulates the logic for managing the affiliates list.
 * - Handles data fetching, searching, and status removal.
 * - Manages the confirmation modal for removal.
 * - Responsibility: Affiliates domain logic and interaction.
 */
export function AdminAffiliatesList() {
    const { toast } = useToast()
    const [search, setSearch] = useState('')
    const [deleteModal, setDeleteModal] = useState({ open: false, id: '', name: '' })

    const { data: affiliatesData, isLoading, refetch } = useQuery({
        queryKey: ['admin-affiliates'],
        queryFn: () => getAdminAffiliates()
    })

    const affiliates = (affiliatesData?.data || [])
        .filter((a: any) =>
            !search ||
            a.full_name?.toLowerCase().includes(search.toLowerCase()) ||
            a.email?.toLowerCase().includes(search.toLowerCase())
        )

    const handleRemoveAffiliate = (id: string, name: string) => {
        setDeleteModal({ open: true, id, name })
    }

    const confirmRemoveAffiliate = async () => {
        try {
            await removeAffiliate(deleteModal.id)
            toast({ title: 'Afiliado removido', description: `${deleteModal.name} não é mais um afiliado.` })
            refetch()
        } catch (error) {
            toast({ variant: 'destructive', title: 'Erro ao remover', description: 'Não foi possível processar a solicitação.' })
        } finally {
            setDeleteModal({ open: false, id: '', name: '' })
        }
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
            <Input
                placeholder="Buscar por nome ou email..."
                value={search}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)}
                icon={<Search size={18} />}
            />
            {isLoading ? (
                <EmptyState
                    icon={HeartHandshake}
                    title="Carregando..."
                    description="Buscando parceiros cadastrados."
                />
            ) : affiliates.length === 0 ? (
                <EmptyState
                    icon={HeartHandshake}
                    title={search ? "Nenhum resultado" : "Nenhum afiliado ativo"}
                    description={search ? "Tente ajustar sua busca." : "Utilize o painel de afiliados para adicionar novos parceiros comerciais."}
                />
            ) : (
                affiliates.map((affiliate: any) => (
                    <AffiliateListItem
                        key={affiliate.id}
                        affiliateId={affiliate.id}
                        name={affiliate.full_name || 'Usuário sem nome'}
                        email={affiliate.email || ''}
                        registrationDate={new Date(affiliate.created_at).toLocaleDateString('pt-BR')}
                        referrals={{
                            total: affiliate.total_referrals || 0,
                            active: affiliate.active_referrals || 0,
                        }}
                        revenue={`R$ ${Number(affiliate.revenue_generated || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                        commission={`R$ ${Number(affiliate.monthly_commission || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                        rate={affiliate.commission_rate ?? 10}
                        onDelete={() => handleRemoveAffiliate(affiliate.id, affiliate.full_name || 'afiliado')}
                    />
                ))
            )}
            <Modal
                isOpen={deleteModal.open}
                onClose={() => setDeleteModal({ ...deleteModal, open: false })}
                title="Remover Afiliado"
                subtitle={`Deseja remover o status de afiliado de ${deleteModal.name}?`}
                icon={XCircle}
                variant="red"
                onConfirm={confirmRemoveAffiliate}
                confirmLabel="Remover"
            >
                <Font
                    variant="body"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                    }}>
                    Esta ação removerá imediatamente o acesso do usuário ao painel de afiliado e interromperá o rastreamento de novas comissões.
                </Font>
            </Modal>
        </Stack>
    );
}

'use client'

import { useState, useEffect } from 'react'
import { Plus, Trash2, TrendingDown, Edit3 } from 'lucide-react'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Button } from '@/components/store/base/button'
import { Badge } from '@/components/store/base/badge'
import { Inline } from '@/components/store/base/layout'
import { Modal } from '@/components/store/advanced/modal'
import { addOperationalCost, deleteOperationalCost, updateOperationalCost } from '@/actions/admin-actions'
import { useToast } from '@/hooks/use-toast'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { ENTITIES } from '@/lib/outbox-db'
import { ActionableListCard } from '../intermediary/actionable-list-card'
import { EmptyState } from '../intermediary/empty-state'
import { ActionIconButton } from '../intermediary/action-icon-button'
import { CircleIcon } from '../intermediary/circle-icon'
import { OperationalCostForm } from '../intermediary/operational-cost-form'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

interface OperationalCost {
    id: string
    description: string
    amount: number
    type: 'fixed' | 'variable'
    created_at: string
}

/**
 * AdminOperationalCostsPanel: Encapsulates all operational cost management logic.
 * - Handles state for costs, modals, and forms.
 * - Manages optimistic mutations for CRUD operations.
 * - Follows strict Design System governance.
 */
export function AdminOperationalCostsPanel({ initialCosts }: { initialCosts: OperationalCost[] }) {
    const { toast } = useToast()
    const [costs, setCosts] = useState<OperationalCost[]>(initialCosts)

    useEffect(() => {
        setCosts(initialCosts)
    }, [initialCosts])

    const [isAddModalOpen, setIsAddModalOpen] = useState(false)
    const [isEditModalOpen, setIsEditModalOpen] = useState(false)
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false)
    const [selectedCost, setSelectedCost] = useState<OperationalCost | null>(null)
    
    // Form state
    const [description, setDescription] = useState('')
    const [amount, setAmount] = useState('')
    const [type, setType] = useState<'fixed' | 'variable'>('fixed')

    const { mutate: addCostMutate } = useOptimisticMutation({
        actionName: 'add-operational-cost',
        entity: ENTITIES.OPERATIONAL_COST,
        queryKey: ['admin', 'operational-costs'],
        additionalQueryKeys: [['admin', 'overview']],
        mutationFn: async (variables: any) => (await addOperationalCost(variables)) as any,
        onMutate: (variables) => {
            const tempId = crypto.randomUUID()
            const newCost = { ...variables, id: tempId, created_at: new Date().toISOString() }
            setCosts(prev => [newCost, ...prev])
            setIsAddModalOpen(false)
            resetForm()
            return { tempId }
        },
        onSuccess: () => {
            toast({ title: 'Sucesso', description: 'Custo adicionado localmente.' })
        },
        onError: (err, variables, ctx) => {
            setCosts(prev => prev.filter(c => c.id !== ctx?.tempId))
            toast({ title: 'Erro', description: 'Erro ao adicionar custo.', variant: 'destructive' })
        }
    })

    const { mutate: deleteCostMutate } = useOptimisticMutation({
        actionName: 'delete-operational-cost',
        entity: ENTITIES.OPERATIONAL_COST,
        queryKey: ['admin', 'operational-costs'],
        additionalQueryKeys: [['admin', 'overview']],
        mutationFn: async (variables: { id: string }) => (await deleteOperationalCost(variables.id)) as any,
        onMutate: (variables) => {
            const previousCosts = [...costs]
            setCosts(prev => prev.filter(c => c.id !== variables.id))
            setIsDeleteModalOpen(false)
            return { previousCosts }
        },
        onSuccess: () => {
            toast({ title: 'Sucesso', description: 'Custo removido localmente.' })
        },
        onError: (err, variables, ctx) => {
            setCosts(ctx?.previousCosts || [])
            toast({ title: 'Erro', description: 'Erro ao deletar custo.', variant: 'destructive' })
        }
    })

    const { mutate: updateCostMutate } = useOptimisticMutation({
        actionName: 'update-operational-cost',
        entity: ENTITIES.OPERATIONAL_COST,
        queryKey: ['admin', 'operational-costs'],
        additionalQueryKeys: [['admin', 'overview']],
        mutationFn: async (variables: any) => (await updateOperationalCost(variables.id, variables)) as any,
        onMutate: (variables) => {
            const previousCosts = [...costs]
            setCosts(prev => prev.map(c => c.id === variables.id ? { ...c, ...variables } : c))
            setIsEditModalOpen(false)
            return { previousCosts }
        },
        onSuccess: () => {
            toast({ title: 'Sucesso', description: 'Custo atualizado localmente.' })
        },
        onError: (err, variables, ctx) => {
            setCosts(ctx?.previousCosts || [])
            toast({ title: 'Erro', description: 'Erro ao atualizar custo.', variant: 'destructive' })
        }
    })

    function resetForm() {
        setDescription('')
        setAmount('')
        setType('fixed')
    }

    function handleAddCost() {
        if (!description || !amount) return toast({ title: 'Erro', description: 'Preencha todos os campos', variant: 'destructive' })
        const numericAmount = parseFloat(amount.replace(',', '.'))
        addCostMutate({ description, amount: numericAmount, type })
    }

    function handleEditCost() {
        if (!selectedCost || !description || !amount) return toast({ title: 'Erro', description: 'Preencha todos os campos', variant: 'destructive' })
        const numericAmount = parseFloat(amount.replace(',', '.'))
        updateCostMutate({ id: selectedCost.id, description, amount: numericAmount, type })
    }

    function openDeleteModal(cost: OperationalCost) {
        setSelectedCost(cost)
        setIsDeleteModalOpen(true)
    }

    function openEditModal(cost: OperationalCost) {
        setSelectedCost(cost)
        setDescription(cost.description)
        setAmount(cost.amount.toString())
        setType(cost.type)
        setIsEditModalOpen(true)
    }

    const totalMonthly = costs.reduce((sum, c) => sum + Number(c.amount), 0)

    return (
        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
            <Stack direction="row" justify="end" align="center" gap={STORE_TOKENS.SPACING.CONTAINER}>
                <Badge
                    label={`R$ ${totalMonthly.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} / mês`}
                    color={STORE_TOKENS.COLORS.SUCCESS}
                    variant="solid"
                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                    size="md"
                />
                <Button
                    variant="outline-red"
                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                    onClick={() => {
                        resetForm()
                        setIsAddModalOpen(true)
                    }}
                    paddingX={STORE_TOKENS.PADDING.CONTAINER}
                    size="md"
                >
                    <Stack direction="row" gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                        <Icon icon={Plus} size="sm" />
                        <Font variant="label-caps">Adicionar Custo</Font>
                    </Stack>
                </Button>
            </Stack>
            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                {costs.map((cost) => {
                    const badgeColor = cost.type === 'fixed' ? STORE_TOKENS.COLORS.INFO : STORE_TOKENS.COLORS.BRAND;
                    return (
                    <ActionableListCard
                        key={cost.id}
                        badges={
                            <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                <Badge
                                    label={new Date(cost.created_at).toLocaleDateString('pt-BR')}
                                    variant="glass"
                                    size="xs"
                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                />
                                <Badge
                                    label={cost.type === 'fixed' ? 'Fixo' : 'Variável'}
                                    variant="glass"
                                    color={badgeColor}
                                    size="xs"
                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                />
                            </Inline>
                        }
                        actions={
                            <>
                                <ActionIconButton
                                    icon={Edit3}
                                    variant="outline-blue"
                                    onClick={() => openEditModal(cost)}
                                />
                                <ActionIconButton
                                    icon={Trash2}
                                    variant="outline-red"
                                    onClick={() => openDeleteModal(cost)}
                                />
                            </>
                        }
                    >
                        <Inline gap={STORE_TOKENS.SPACING.CONTAINER} align="center">
                            <CircleIcon
                                icon={TrendingDown}
                                size="sm"
                                // eslint-disable-next-line no-restricted-syntax
                                color={cost.type === 'fixed' ? 'blue' : 'orange'}
                            />
                            <Stack gap={STORE_TOKENS.SPACING.NONE} minWidth={0}>
                                <Font
                                    weight="black"
                                    uppercase
                                    italic
                                    variant={{ base: 'body-sm', md: 'body' }}
                                    tracking="wider"
                                    truncate
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                    }}>
                                    {cost.description}
                                </Font>
                                <Box fullWidth minWidth={0} overflow="hidden">
                                    <Font
                                        variant="sub-tiny"
                                        uppercase
                                        tracking="widest"
                                        {...{
                                            color: STORE_TOKENS.COLORS.TEXT.DIM,
                                        }}>
                                        - R$ {Number(cost.amount).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                                    </Font>
                                </Box>
                            </Stack>
                        </Inline>
                    </ActionableListCard>
                    );
                })}

                {costs.length === 0 && (
                    <EmptyState
                        icon={TrendingDown}
                        title="Sem Custos"
                        description="Nenhum custo operacional cadastrado no momento."
                    />
                )}
            </Stack>
            <Modal
                isOpen={isAddModalOpen}
                onClose={() => setIsAddModalOpen(false)}
                title="Adicionar Custo"
                subtitle="Registre gastos de infraestrutura ou marketing."
                icon={TrendingDown}
                confirmLabel="Salvar Custo"
                onConfirm={handleAddCost}
                variant="red"
            >
                <OperationalCostForm 
                    description={description} setDescription={setDescription}
                    amount={amount} setAmount={setAmount}
                    type={type} setType={setType}
                />
            </Modal>
            <Modal
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                title="Editar Custo"
                subtitle={`Modificando: ${selectedCost?.description}`}
                icon={Edit3}
                confirmLabel="Salvar Alterações"
                onConfirm={handleEditCost}
                variant="blue"
            >
                <OperationalCostForm 
                    description={description} setDescription={setDescription}
                    amount={amount} setAmount={setAmount}
                    type={type} setType={setType}
                />
            </Modal>
            <Modal
                isOpen={isDeleteModalOpen}
                onClose={() => setIsDeleteModalOpen(false)}
                title="Confirmar Exclusão"
                subtitle={`Deseja realmente apagar o custo: ${selectedCost?.description}?`}
                icon={Trash2}
                variant="red"
                confirmLabel="Sim, Excluir"
                onConfirm={() => deleteCostMutate({ id: selectedCost?.id || '' })}
            >
                <Font
                    variant="description"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                    }}>
                    Esta ação não pode ser desfeita e removerá o registro permanentemente do sistema.
                </Font>
            </Modal>
        </Stack>
    );
}

