                        placeholder="Ex: Servidor, Domínio, Marketing..."
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                    />
                    <Stack direction="row" gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Box flex1>
                            <Input
                                label="Valor (R$)"
                                type="number"
                                placeholder="0,00"
                                value={amount}
                                onChange={(e) => setAmount(e.target.value)}
                            />
                        </Box>
                        <Box flex1>
                            <FormSelect
                                label="Tipo de Custo"
                                options={[
                                    { label: 'Fixo', value: 'fixed', description: 'Gastos recorrentes mensais' },
                                    { label: 'Variável', value: 'variable', description: 'Gastos esporádicos' }
                                ]}
                                value={type}
                                onChange={(val: any) => setType(val)}
                            />
                        </Box>
                    </Stack>
                </Stack>
            </Modal>
            {/* Modal de Edição */}
            <Modal
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                title="Editar Custo"
                subtitle={`Modificando: ${selectedCost?.description}`}
                icon={Edit3}
                confirmLabel="Salvar Alterações"
                onConfirm={handleEditCost}
                variant="blue"
            >
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    <Input
                        label="Descrição"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                    />
                    <Stack direction="row" gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Box flex1>
                            <Input
                                label="Valor (R$)"
                                type="number"
                                value={amount}
                                onChange={(e) => setAmount(e.target.value)}
                            />
                        </Box>
                        <Box flex1>
                            <FormSelect
                                label="Tipo de Custo"
                                options={[
                                    { label: 'Fixo', value: 'fixed', description: 'Gastos recorrentes mensais' },
                                    { label: 'Variável', value: 'variable', description: 'Gastos esporádicos' }
                                ]}
                                value={type}
                                onChange={(val: any) => setType(val)}
                            />
                        </Box>
                    </Stack>
                </Stack>
            </Modal>
            {/* Modal de Exclusão */}
            <Modal
                isOpen={isDeleteModalOpen}
                onClose={() => setIsDeleteModalOpen(false)}
                title="Confirmar Exclusão"
                subtitle={`Deseja realmente apagar o custo: ${selectedCost?.description}?`}
                icon={Trash2}
                variant="red"
                confirmLabel="Sim, Excluir"
                onConfirm={() => deleteCostMutate({ id: selectedCost?.id || '' })}
            >
                <Font
                    variant="description"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                    }}>
                    Esta ação não pode ser desfeita e removerá o registro permanentemente do sistema.
                </Font>
            </Modal>
        </Stack>
    );
}

'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTopProductsByClicks } from '@/actions/admin-actions'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Badge } from '@/components/store/base/badge'
import { GlassPanel } from '@/components/store/base/surface'
import { ShoppingBag, MousePointer2 } from 'lucide-react'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { Img } from '@/components/store/base/img'
import { Icon } from '@/components/store/base/icon'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

/**
 * AdminTopProductsPanel: Manages the logic for fetching and displaying top products.
 * - Handles the ranking logic and responsive rendering.
 * - Encapsulates the visual complexity of product cards.
 * - Follows "Zero-Manual-Styling" governance by avoiding arbitrary Tailwind classes.
 */
export function AdminTopProductsPanel() {
    const { data: topProducts = [], isLoading } = useQuery({
        queryKey: [...QUERY_KEYS.admin.overview, 'top-products'],
        queryFn: () => getTopProductsByClicks()
    })

    if (isLoading) {
        return <EmptyState icon={ShoppingBag} title="Carregando..." description="Buscando estatísticas de cliques." />
    }

    if (topProducts.length === 0) {
        return (
            <EmptyState
                icon={ShoppingBag}
                title="Nenhum Clique"
                description="Ainda não há registros de cliques nos produtos da loja."
            />
        )
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
            {topProducts.map((product: any, index: number) => (
                <GlassPanel
                    key={product.id}
                    padding={STORE_TOKENS.PADDING.CONTAINER}
                    display="flex"
                    direction="col"
                    justify="center"
                    gap={STORE_TOKENS.SPACING.CONTAINER}
                    transition
                    group
                    hoverBg={STORE_TOKENS.COLORS.WHITE}
                    hoverBgOpacity={STORE_TOKENS.OPACITY.LOW}
                >
                    <Stack direction="row" align="center" justify="between" fullWidth>
                        <Stack direction="row" gap={STORE_TOKENS.SPACING.CONTAINER} align="center">
                            {/* Rank Badge - Circular & Centered */}
                            <Box
                                width="auto"
                                padding={STORE_TOKENS.PADDING.ELEMENT}
                                bg={!index ? STORE_TOKENS.COLORS.WARNING : STORE_TOKENS.COLORS.WHITE}
                                bgOpacity={!index ? STORE_TOKENS.OPACITY.MEDIUM : STORE_TOKENS.OPACITY.LOW}
                                rounded={STORE_TOKENS.RADIUS.FULL}
                                display="flex"
                                align="center"
                                justify="center"
                                minWidth={40}
                                minHeight={40}
                            >
                                <Font
                                    variant="label-caps"
                                    color={!index ? STORE_TOKENS.COLORS.WARNING : STORE_TOKENS.COLORS.TEXT.SECONDARY}
                                >
                                    #{index + 1}
                                </Font>
                            </Box>

                            {/* Product Image */}
                            <Box
                                bg={STORE_TOKENS.COLORS.BLACK}
                                width={48}
                                height={48}
                                overflow="hidden"
                                rounded={STORE_TOKENS.RADIUS.SYSTEM}
                            >
                                {product.image_url ? (
                                    <Img
                                        src={product.image_url}
                                        alt={product.name}
                                        fullWidth
                                        fullHeight
                                        objectFit="cover"
                                    />
                                ) : (
                                    <Stack fullHeight align="center" justify="center">
                                        <Icon icon={ShoppingBag} size="sm" color={STORE_TOKENS.COLORS.TEXT.DIM} />
                                    </Stack>
                                )}
                            </Box>

                            {/* Desktop Only: Product Name & Badge */}
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT} display={{ base: 'none', md: 'flex' }}>
                                <Font weight="black" italic uppercase variant="body">
                                    {product.name}
                                </Font>
                                <Box width="auto">
                                    <Badge
                                        label={product.category}
                                        variant="glass"
                                        color={STORE_TOKENS.COLORS.BRAND}
                                        size="sm"
                                    />
                                </Box>
                            </Stack>
                        </Stack>

                        {/* Clicks Metric (Always on the right of the top row) */}
                        <Stack align="end" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                            <Stack direction="row" gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                <Icon icon={MousePointer2} size="xs" color={STORE_TOKENS.COLORS.SUCCESS} />
                                <Font
                                    weight="black"
                                    variant="heading"
                                    {...{
                                        color: STORE_TOKENS.COLORS.SUCCESS,
                                    }}>
                                    {product.clicks}
                                </Font>
                            </Stack>
                            <Font
                                variant="label-caps"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                }}>
                                Cliques
                            </Font>
                        </Stack>
                    </Stack>

                    {/* Mobile Only: Product Name & Badge */}
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT} display={{ base: 'flex', md: 'none' }}>
                        <Font weight="black" italic uppercase variant="body">
                            {product.name}
                        </Font>
                        <Box width="auto">
                            <Badge
                                label={product.category}
                                variant="glass"
                                color={STORE_TOKENS.COLORS.BRAND}
                                size="sm"
                            />
                        </Box>
                    </Stack>
                </GlassPanel>
            ))}
        </Stack>
    );
}

'use client'

import React, { useState } from 'react'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Box } from '@/components/store/base/box'
import { Grid } from '@/components/store/base/grid'
import { Surface } from '@/components/store/base/surface'
import { Input } from '@/components/store/base/input'
import { FormSelect } from '@/components/store/base/form-select'
import { FormSwitch } from '@/components/store/base/form-switch'
import { Textarea } from '@/components/store/base/textarea'
import { Button } from '@/components/store/base/button'
import { Icon } from '@/components/store/base/icon'
import { FormCheckbox } from '@/components/store/base/form-checkbox'
import {
    Zap,
    Utensils,
    Sparkles,
    Loader2,
    Target,
    AlertCircle,
    ArrowLeft,
    ArrowRight
} from 'lucide-react'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { generateAIProtocol, AIProtocolPreferences } from '@/actions/ai-protocol-actions'
import { saveParsedData } from '@/actions/save-actions'
import { useQueryClient, useMutation } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { useToast } from '@/hooks/use-toast'
import { DomainStepCard } from '../intermediary/domain-step-card'

interface AIProtocolFormProps {
    userId: string
    onSuccess: (summary: any) => void
}

/**
 * AIProtocolForm: Advanced organism grouping all behavior and layout for the protocol generator.
 * Extracted from AIProtocolSectionContent.
 * All nested structures (StepCards, Grids) are preserved for pixel-perfect parity.
 */
export function AIProtocolForm({ userId, onSuccess }: AIProtocolFormProps) {
    const { toast } = useToast()
    const queryClient = useQueryClient()
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState<string | null>(null)

    const [currentStep, setCurrentStep] = useState(1)

    const handleNext = () => setCurrentStep(prev => Math.min(prev + 1, 3))
    const handlePrev = () => setCurrentStep(prev => Math.max(prev - 1, 1))

    // Form state
    const [goal, setGoal] = useState<'bulking' | 'cutting' | 'maintenance'>('bulking')
    const [workoutSplit, setWorkoutSplit] = useState('ppl')
    const [customSplit, setCustomSplit] = useState('')
    const [trainingVolume, setTrainingVolume] = useState<'low' | 'high'>('high')
    const [strongMuscles, setStrongMuscles] = useState('')
    const [weakMuscles, setWeakMuscles] = useState('')
    const [cardioLikes, setCardioLikes] = useState<string[]>([])
    const [mealsPerDay, setMealsPerDay] = useState(4)
    const [foodLikes, setFoodLikes] = useState('')
    const [foodDislikes, setFoodDislikes] = useState('')

    const { mutate: generateMutate } = useMutation({
        mutationFn: async (variables: any) => {
            const result = await generateAIProtocol(variables.preferences)
            if (result.error) throw new Error(result.error)
            
            if (result.data) {
                const saveResult = await saveParsedData('workout', result.data, userId)
                if (saveResult.error) throw new Error(saveResult.error)
            }
            
            return result
        },
        onMutate: () => {
            setLoading(true)
            toast({ title: "✨ Gerando seu protocolo...", description: "Aguarde enquanto a IA processa seu plano (isso pode demorar alguns segundos)." })
        },
        onSuccess: (result) => {
            setLoading(false)
            if (result.data) {
                queryClient.invalidateQueries({ queryKey: QUERY_KEYS.student.hasProtocol(userId) })
                onSuccess(result.summary)
            }
        },
        onError: (err: any) => {
            setLoading(false)
            setError(err.message)
            toast({ variant: "destructive", title: "Erro na geração", description: err.message })
        }
    })

    const handleGenerate = () => {
        const preferences: AIProtocolPreferences = {
            goal,
            workoutSplit: workoutSplit === 'other' ? customSplit : workoutSplit,
            trainingVolume,
            strongMuscles,
            weakMuscles,
            cardioLikes: cardioLikes.join(', '),
            cardioDislikes: '',
            mealsPerDay,
            foodLikes,
            foodDislikes,
            dietaryRestrictions: '',
        }
        generateMutate({ preferences })
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
            {/* 1. OBJETIVO & TREINO */}
            {currentStep === 1 && (
                <DomainStepCard
                    index={1}
                    title="Objetivo & Treino"
                    description="Defina sua meta principal e a estrutura do seu treinamento."
                    icon={Target}
                >
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <FormSelect
                            label="Seu Objetivo"
                            placeholder="Selecione o objetivo..."
                            value={goal}
                            onChange={(v) => setGoal(v as any)}
                            options={[
                                { value: 'bulking', label: 'Bulking', description: 'Ganho de massa e força muscular.' },
                                { value: 'cutting', label: 'Cutting', description: 'Queima de gordura e definição.' },
                                { value: 'maintenance', label: 'Manutenção', description: 'Manter físico e melhorar qualidade.' },
                            ]}
                        />

                        <Box height="px" bg={STORE_TOKENS.COLORS.WHITE} bgOpacity={STORE_TOKENS.OPACITY.LOW} fullWidth />

                        <Grid cols={{ base: 2, md: 2 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <FormSelect
                                label="Divisão"
                                placeholder="Selecione a divisão..."
                                value={workoutSplit}
                                onChange={(v) => setWorkoutSplit(v)}
                                options={[
                                    { value: 'ppl', label: 'PPL', description: 'Push / Pull / Legs' },
                                    { value: 'upper_lower', label: 'Upper/Lower', description: 'Superior / Inferior' },
                                    { value: 'one_group', label: 'ABCDE', description: '1 Músculo por dia' },
                                    { value: 'full_body', label: 'Full Body', description: 'Corpo todo' },
                                    { value: 'other', label: 'Personalizado', description: 'Descreva sua divisão' },
                                ]}
                            />
                            <FormSwitch
                                label="Volume"
                                value={trainingVolume}
                                onChange={(v) => setTrainingVolume(v as any)}
                                options={[
                                    { label: 'LOW VOLUME', value: 'low' },
                                    { label: 'HIGH VOLUME', value: 'high' }
                                ]}
                            />
                            {workoutSplit === 'other' && (
                                <Box mdColSpan={2}>
                                    <Input label="Descrição da Divisão" placeholder="Ex: Peito e Costas..." value={customSplit} onChange={(e) => setCustomSplit(e.target.value)} />
                                </Box>
                            )}
                        </Grid>

                        <Box height="px" bg={STORE_TOKENS.COLORS.WHITE} bgOpacity={STORE_TOKENS.OPACITY.LOW} fullWidth />

                        <Grid cols={{ base: 2, md: 2 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Textarea label="Pontos Fortes" placeholder="Peitoral, Braços..." value={strongMuscles} onChange={(e) => setStrongMuscles(e.target.value)} />
                            <Textarea label="Pontos Fracos" placeholder="Dorsais, Quadríceps..." value={weakMuscles} onChange={(e) => setWeakMuscles(e.target.value)} />
                        </Grid>
                    </Stack>
                </DomainStepCard>
            )}
            {/* 2. CARDIO */}
            {currentStep === 2 && (
                <DomainStepCard
                    index={2}
                    title="Perfil Aeróbico"
                    description="Modalidades preferidas para queima calórica."
                    icon={Zap}
                >
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Font
                            variant="sub-tiny"
                            weight="black"
                            uppercase
                            tracking="widest"
                            {...{
                                color: "zinc-500",
                            }}>Modalidades Aceitas</Font>
                        <Grid cols={{ base: 2, md: 4 }} gap={STORE_TOKENS.SPACING.ELEMENT}>
                            {['Esteira', 'Bike', 'Escada', 'Corrida', 'HIIT', 'Natação', 'Caminhada', 'Corda'].map(c => (
                                <FormCheckbox
                                    key={c}
                                    label={c.toUpperCase()}
                                    checked={cardioLikes.includes(c)}
                                    onChange={(checked) => setCardioLikes(prev => checked ? [...prev, c] : prev.filter(x => x !== c))}
                                />
                            ))}
                        </Grid>
                    </Stack>
                </DomainStepCard>
            )}
            {/* 3. DIETA */}
            {currentStep === 3 && (
                <DomainStepCard
                    index={3}
                    title="Plano Nutricional"
                    description="Personalização da base alimentar diária."
                    icon={Utensils}
                >
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <FormSelect
                            label="Refeições por dia"
                            value={String(mealsPerDay)}
                            onChange={(v) => setMealsPerDay(Number(v))}
                            options={[{ value: '3', label: '3 Refeições' }, { value: '4', label: '4 Refeições' }, { value: '5', label: '5 Refeições' }, { value: '6', label: '6 Refeições' }]}
                        />
                        <Grid cols={{ base: 2, md: 2 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Textarea label="Gosto de" placeholder="Frango, Arroz, Ovos..." value={foodLikes} onChange={(e) => setFoodLikes(e.target.value)} />
                            <Textarea label="Não Gosto / Restrições" placeholder="Lactose, Brócolis..." value={foodDislikes} onChange={(e) => setFoodDislikes(e.target.value)} />
                        </Grid>
                    </Stack>
                </DomainStepCard>
            )}
            {/* ACTION AREA */}
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                {error && (
                    <Surface variant="tonal-red" padding={STORE_TOKENS.PADDING.ELEMENT} rounded={STORE_TOKENS.RADIUS.SYSTEM}>
                        <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                            <Icon icon={AlertCircle} size="xs" color={STORE_TOKENS.COLORS.ERROR} />
                            <Font
                                variant="auxiliary"
                                {...{
                                    color: "red",
                                }}>{error}</Font>
                        </Stack>
                    </Surface>
                )}

                {currentStep === 1 ? (
                    <Button variant="primary" size="lg" fullWidth onClick={handleNext}>
                        <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                            <Font variant="sub-tiny" weight="black" uppercase italic>Próxima Etapa</Font>
                            <Icon icon={ArrowRight} size="xs" />
                        </Stack>
                    </Button>
                ) : (
                    <Grid cols={{ base: 1, md: 2 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Button variant="outline-zinc" size="lg" fullWidth onClick={handlePrev} disabled={loading}>
                            <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Icon icon={ArrowLeft} size="xs" />
                                <Font variant="sub-tiny" weight="black" uppercase italic>Anterior</Font>
                            </Stack>
                        </Button>

                        {currentStep < 3 ? (
                            <Button variant="primary" size="lg" fullWidth onClick={handleNext}>
                                <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                    <Font variant="sub-tiny" weight="black" uppercase italic>Próxima Etapa</Font>
                                    <Icon icon={ArrowRight} size="xs" />
                                </Stack>
                            </Button>
                        ) : (
                            <Button variant="primary" size="lg" fullWidth onClick={handleGenerate} disabled={loading}>
                                {loading ? (
                                    <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Icon icon={Loader2} size="sm" animate="spin" />
                                        <Font variant="sub-tiny" weight="black" uppercase>Processando...</Font>
                                    </Stack>
                                ) : (
                                    <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Icon icon={Sparkles} size="xs" />
                                        <Font variant="sub-tiny" weight="black" uppercase italic>Gerar Protocolo</Font>
                                    </Stack>
                                )}
                            </Button>
                        )}
                    </Grid>
                )}
            </Stack>
        </Stack>
    );
}

'use client'

import React, { useState, useEffect } from 'react'
import { Modal } from '@/components/store/advanced/modal'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Input } from '@/components/store/base/input'
import {
    CreditCard,
    User,
    ShieldCheck,
    CheckCircle2,
    Calendar,
    MapPin,
    Hash,
    Loader2
} from 'lucide-react'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { createAsaasSubscription, searchAsaasCustomer } from '@/actions/asaas-actions'
import { useToast } from '@/hooks/use-toast'

interface AsaasPaymentModalProps {
    isOpen: boolean
    onClose: () => void
    tier: 'on_demand' | 'auto_training'
    currentCpf?: string
    currentName?: string
    monthlyTotal: number
    userId?: string
}

type Step = 'info' | 'payment' | 'card_details'

export function AsaasPaymentModal({
    isOpen,
    onClose,
    tier,
    currentCpf,
    currentName,
    monthlyTotal,
    userId
}: AsaasPaymentModalProps) {
    const [cpf, setCpf] = useState(currentCpf || '')
    const [fullName, setFullName] = useState(currentName || '')
    const [isProcessing, setIsProcessing] = useState(false)
    const [cardData, setCardData] = useState({
        number: '',
        holder: '',
        expiry: '',
        cvv: '',
        postalCode: '',
        addressNumber: ''
    })
    const [fetchingName, setFetchingName] = useState(false)
    const { toast } = useToast()

    // Masking Utilities
    const maskCpfCnpj = (v: string) => {
        const c = v.replace(/\D/g, '')
        if (c.length <= 11) {
            return c.replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d{1,2})/, '$1-$2').substring(0, 14);
        }
        return c.replace(/(\d{2})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1/$2').replace(/(\d{4})(\d{1,2})/, '$1-$2').substring(0, 18);
    }

    const maskCardNumber = (v: string) => v.replace(/\D/g, '').replace(/(\d{4})/g, '$1 ').trim().substring(0, 19)
    const maskExpiry = (v: string) => v.replace(/\D/g, '').replace(/(\d{2})/, '$1/').substring(0, 5)
    const maskCep = (v: string) => v.replace(/\D/g, '').replace(/(\d{5})/, '$1-').substring(0, 9)

    const validateCpfCnpj = (val: string) => {
        const clean = val.replace(/\D/g, '')
        return clean.length === 11 || clean.length === 14 
    }

    // Auto-fetch name from Asaas
    useEffect(() => {
        const clean = cpf.replace(/\D/g, '')
        if (clean.length === 11 || clean.length === 14) {
            if (!fullName || fullName.trim().split(' ').length < 2) {
                const timer = setTimeout(async () => {
                    setFetchingName(true)
                    try {
                        const res = await searchAsaasCustomer(clean)
                        if (res.success && res.name) {
                            setFullName(res.name)
                        }
                    } catch (err) {
                        console.error(`[ASAAS] Error:`, err)
                    } finally {
                        setFetchingName(false)
                    }
                }, 800)
                return () => clearTimeout(timer)
            }
        }
    }, [cpf])

    const handleSubscribe = async (e?: React.FormEvent) => {
        if (e) e.preventDefault()
        
        if (!validateCpfCnpj(cpf)) {
            toast({ variant: 'destructive', title: 'Documento inválido', description: 'Insira um CPF ou CNPJ válido.' })
            return
        }
        if (fullName.trim().split(' ').length < 2) {
            toast({ variant: 'destructive', title: 'Nome incompleto', description: 'Por favor, insira seu nome completo.' })
            return
        }
        if (cardData.number.replace(/\s/g, '').length < 15) {
            toast({ variant: 'destructive', title: 'Cartão inválido', description: 'Insira um número de cartão válido.' })
            return
        }
        if (cardData.expiry.length < 5) {
            toast({ variant: 'destructive', title: 'Validade inválida', description: 'Insira uma validade válida.' })
            return
        }
        if (cardData.cvv.length < 3) {
            toast({ variant: 'destructive', title: 'CVV inválido', description: 'Insira um CVV válido.' })
            return
        }

        setIsProcessing(true)
        toast({ title: "Processando...", description: "Estamos preparando sua assinatura segura." })

        try {
            const [month, year] = cardData.expiry.split('/')
            const fullYear = `20${year}`

            const res = await createAsaasSubscription(
                tier,
                'CREDIT_CARD',
                cpf.replace(/\D/g, ''),
                fullName.trim(),
                {
                    holderName: cardData.holder,
                    number: cardData.number.replace(/\s/g, ''),
                    expiryMonth: month,
                    expiryYear: fullYear,
                    ccv: cardData.cvv,
                    postalCode: cardData.postalCode.replace(/\D/g, ''),
                    addressNumber: cardData.addressNumber
                }
            )

            if (res.success) {
                toast({ title: 'Sucesso!', description: 'Sua assinatura foi processada com êxito.' })
                onClose()
                const target = tier === 'auto_training' ? '/dashboard/student' : '/dashboard/trainer'
                window.location.href = target
            } else {
                throw new Error(res.error || 'Erro ao processar o pagamento.')
            }
        } catch (err: any) {
            toast({
                variant: 'destructive',
                title: 'Erro no Pagamento',
                description: err.message || 'Ocorreu um erro ao processar o cartão.'
            })
        } finally {
            setIsProcessing(false)
        }
    }

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Finalizar Assinatura"
            subtitle={tier === 'auto_training' ? 'Plano Aluno Auto-Treino' : 'Plano Trainer On-Demand'}
            icon={ShieldCheck}
            variant="emerald"
            hideCancel
            confirmLabel="Assinar Agora"
            onConfirm={handleSubscribe}
            isLoading={isProcessing}
        >
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                {/* Total Summary */}
                <Box padding={STORE_TOKENS.PADDING.CONTAINER} bg={STORE_TOKENS.COLORS.BACKGROUND} bgOpacity={STORE_TOKENS.OPACITY.SUBTLE} border borderColor={STORE_TOKENS.COLORS.DIVIDER.SUBTLE} rounded={STORE_TOKENS.RADIUS.SYSTEM}>
                    <Stack align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                        <Font
                            variant="sub-tiny"
                            weight="black"
                            uppercase
                            {...{
                                color: "zinc-500",
                            }}>Total a Investir</Font>
                        <Font
                            variant="h3"
                            {...{
                                color: "white",
                            }}>R$ {monthlyTotal.toFixed(2).replace('.', ',')}</Font>
                        <Font
                            variant="tiny"
                            weight="black"
                            uppercase
                            italic
                            {...{
                                color: "emerald",
                            }}>Assinatura Mensal Recorrente</Font>
                    </Stack>
                </Box>

                {/* Identification */}
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    <Input
                        label="DOCUMENTO (CPF OU CNPJ)"
                        icon={<Hash size={16} />}
                        value={cpf}
                        onChange={(e) => setCpf(maskCpfCnpj(e.target.value))}
                        placeholder="000.000.000-00"
                    />

                    <Input
                        label="NOME COMPLETO"
                        icon={fetchingName ? <Icon icon={Loader2} size="sm" spin /> : <User size={16} />}
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value)}
                        placeholder="Seu nome conforme o documento"
                    />
                </Stack>



                {/* Card Details */}
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    <Input
                        label="NÚMERO DO CARTÃO"
                        icon={<CreditCard size={16} />}
                        value={cardData.number}
                        onChange={(e) => setCardData(d => ({ ...d, number: maskCardNumber(e.target.value) }))}
                        placeholder="0000 0000 0000 0000"
                    />

                    <Input
                        label="NOME NO CARTÃO"
                        icon={<User size={16} />}
                        value={cardData.holder}
                        onChange={(e) => setCardData(d => ({ ...d, holder: e.target.value.toUpperCase() }))}
                        placeholder="NOME COMO IMPRESSO"
                    />

                    <Stack direction="row" gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Input
                            label="VALIDADE"
                            icon={<Calendar size={16} />}
                            value={cardData.expiry}
                            onChange={(e) => setCardData(d => ({ ...d, expiry: maskExpiry(e.target.value) }))}
                            placeholder="MM/AA"
                            flex1
                        />
                        <Input
                            label="CVV"
                            icon={<ShieldCheck size={16} />}
                            value={cardData.cvv}
                            onChange={(e) => setCardData(d => ({ ...d, cvv: e.target.value.replace(/\D/g, '').substring(0, 4) }))}
                            placeholder="000"
                            flex1
                        />
                    </Stack>

                    <Stack direction="row" gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Input
                            label="CEP"
                            icon={<MapPin size={16} />}
                            value={cardData.postalCode}
                            onChange={(e) => setCardData(d => ({ ...d, postalCode: maskCep(e.target.value) }))}
                            placeholder="00000-000"
                            flex1
                        />
                        <Input
                            label="Nº"
                            icon={<Hash size={16} />}
                            value={cardData.addressNumber}
                            onChange={(e) => setCardData(d => ({ ...d, addressNumber: e.target.value }))}
                            placeholder="Ex: 123"
                            flex1
                        />
                    </Stack>
                </Stack>

                <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT} padding={STORE_TOKENS.PADDING.ELEMENT}>
                    <Icon icon={CheckCircle2} size="xs" color={STORE_TOKENS.COLORS.SUCCESS} />
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        tracking="widest"
                        {...{
                            color: "zinc-500",
                        }}>Ambiente 100% Seguro</Font>
                </Stack>
            </Stack>
        </Modal>
    );
}

'use client'

import React, { useState } from 'react'
import { AuthLoginForm } from './auth-login-form'
import { AuthSignUpForm } from './auth-signup-form'
import { AuthAffiliateSignUpForm } from './auth-affiliate-signup-form'
import { AuthForgotPasswordForm } from './auth-forgot-password-form'
import { AuthUpdatePasswordForm } from './auth-update-password-form'
import { 
    signInAction, 
    signUpAction, 
    forgotPasswordAction, 
    updatePasswordAction 
} from '@/actions/auth-actions'
import { useSearchParams } from 'next/navigation'

interface AuthFormProps {
    view: 'login' | 'signup' | 'affiliate-signup' | 'forgot-password' | 'update-password'
}

export function AuthForm({ view }: AuthFormProps) {
    const searchParams = useSearchParams()
    
    // Common State
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [fullName, setFullName] = useState('')
    const [whatsapp, setWhatsapp] = useState('')
    const [role, setRole] = useState<'student' | 'trainer'>('trainer')
    const [acceptedTerms, setAcceptedTerms] = useState(true)
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState<string | null>(null)
    const [success, setSuccess] = useState<string | null>(null)

    // Handle Login
    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        setError(null)

        const formData = new FormData()
        formData.append('email', email)
        formData.append('password', password)

        const result = await signInAction(formData)
        if (result?.error) {
            setError(result.error)
            setLoading(false)
        }
    }

    // Handle SignUp
    const handleSignUp = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!acceptedTerms) {
            setError('Você precisa aceitar os termos de uso.')
            return
        }

        setLoading(true)
        setError(null)

        const formData = new FormData()
        formData.append('email', email)
        formData.append('password', password)
        formData.append('full_name', fullName)
        formData.append('whatsapp', whatsapp)
        formData.append('role', view === 'affiliate-signup' ? 'affiliate' : role)
        
        const ref = searchParams.get('ref')
        if (ref) formData.append('referred_by', ref)

        const result = await signUpAction(formData)
        if (result?.error) {
            setError(result.error)
            setLoading(false)
        }
    }

    // Handle Forgot Password
    const handleForgotPassword = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        setError(null)
        setSuccess(null)

        const formData = new FormData()
        formData.append('email', email)
        formData.append('origin', window.location.origin)

        const result = await forgotPasswordAction(formData)
        if (result?.error) {
            setError(result.error)
        } else if (result?.success) {
            setSuccess(result.success)
        }
        setLoading(false)
    }

    // Handle Update Password
    const handleUpdatePassword = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        setError(null)

        const formData = new FormData()
        formData.append('password', password)

        const result = await updatePasswordAction(formData)
        if (result?.error) {
            setError(result.error)
            setLoading(false)
        }
    }

    switch (view) {
        case 'login':
            return (
                <AuthLoginForm 
                    email={email} setEmail={setEmail}
                    password={password} setPassword={setPassword}
                    onSubmit={handleLogin}
                    loading={loading}
                    error={error}
                />
            )
        case 'signup':
            return (
                <AuthSignUpForm 
                    fullName={fullName} setFullName={setFullName}
                    email={email} setEmail={setEmail}
                    whatsapp={whatsapp} setWhatsapp={setWhatsapp}
                    password={password} setPassword={setPassword}
                    role={role} setRole={setRole}
                    acceptedTerms={acceptedTerms} setAcceptedTerms={setAcceptedTerms}
                    onSubmit={handleSignUp}
                    loading={loading}
                    error={error}
                />
            )
        case 'affiliate-signup':
            return (
                <AuthAffiliateSignUpForm 
                    fullName={fullName} setFullName={setFullName}
                    email={email} setEmail={setEmail}
                    whatsapp={whatsapp} setWhatsapp={setWhatsapp}
                    password={password} setPassword={setPassword}
                    acceptedTerms={acceptedTerms} setAcceptedTerms={setAcceptedTerms}
                    onSubmit={handleSignUp}
                    loading={loading}
                    error={error}
                />
            )
        case 'forgot-password':
            return (
                <AuthForgotPasswordForm 
                    email={email} setEmail={setEmail}
                    onSubmit={handleForgotPassword}
                    loading={loading}
                    error={error}
                    message={success}
                />
            )
        case 'update-password':
            return (
                <AuthUpdatePasswordForm 
                    password={password} setPassword={setPassword}
                    onSubmit={handleUpdatePassword}
                    loading={loading}
                    error={error}
                />
            )
        default:
            return <AuthLoginForm />
    }
}

