'use client'

import React from 'react'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Input } from '@/components/store/base/input'
import { Button } from '@/components/store/base/button'
import { GlassPanel } from '@/components/store/base/surface'
import { Inline } from '@/components/store/base/layout'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { RegistryActionModal } from '@/components/store/advanced/registry-action-modal'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { assignDiet } from '@/actions/diet-actions'
import { ENTITIES } from '@/lib/outbox-db'
import { Pencil, Check, X, Calendar, Sparkles, Loader2, Utensils } from 'lucide-react'
import { AssignmentBadge } from '@/components/store/intermediary/assignment-badge'

interface DietBuilderHeaderProps {
    dietId: string
    name: string
    description?: string
    isEditing: boolean
    setIsEditing: (val: boolean) => void
    editName: string
    setEditName: (val: string) => void
    onSave: () => void
    onCancel: () => void
    showAssignmentBadge?: boolean
    canAssign?: boolean
    assignments?: any[]
    students?: any[]
    isEstimatingAll: boolean
    onEstimateAll: () => void
    contextLabel?: string
    icon?: string
    contextColor?: string
}

export function DietBuilderHeader({
    dietId,
    name,
    description,
    isEditing,
    setIsEditing,
    editName,
    setEditName,
    onSave,
    onCancel,
    showAssignmentBadge = true,
    canAssign = true,
    assignments = [],
    students = [],
    isEstimatingAll,
    onEstimateAll,
    contextLabel,
    contextColor
}: DietBuilderHeaderProps) {
    const [isAssignModalOpen, setIsAssignModalOpen] = React.useState(false)

    const { mutate: assignMutation } = useOptimisticMutation({
        queryKey: ['diet'],
        entity: ENTITIES.DIET,
        actionName: 'assign-diet',
        mutationFn: async ({ dietId, daysOfWeek, studentId }: { dietId: string; daysOfWeek: number[]; studentId: string }) => {
            const res = await assignDiet(dietId, studentId, daysOfWeek)
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const handleAssignConfirm = (data?: any) => {
        if (!data || !data.student_id) return
        const { selectedDays, student_id } = data
        assignMutation({ dietId, daysOfWeek: selectedDays || [0, 1, 2, 3, 4, 5, 6], studentId: student_id })
        setIsAssignModalOpen(false)
    }

    return (
        <Stack
            direction={{ base: 'col', md: 'row' }}
            align={{ base: 'stretch', md: 'start' }}
            justify="between"
            gap={STORE_TOKENS.SPACING.SECTION}
            fullWidth
        >
            {/* Diet name — display or edit mode */}
            <Box flex1>
                {isEditing ? (
                    <GlassPanel padding={STORE_TOKENS.SPACING.CONTAINER}>
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Font
                                    variant="sub-tiny"
                                    uppercase
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                    }}>
                                    Nome da Dieta
                                </Font>
                                <Input
                                    value={editName}
                                    onChange={(e) => setEditName(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') onSave()
                                        if (e.key === 'Escape') onCancel()
                                    }}
                                    placeholder="Nome da dieta..."
                                    size="lg"
                                    autoFocus
                                />
                            </Stack>
                            <Stack direction={{ base: 'col', md: 'row' }} gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Button
                                    variant="outline-emerald"
                                    onClick={onSave}
                                    gap={STORE_TOKENS.SPACING.ELEMENT}
                                    fullWidth={{ base: true, md: false }}
                                >
                                    <Icon icon={Check} size="xs" />
                                    Salvar
                                </Button>
                                <Button
                                    variant="outline-red"
                                    onClick={onCancel}
                                    gap={STORE_TOKENS.SPACING.ELEMENT}
                                    fullWidth={{ base: true, md: false }}
                                >
                                    <Icon icon={X} size="xs" />
                                    Cancelar
                                </Button>
                            </Stack>
                        </Stack>
                    </GlassPanel>
                ) : (
                    <Box
                        display="flex"
                        align="start"
                        gap={STORE_TOKENS.SPACING.ELEMENT}
                        cursor="pointer"
                        onClick={() => setIsEditing(true)}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                            {contextLabel && (
                                <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                    <Icon icon={Utensils} color={(contextColor as any) || STORE_TOKENS.COLORS.BRAND} size="lg" />
                                    <Font
                                        variant="auxiliary"
                                        uppercase
                                        {...{
                                            color: (contextColor as any) || STORE_TOKENS.COLORS.BRAND,
                                        }}>
                                        {contextLabel}
                                    </Font>
                                </Inline>
                            )}
                            <Inline align="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    uppercase
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                    }}>
                                    {name}
                                </Font>
                                <Box
                                    padding={STORE_TOKENS.SPACING.TINY}
                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                    hoverBg={STORE_TOKENS.COLORS.BACKGROUND}
                                    display="flex"
                                    align="center"
                                    justify="center"
                                >
                                    <Icon icon={Pencil} size="sm" color={STORE_TOKENS.COLORS.BRAND} />
                                </Box>
                            </Inline>
                            <Font
                                variant="description"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                }}>
                                {description || 'Toque para editar nome e detalhes'}
                            </Font>
                        </Stack>
                    </Box>
                )}
            </Box>
            {/* Actions: estimate + assign */}
            {!isEditing && (
                <Stack
                    direction={{ base: 'col', md: 'row' }}
                    align={{ base: 'stretch', md: 'center' }}
                    justify="end"
                    gap={STORE_TOKENS.SPACING.ELEMENT}
                >
                    {/* Assignment badge */}
                    {showAssignmentBadge && assignments && assignments.length > 0 && (
                        <AssignmentBadge
                            studentName={assignments[0]?.student?.full_name || 'Aluno'}
                            studentAvatarUrl={assignments[0]?.student?.avatar_url}
                            variant="primary"
                        />
                    )}

                    {/* Calcular Macros */}
                    <Button
                        variant="outline-zinc"
                        size="lg"
                        shine
                        onClick={onEstimateAll}
                        disabled={isEstimatingAll}
                        gap={STORE_TOKENS.SPACING.ELEMENT}
                        fullWidth={{ base: true, md: false }}
                    >
                        <Icon icon={isEstimatingAll ? Loader2 : Sparkles} size="sm" color={STORE_TOKENS.COLORS.BRAND} spin={isEstimatingAll} />
                        {isEstimatingAll ? 'Calculando...' : 'Calcular Macros'}
                    </Button>

                    {/* Assign diet */}
                    {canAssign && (
                        <Box shrink={0} display="flex" justify="center">
                            <Button
                                variant="outline-primary"
                                size="lg"
                                shine
                                fullWidth={{ base: true, md: false }}
                                onClick={() => setIsAssignModalOpen(true)}
                            >
                                <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                    <Icon icon={Calendar} size="sm" color={STORE_TOKENS.COLORS.BRAND} />
                                    {assignments?.length ? 'Gerenciar Atribuição' : 'Atribuir Dieta'}
                                </Inline>
                            </Button>
                        </Box>
                    )}

                    <RegistryActionModal
                        isOpen={isAssignModalOpen}
                        onClose={() => setIsAssignModalOpen(false)}
                        type="assign_diet"
                        onConfirm={handleAssignConfirm}
                        students={students}
                        initialData={{
                            student_id: assignments?.[0]?.student_id,
                            selectedDays: assignments?.[0]?.days_of_week || [0, 1, 2, 3, 4, 5, 6]
                        }}
                    />
                </Stack>
            )}
        </Stack>
    );
}

'use client'

import React, { useState, useEffect } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useToast } from '@/hooks/use-toast'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import {
    getDietDetails,
    addMealToDiet,
    removeMeal,
    addMealItem,
    removeMealItem,
    updateMealsOrder,
    updateMealItemsOrder,
    updateDietMeta,
    estimateAllDietMacros
} from '@/actions/diet-actions'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Grid } from '@/components/store/base/grid'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Button } from '@/components/store/base/button'
import { Badge } from '@/components/store/base/badge'
import { GlassPanel } from '@/components/store/base/surface'
import { Inline } from '@/components/store/base/layout'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Loader2, ArrowLeft, Utensils } from 'lucide-react'
import Link from 'next/link'
import { EmptyState } from '@/components/store/intermediary/empty-state'

import { DietBuilderHeader } from './diet-builder-header'
import { DietBuilderMealCard } from './diet-builder-meal-card'
import { DietBuilderNewMeal } from './diet-builder-new-meal'

interface DietBuilderSmartProps {
    diet: any
    students?: any[]
    backHref?: string
    canAssign?: boolean
    showAssignmentBadge?: boolean
    hideHeader?: boolean
    contextLabel?: string
    icon?: string
    contextColor?: string
}

export function DietBuilderSmart({
    diet: initialDiet,
    students = [],
    backHref = '/dashboard/trainer/diets',
    canAssign = true,
    showAssignmentBadge = true,
    hideHeader = false,
    contextLabel,
    icon,
    contextColor
}: DietBuilderSmartProps) {
    const { toast } = useToast()
    const queryClient = useQueryClient()
    const queryKey = QUERY_KEYS.diets.detail(initialDiet.id)

    const { data: dietData } = useQuery({
        queryKey,
        queryFn: () => getDietDetails(initialDiet.id),
        initialData: initialDiet
    })

    const diet = dietData as { id: string; name: string; meals: any[]; assignments?: any[] }
    const meals = diet.meals || []

    // Meta editing state
    const [isEditingMeta, setIsEditingMeta] = useState(false)
    const [editName, setEditName] = useState(diet.name)
    const [isEstimatingAll, setIsEstimatingAll] = useState(false)

    // Drag state
    const [draggedMealId, setDraggedMealId] = useState<string | null>(null)
    const [draggedItemId, setDraggedItemId] = useState<{ mealId: string; itemId: string } | null>(null)

    useEffect(() => {
        if (!isEditingMeta && diet) {
            setEditName(diet.name)
        }
    }, [diet?.name, isEditingMeta])

    // ── MUTATIONS ─────────────────────────────────────────────────────────────

    const { mutate: mutateMeta } = useOptimisticMutation({
        actionName: 'update-diet-meta',
        entity: ENTITIES.DIET,
        entityId: diet.id,
        queryKey,
        mutationFn: async (variables: { id: string; name: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({ ...old, name: variables.name }))
            return { previous }
        },
        onSuccess: () => setIsEditingMeta(false)
    })

    const { mutate: addMealMutate } = useOptimisticMutation({
        actionName: 'add-meal',
        entity: ENTITIES.DIET,
        entityId: diet.id,
        queryKey,
        mutationFn: async (variables: { dietId: string; name: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                meals: [...(old?.meals || []), {
                    id: `temp-${Date.now()}`,
                    diet_id: diet.id,
                    name: variables.name,
                    time_of_day: '08:00',
                    order_index: (old?.meals?.length || 0),
                    notes: '',
                    meal_items: []
                }]
            }))
            return { previous }
        }
    })

    const { mutate: addItemMutate } = useOptimisticMutation({
        actionName: 'add-meal-item',
        entity: ENTITIES.MEAL,
        entityId: 'new',
        queryKey,
        mutationFn: async (variables: { mealId: string; dietId: string; foodId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                meals: (old?.meals || []).map((m: any) =>
                    m.id === variables.mealId
                        ? {
                            ...m, meal_items: [...(m.meal_items || []), {
                                id: `temp-item-${Date.now()}`,
                                food_name: 'Novo Alimento',
                                quantity: '100g',
                                protein: 0, carbs: 0, fat: 0, fiber: 0
                            }]
                        }
                        : m
                )
            }))
            return { previous }
        }
    })

    const { mutate: removeMealMutate } = useOptimisticMutation({
        actionName: 'remove-meal',
        entity: ENTITIES.MEAL,
        entityId: 'remove',
        queryKey,
        mutationFn: async (variables: { id: string; dietId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                meals: (old?.meals || []).filter((m: any) => m.id !== variables.id)
            }))
            return { previous }
        }
    })

    const { mutate: removeItemMutate } = useOptimisticMutation({
        actionName: 'remove-meal-item',
        entity: ENTITIES.MEAL_ITEM,
        entityId: 'remove',
        queryKey,
        mutationFn: async (variables: { id: string; dietId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                meals: (old?.meals || []).map((m: any) => ({
                    ...m,
                    meal_items: (m.meal_items || []).filter((i: any) => i.id !== variables.id)
                }))
            }))
            return { previous }
        }
    })

    const { mutate: reorderMealsMutate } = useOptimisticMutation({
        actionName: 'update-meals-order',
        entity: ENTITIES.MEAL,
        entityId: diet.id,
        queryKey,
        mutationFn: async (variables: { orderedIds: string[]; dietId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => {
                const ms = [...(old?.meals || [])]
                const sorted = variables.orderedIds.map(id => ms.find(m => m.id === id)).filter(Boolean)
                return { ...old, meals: sorted }
            })
            return { previous }
        }
    })

    const { mutate: reorderItemsMutate } = useOptimisticMutation({
        actionName: 'update-meal-items-order',
        entity: ENTITIES.MEAL_ITEM,
        entityId: 'reorder',
        queryKey,
        mutationFn: async (variables: { mealId: string; orderedIds: string[] }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                meals: (old?.meals || []).map((m: any) => {
                    if (m.id !== variables.mealId) return m
                    const items = [...(m.meal_items || [])]
                    const sorted = variables.orderedIds.map(id => items.find(i => i.id === id)).filter(Boolean)
                    return { ...m, meal_items: sorted }
                })
            }))
            return { previous }
        }
    })

    // ── HANDLERS ──────────────────────────────────────────────────────────────

    const handleMealDragStart = (e: React.DragEvent, id: string) => {
        setDraggedMealId(id)
        if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move'
    }

    const handleMealDragOver = (e: React.DragEvent, targetId: string) => {
        e.preventDefault()
        if (!draggedMealId || draggedMealId === targetId) return
        const draggedIndex = meals.findIndex(m => m.id === draggedMealId)
        const targetIndex = meals.findIndex(m => m.id === targetId)
        if (draggedIndex === -1 || targetIndex === -1) return
        const newMeals = [...meals]
        const [removed] = newMeals.splice(draggedIndex, 1)
        newMeals.splice(targetIndex, 0, removed)
        queryClient.setQueryData(queryKey, (old: any) => ({ ...old, meals: newMeals }))
    }

    const handleMealDragEnd = () => {
        if (!draggedMealId) return
        setDraggedMealId(null)
        reorderMealsMutate({ orderedIds: meals.map(m => m.id), dietId: diet.id })
    }

    const handleItemDragStart = (e: React.DragEvent, mealId: string, itemId: string) => {
        e.stopPropagation()
        setDraggedItemId({ mealId, itemId })
    }

    const handleItemDragOver = (e: React.DragEvent, mealId: string, targetId: string) => {
        e.preventDefault()
        if (!draggedItemId || draggedItemId.mealId !== mealId || draggedItemId.itemId === targetId) return
        const mealIndex = meals.findIndex(m => m.id === mealId)
        if (mealIndex === -1) return
        const currentItems = meals[mealIndex].meal_items || []
        const draggedIndex = currentItems.findIndex((i: any) => i.id === draggedItemId.itemId)
        const targetIndex = currentItems.findIndex((i: any) => i.id === targetId)
        if (draggedIndex === -1 || targetIndex === -1) return
        const newMeals = [...meals]
        const newItems = [...currentItems]
        const [removed] = newItems.splice(draggedIndex, 1)
        newItems.splice(targetIndex, 0, removed)
        newMeals[mealIndex] = { ...newMeals[mealIndex], meal_items: newItems }
        queryClient.setQueryData(queryKey, (old: any) => ({ ...old, meals: newMeals }))
    }

    const handleItemDragEnd = (mealId: string) => {
        if (!draggedItemId) return
        const meal = meals.find(m => m.id === mealId)
        setDraggedItemId(null)
        if (meal) {
            reorderItemsMutate({ mealId, orderedIds: (meal.meal_items || []).map((i: any) => i.id) })
        }
    }

    const handleEstimateAll = async () => {
        try {
            setIsEstimatingAll(true)
            toast({ title: 'Calculando...', description: 'A IA está analisando todos os itens da dieta.' })
            const res = await estimateAllDietMacros(diet.id)
            if (res.success) {
                toast({ title: 'Concluído!', description: 'Todos os macros foram calculados com sucesso.' })
                queryClient.invalidateQueries({ queryKey })
            } else {
                throw new Error((res as any).error)
            }
        } catch (error: any) {
            toast({ variant: 'destructive', title: 'Erro', description: error.message || 'Erro ao calcular macros.' })
        } finally {
            setIsEstimatingAll(false)
        }
    }

    // Computed totals (passed down to header)
    const totals = meals.reduce((acc, meal) => {
        meal.meal_items?.forEach((item: any) => {
            acc.p += Number(item.protein) || 0
            acc.c += Number(item.carbs) || 0
            acc.f += Number(item.fat) || 0
            acc.fib += Number(item.fiber) || 0
        })
        return acc
    }, { p: 0, c: 0, f: 0, fib: 0 })

    // ── LOADING STATE ─────────────────────────────────────────────────────────
    if (!diet) {
        return (
            <Box display="flex" direction="col" align="center" justify="center" minHeight="lg" gap={STORE_TOKENS.SPACING.SECTION}>
                <Icon icon={Loader2} size="lg" color={STORE_TOKENS.COLORS.BRAND} spin />
                <Stack align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="heading"
                        uppercase
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                        }}>
                        Sincronizando Dados...
                    </Font>
                    <Font
                        variant="description"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.MUTED,
                        }}>
                        Preparando o protocolo alimentar
                    </Font>
                </Stack>
            </Box>
        );
    }

    // ── RENDER ────────────────────────────────────────────────────────────────
    return (
        <Stack gap={STORE_TOKENS.SPACING.SECTION}>
            {/* Header: name, macros bar, assign button */}
            {!hideHeader && (
                <DietBuilderHeader
                    dietId={diet.id}
                    name={diet.name}
                    isEditing={isEditingMeta}
                    setIsEditing={setIsEditingMeta}
                    editName={editName}
                    setEditName={setEditName}
                    onSave={() => mutateMeta({ id: diet.id, name: editName })}
                    onCancel={() => {
                        setEditName(diet.name)
                        setIsEditingMeta(false)
                    }}
                    showAssignmentBadge={showAssignmentBadge}
                    canAssign={canAssign}
                    assignments={diet.assignments}
                    students={students}
                    isEstimatingAll={isEstimatingAll}
                    onEstimateAll={handleEstimateAll}
                    contextLabel={contextLabel}
                    icon={icon}
                    contextColor={contextColor}
                />
            )}
            {/* ── Macro totals bar (isolated section) ── */}
            {!hideHeader && (
                <Grid cols={{ base: 6, md: 5 }} gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth>
                    {/* PROT */}
                    <GlassPanel padding={STORE_TOKENS.SPACING.ELEMENT} border="standard" colSpan={2} mdColSpan={1}>
                        <Stack gap={STORE_TOKENS.SPACING.TINY} align="center" justify="center">
                            <Font
                                variant="sub-tiny"
                                uppercase
                                weight="black"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.DIM,
                                }}>Prot</Font>
                            <Inline align="baseline" justify="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.INFO,
                                    }}>{Math.round(totals.p)}</Font>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                    }}>g</Font>
                            </Inline>
                        </Stack>
                    </GlassPanel>
                    {/* CARB */}
                    <GlassPanel padding={STORE_TOKENS.SPACING.ELEMENT} border="standard" colSpan={2} mdColSpan={1}>
                        <Stack gap={STORE_TOKENS.SPACING.TINY} align="center" justify="center">
                            <Font
                                variant="sub-tiny"
                                uppercase
                                weight="black"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.DIM,
                                }}>Carb</Font>
                            <Inline align="baseline" justify="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.BRAND,
                                    }}>{Math.round(totals.c)}</Font>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                    }}>g</Font>
                            </Inline>
                        </Stack>
                    </GlassPanel>
                    {/* GORD */}
                    <GlassPanel padding={STORE_TOKENS.SPACING.ELEMENT} border="standard" colSpan={2} mdColSpan={1}>
                        <Stack gap={STORE_TOKENS.SPACING.TINY} align="center" justify="center">
                            <Font
                                variant="sub-tiny"
                                uppercase
                                weight="black"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.DIM,
                                }}>Gord</Font>
                            <Inline align="baseline" justify="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.WARNING,
                                    }}>{Math.round(totals.f)}</Font>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                    }}>g</Font>
                            </Inline>
                        </Stack>
                    </GlassPanel>
                    {/* FIB */}
                    <GlassPanel padding={STORE_TOKENS.SPACING.ELEMENT} border="standard" colSpan={3} mdColSpan={1}>
                        <Stack gap={STORE_TOKENS.SPACING.TINY} align="center" justify="center">
                            <Font
                                variant="sub-tiny"
                                uppercase
                                weight="black"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.DIM,
                                }}>Fib</Font>
                            <Inline align="baseline" justify="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                                    }}>{Math.round(totals.fib)}</Font>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                    }}>g</Font>
                            </Inline>
                        </Stack>
                    </GlassPanel>
                    {/* KCAL */}
                    <GlassPanel padding={STORE_TOKENS.SPACING.ELEMENT} border="standard" colSpan={3} mdColSpan={1}>
                        <Stack gap={STORE_TOKENS.SPACING.TINY} align="center" justify="center">
                            <Font
                                variant="sub-tiny"
                                uppercase
                                weight="black"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                }}>Kcal</Font>
                            <Inline align="baseline" justify="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                    }}>
                                    {Math.round((totals.p * 4) + (totals.c * 4) + (totals.f * 9))}
                                </Font>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                    }}>kcal</Font>
                            </Inline>
                        </Stack>
                    </GlassPanel>
                </Grid>
            )}
            {/* Meals section */}
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                <Stack
                    direction={{ base: 'col', md: 'row' }}
                    align={{ base: 'start', md: 'center' }}
                    justify="between"
                    gap={STORE_TOKENS.SPACING.ELEMENT}
                >
                    <Font
                        variant="heading"
                        uppercase
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                        }}>
                        Refeições
                    </Font>
                    <Badge
                        label={`${meals.length} ${meals.length !== 1 ? 'refeições' : 'refeição'}`}
                        variant="glass"
                        color={(contextColor as any) || STORE_TOKENS.COLORS.BRAND}
                        size="sm"
                        rounded={STORE_TOKENS.RADIUS.SYSTEM}
                    />
                </Stack>

                {meals.length > 0 ? (
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        {meals.map((meal: any, index: number) => (
                            <DietBuilderMealCard
                                key={meal.id}
                                meal={meal}
                                index={index}
                                dietId={diet.id}
                                queryKey={queryKey}
                                isDragged={draggedMealId === meal.id}
                                draggedItemId={draggedItemId}
                                onMealDragStart={handleMealDragStart}
                                onMealDragOver={handleMealDragOver}
                                onMealDragEnd={handleMealDragEnd}
                                onItemDragStart={handleItemDragStart}
                                onItemDragOver={handleItemDragOver}
                                onItemDragEnd={handleItemDragEnd}
                                onRemoveMeal={(id) => {
                                    if (!confirm('Remover esta refeição inteira?')) return
                                    removeMealMutate({ id, dietId: diet.id })
                                }}
                                onRemoveItem={(id) => removeItemMutate({ id, dietId: diet.id })}
                                onAddItem={(mealId) => addItemMutate({ mealId, dietId: diet.id, foodId: 'default' })}
                            />
                        ))}
                    </Stack>
                ) : (
                    <EmptyState
                        icon={Utensils}
                        title="NENHUMA REFEIÇÃO ADICIONADA"
                        description="Use o formulário abaixo para começar."
                    />
                )}
            </Stack>
            {/* Add new meal form */}
            <DietBuilderNewMeal
                onAdd={(name) => addMealMutate({ dietId: diet.id, name })}
            />
            {/* Back navigation */}
            <Box display="flex" justify="center">
                <Button
                    asChild
                    variant="outline-zinc"
                    fullWidth={{ base: true, sm: false }}
                    paddingY={STORE_TOKENS.SPACING.ELEMENT}
                    paddingX={STORE_TOKENS.SPACING.CONTAINER}
                    gap={STORE_TOKENS.SPACING.ELEMENT}
                >
                    <Link href={backHref}>
                        <Icon icon={ArrowLeft} size="xs" />
                        Voltar para a Biblioteca de Dietas
                    </Link>
                </Button>
            </Box>
        </Stack>
    );
}

'use client'

import { useState, useEffect } from 'react'
import { impersonateUser } from '@/actions/admin-actions'
import { Button } from '@/components/store/base/button'
import { ShieldAlert, ArrowLeftRight, RefreshCw } from 'lucide-react'
import { useToast } from '@/hooks/use-toast'
import { Box } from '@/components/store/base/box'
import { Inline } from '@/components/store/base/layout'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Badge } from '@/components/store/base/badge'
import { Surface } from '@/components/store/base/surface'
import { RegistryColor } from './registry-context'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

export function ImpersonationBar({ color }: { color?: RegistryColor }) {
    const [mounted, setMounted] = useState(false)
    const [isImpersonating, setIsImpersonating] = useState(false)
    const [adminId, setAdminId] = useState<string | null>(null)
    const [loading, setLoading] = useState(false)
    const { toast } = useToast()

    useEffect(() => {
        setMounted(true)
        const checkStatus = () => {
            const cookies = document.cookie.split('; ')
            const imp = cookies.find(c => c.startsWith('rt_impersonating='))?.split('=')[1]
            const aid = cookies.find(c => c.startsWith('rt_admin_id='))?.split('=')[1]

            setIsImpersonating(imp === 'true')
            setAdminId(aid || null)
        }

        checkStatus()
        const interval = setInterval(checkStatus, 2000)
        return () => clearInterval(interval)
    }, [])

    if (!mounted || !isImpersonating || !adminId) return null

    const handleReturn = async () => {
        setLoading(true)
        toast({ title: 'Retornando ao Admin...', description: 'Estamos restaurando sua sessão original.' })

        const res = await impersonateUser(adminId)
        if (res?.error) {
            toast({ variant: 'destructive', title: 'Erro ao retornar', description: res.error })
            setLoading(false)
        }
    }

    const primaryColor = color || 'orange'
    const safeIconColor = primaryColor === 'zinc' ? 'zinc-400' : primaryColor

    return (
        <Box position="relative" fullWidth>
            <Surface
                variant={`tonal-${primaryColor}` as any}
                rounded={STORE_TOKENS.RADIUS.NONE}
                padding={STORE_TOKENS.PADDING.CONTAINER}
            >
                <Inline justify="between" align="center" gap={STORE_TOKENS.SPACING.CONTAINER}>
                    <Inline gap={STORE_TOKENS.SPACING.CONTAINER} align="center">
                        <Badge
                            label="Modo Inspeção Ativo"
                            icon={ShieldAlert}
                            variant="glass"
                            color={primaryColor}
                            rounded={STORE_TOKENS.RADIUS.FULL}
                        />
                        <Box display={{ base: 'none', md: 'block' }}>
                            <Font
                                variant="sub-tiny"
                                weight="bold"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                                }}>
                                Você está visualizando a plataforma como outro usuário. Todas as ações afetarão a conta dele.
                            </Font>
                        </Box>
                    </Inline>

                    <Button
                        onClick={handleReturn}
                        disabled={loading}
                        variant={`outline-${primaryColor}` as any}
                        size="sm"
                        rounded={STORE_TOKENS.RADIUS.FULL}
                    >
                        <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                            {loading ? (
                                <Icon icon={RefreshCw} size="xs" color={safeIconColor as any} animate="spin" />
                            ) : (
                                <Icon icon={ArrowLeftRight} size="xs" color={safeIconColor as any} />
                            )}
                            <Font
                                variant="label-caps"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                }}>Voltar ao Admin</Font>
                        </Inline>
                    </Button>
                </Inline>
            </Surface>
        </Box>
    );
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useToast } from '@/hooks/use-toast';
import { saveParsedData } from '@/actions/save-actions';
import { useTrainerOnboarding } from '@/hooks/use-trainer-onboarding';
import { QUERY_KEYS } from '@/lib/query-keys';
import { validateImportCompatibility } from '../lib/validators';
import { normalizeDays } from '@/lib/utils';

export function usePdfSaveFlow({ type, userId, role, initialStudentId, parsedData, setParsedData, selectionHooks, bindingHooks }: any) {
    const { toast } = useToast();
    const queryClient = useQueryClient();
    const { step: onboardingStep, nextStep } = useTrainerOnboarding(userId, { activeStudents: 0, workoutsCount: 0, dietsCount: 0 });

    const { mutate: handleSaveFinal, isPending: isSaving } = useMutation({
        mutationFn: async (variables: any) => {
            return await saveParsedData(variables.type, variables.data, variables.studentId, variables.createPlaceholder);
        },
        onSuccess: (result, variables) => {
            if (result.error) {
                toast({ variant: "destructive", title: "Erro ao salvar", description: result.error });
                return;
            }

            setParsedData(null);
            bindingHooks.setSelectedStudentId(null);
            selectionHooks.setSelectedOptionIndex(0);

            setTimeout(() => {
                const sid = variables.studentId || (result as any).data?.placeholderId || (result as any).results?.placeholderId;
                queryClient.invalidateQueries({ queryKey: ['trainer', 'student'] });
                if (sid) {
                    queryClient.invalidateQueries({ queryKey: QUERY_KEYS.ergogenics.all(sid) });
                    queryClient.invalidateQueries({ queryKey: QUERY_KEYS.cardio.assignments(sid) });
                }
                queryClient.invalidateQueries({ queryKey: ['trainer'] });
                queryClient.invalidateQueries({ queryKey: ['workouts'] });
                queryClient.invalidateQueries({ queryKey: ['diets'] });
                queryClient.invalidateQueries({ queryKey: ['cardio'] });
                queryClient.invalidateQueries({ queryKey: ['ergogenics'] });
            }, 800);

            if (onboardingStep === 'import_diet') {
                nextStep('aha_moment');
                const ghostInfo = variables.createPlaceholder || { name: bindingHooks.detectedStudentName || 'Aluno' };
                localStorage.setItem(`onboarding_ghost_${userId}`, JSON.stringify(ghostInfo));
            }

            toast({ title: "✅ Plano importado com sucesso", description: `${type === 'workout' ? 'Treino' : 'Dieta'} processado e vinculado.` });
        },
        onSettled: () => setTimeout(() => queryClient.invalidateQueries(), 1000)
    });

    const handleSave = () => {
        if (role === 'trainer' && type === 'workout' && parsedData?.parsed_data?.ergogenics?.length > 0 && !bindingHooks.selectedStudentId) {
            toast({ variant: "destructive", title: "Atenção!", description: "Ergogênicos detectados. Selecione um aluno para salvar o protocolo." });
            return;
        }

        const compatibilityError = validateImportCompatibility(type, parsedData);
        if (compatibilityError) {
            toast({ variant: "destructive", title: "Arquivo Incompatível", description: compatibilityError });
            return;
        }

        if (role === 'trainer' && bindingHooks.bindingMode === 'create' && !bindingHooks.placeholderEmail) {
            toast({ variant: "destructive", title: "Atenção: Email não informado!", description: "Sem o email você não consegue enviar o acesso automaticamente." });
        }

        let dataToSave = { ...parsedData.parsed_data };

        if (dataToSave.cardios) {
            dataToSave.cardios = dataToSave.cardios
                .filter((_: any, i: number) => selectionHooks.selectedCardioIndices.has(i))
                .map((c: any) => ({ ...c, application_days: normalizeDays(c.application_days) }));
        }
        if (dataToSave.ergogenics) {
            dataToSave.ergogenics = dataToSave.ergogenics.filter((_: any, i: number) => selectionHooks.selectedErgoIndices.has(i));
        }

        if (type === 'diet' && parsedData.parsed_data?.options?.length > 0) {
            const selectedOption = parsedData.parsed_data.options[selectionHooks.selectedOptionIndex];
            dataToSave = {
                ...dataToSave,
                diet_name: selectedOption.name,
                meals: selectedOption.meals,
                days_of_week: (selectionHooks.selectedDietDays && selectionHooks.selectedDietDays.length > 0) ? selectionHooks.selectedDietDays : (role === 'student' ? [0, 1, 2, 3, 4, 5, 6] : []),
            };
            delete dataToSave.options;
        } else if (type === 'diet') {
            dataToSave = { ...dataToSave, days_of_week: normalizeDays(selectionHooks.selectedDietDays) };
        }

        let createPlaceholderObj = undefined;
        if (role === 'trainer' && bindingHooks.bindingMode === 'create' && !bindingHooks.selectedStudentId) {
            createPlaceholderObj = {
                name: bindingHooks.placeholderName || bindingHooks.detectedStudentName || "Novo Aluno",
                email: bindingHooks.placeholderEmail,
                whatsapp: bindingHooks.placeholderWhatsapp
            };
        }

        const finalStudentId = bindingHooks.selectedStudentId || initialStudentId;

        handleSaveFinal({
            type,
            data: dataToSave,
            studentId: finalStudentId || undefined,
            createPlaceholder: createPlaceholderObj,
            userId
        });
    };

    return { handleSave, isSaving };
}

import { useState } from 'react';
import { useToast } from '@/hooks/use-toast';
import { createClient } from '@/lib/supabase/client';
import { parseUploadedPdf } from '@/actions/pdf-actions';
import { findStudentByName } from '@/actions/trainer-actions';
import { prepareCardios, prepareErgogenics } from '../lib/helpers';

export function usePdfUpload({ type, role, bindingHooks, selectionHooks }: any) {
    const [uploading, setUploading] = useState(false);
    const [parsing, setParsing] = useState(false);
    const [parsedData, setParsedData] = useState<any>(null);
    const { toast } = useToast();
    const supabase = createClient();

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!e.target.files || e.target.files.length === 0) return;
        const file = e.target.files[0];
        setUploading(true);

        try {
            const fileExt = file.name.split('.').pop();
            const fileName = `${Math.random()}.${fileExt}`;
            const filePath = `${fileName}`;

            const { error: uploadError } = await supabase.storage.from('pdfs').upload(filePath, file);
            if (uploadError) throw uploadError;

            toast({ title: "Arquivo enviado!", description: "Iniciando processamento com IA..." });
            setUploading(false);
            setParsing(true);

            const result = await parseUploadedPdf(filePath, type);
            if (result.error) throw new Error(result.error);

            setParsedData(result.data);
            selectionHooks.setSelectedOptionIndex(0);

            if (result.data) {
                const cardios = result.data.parsed_data?.cardios || [];
                const ergogenics = result.data.parsed_data?.ergogenics || [];

                const { updatedCardios, initialCardios } = prepareCardios(cardios, role === 'student');
                if (updatedCardios.length > 0) result.data.parsed_data.cardios = updatedCardios;
                selectionHooks.setSelectedCardioIndices(initialCardios);

                const { updatedErgos, initialErgos } = prepareErgogenics(ergogenics);
                if (updatedErgos.length > 0) result.data.parsed_data.ergogenics = updatedErgos;
                selectionHooks.setSelectedErgoIndices(initialErgos);
            }

            if (role === 'trainer' && result.data?.detected_student_name) {
                bindingHooks.setDetectedStudentName(result.data.detected_student_name);
                const match = await findStudentByName(result.data.detected_student_name);
                bindingHooks.setStudentMatch(match);
                if (match.exact) {
                    bindingHooks.setSelectedStudentId(match.exact.student_id);
                    bindingHooks.setBindingMode('matched');
                } else if (match.suggestions.length === 0) {
                    bindingHooks.setBindingMode('create');
                } else {
                    bindingHooks.setBindingMode('skip');
                }
            } else {
                bindingHooks.setDetectedStudentName(null);
                bindingHooks.setStudentMatch(null);
                bindingHooks.setBindingMode('skip');
            }

            toast({ title: "Processamento concluído!", description: "Revise os dados antes de salvar." });
        } catch (error: any) {
            toast({ variant: "destructive", title: "Falha na importação", description: error.message });
        } finally {
            setUploading(false);
            setParsing(false);
        }
    };

    return { uploading, parsing, parsedData, setParsedData, handleFileChange };
}

'use client'

import React, { useState } from 'react'
import { Modal } from '@/components/store/advanced/modal'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Inline } from '@/components/store/base/layout'
import { Input } from '@/components/store/base/input'
import { Button } from '@/components/store/base/button'
import { Banknote, AlertCircle } from 'lucide-react'
import { useToast } from '@/hooks/use-toast'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { ENTITIES } from '@/lib/outbox-db'
import { QUERY_KEYS } from '@/lib/query-keys'

interface RequestPayoutModalProps {
    isOpen: boolean
    onClose: () => void
    availableBalance: number
}

/**
 * RequestPayoutModal: Advanced component to handle payout request flow.
 * Fully compliant with Zero-Manual-Styling.
 */
export function RequestPayoutModal({ isOpen, onClose, availableBalance }: RequestPayoutModalProps) {
    const { toast } = useToast()
    const [amount, setAmount] = useState<string>('')
    const [pixKey, setPixKey] = useState<string>('')

    const { mutate, isPending } = useOptimisticMutation({
        actionName: 'request-payout',
        entity: ENTITIES.PAYOUT,
        entityId: 'new',
        queryKey: QUERY_KEYS.affiliate.earnings,
        mutationFn: async (variables: { amount: number, method: string, details: string }) => {
            const { requestPayout } = await import('@/actions/affiliate-actions')
            const res = await requestPayout(variables.amount, variables.method, variables.details)
            if (res.error) throw new Error(res.error)
            return res
        },
        onMutate: () => {
            toast({ title: 'Solicitação registrada!', description: 'Sua solicitação foi salva e será sincronizada.' })
            onClose()
            setAmount('')
            setPixKey('')
        },
        onSuccess: () => {
            toast({ title: 'Saque solicitado!', description: 'Nossa equipe processará o pagamento em breve.' })
        }
    })

    const handleMaxAmount = () => {
        setAmount(availableBalance.toFixed(2))
    }

    const handleSubmit = (e?: React.FormEvent) => {
        e?.preventDefault()

        const val = parseFloat(amount.replace(',', '.'))
        if (isNaN(val) || val < 50) {
            toast({ variant: 'destructive', title: 'Atenção', description: 'O valor mínimo para saque é de R$ 50,00.' })
            return
        }
        if (val > availableBalance) {
            toast({ variant: 'destructive', title: 'Atenção', description: 'Saldo insuficiente.' })
            return
        }
        if (!pixKey.trim()) {
            toast({ variant: 'destructive', title: 'Atenção', description: 'Por favor, informe a chave PIX.' })
            return
        }

        mutate({ amount: val, method: 'PIX', details: pixKey.trim() })
    }

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Solicitar Saque"
            subtitle="Transfira suas comissões confirmadas para sua conta via PIX."
            icon={Banknote}
            variant="emerald"
            confirmLabel={isPending ? 'Processando...' : 'Confirmar Saque'}
            cancelLabel="Cancelar"
            onConfirm={handleSubmit}
            isLoading={isPending}
            disabled={availableBalance < 50}
        >
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                {/* Balance Summary */}
                <Box padding={STORE_TOKENS.PADDING.CONTAINER} rounded={STORE_TOKENS.RADIUS.SYSTEM} bg={STORE_TOKENS.COLORS.BACKGROUND} bgOpacity={STORE_TOKENS.OPACITY.LOW} border>
                    <Inline justify="between" align="center">
                        <Font
                            variant="description"
                            weight="medium"
                            {...{
                                color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                            }}>Saldo Disponível:</Font>
                        <Font
                            variant="body"
                            weight="black"
                            {...{
                                color: STORE_TOKENS.COLORS.BRAND,
                            }}>
                            R$ {availableBalance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                        </Font>
                    </Inline>
                </Box>

                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    {/* Amount Input */}
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                        <Inline justify="between" align="center">
                            <Font
                                variant="sub-tiny"
                                weight="black"
                                uppercase
                                tracking="widest"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                                }}>
                                Valor do Saque (R$)
                            </Font>
                            <Button
                                variant="ghost"
                                padding={STORE_TOKENS.PADDING.NONE}
                                onClick={handleMaxAmount}
                            >
                                <Font
                                    variant="sub-tiny"
                                    weight="black"
                                    {...{
                                        color: STORE_TOKENS.COLORS.BRAND,
                                    }}>SAQUE TOTAL</Font>
                            </Button>
                        </Inline>

                        <Input
                            type="number"
                            step="0.01"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                            placeholder="0,00"
                            disabled={isPending}
                        />

                        <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                            <Icon icon={AlertCircle} size="xs" color={STORE_TOKENS.COLORS.TEXT.MUTED} />
                            <Font
                                variant="sub-tiny"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                }}>Mínimo de R$ 50,00</Font>
                        </Inline>
                    </Stack>

                    {/* PIX Key Input */}
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                        <Font
                            variant="sub-tiny"
                            weight="black"
                            uppercase
                            tracking="widest"
                            {...{
                                color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                            }}>
                            Chave PIX
                        </Font>
                        <Input
                            value={pixKey}
                            onChange={(e) => setPixKey(e.target.value)}
                            placeholder="CPF, Celular, E-mail ou Aleatória"
                            disabled={isPending}
                        />
                    </Stack>
                </Stack>
            </Stack>
        </Modal>
    );
}

'use client';

import { useState, useEffect } from 'react'
import { useToast } from "@/hooks/use-toast"
import { Ruler, Weight, User, ArrowRight, Target, Check } from "lucide-react"
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

// Design System Imports
import { Box } from '@/components/store/base/box'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Grid } from '@/components/store/base/grid'
import { Input } from '@/components/store/base/input'
import { FormSwitch } from '@/components/store/base/form-switch'
import { FormSelect } from '@/components/store/base/form-select'
import { Button } from '@/components/store/base/button'
import { Surface } from '@/components/store/base/surface'
import { Icon } from '@/components/store/base/icon'
import { Badge } from '@/components/store/base/badge'
import { STORE_TOKENS } from "@/components/store/constants/tokens"

export function AnamnesisForm({ initialData }: { initialData?: any }) {
    const { toast } = useToast()
    const queryClient = useQueryClient()

    const calculateAge = (birthDate: string) => {
        if (!birthDate) return null
        const today = new Date()
        const birth = new Date(birthDate)
        let age = today.getFullYear() - birth.getFullYear()
        const m = today.getMonth() - birth.getMonth()
        if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
            age--
        }
        return age
    }

    const studentAge = initialData?.birth_date ? calculateAge(initialData.birth_date) : initialData?.age

    const [formData, setFormData] = useState({
        sex: initialData?.sex || 'male',
        activity_level: initialData?.activity_level || 'moderate',
        height: initialData?.height || '',
        weight: initialData?.weight || initialData?.current_weight || initialData?.starting_weight || '',
        neck_cm: initialData?.neck_cm || '',
        waist_cm: initialData?.waist_cm || '',
        hip_cm: initialData?.hip_cm || '',
    })

    const [calculatedBF, setCalculatedBF] = useState<string | null>(null)

    useEffect(() => {
        const h = parseFloat(formData.height)
        const neck = parseFloat(formData.neck_cm)
        const waist = parseFloat(formData.waist_cm)
        const hip = parseFloat(formData.hip_cm)

        if (formData.sex === 'male') {
            if (!h || !waist || !neck || waist <= neck) {
                setCalculatedBF(null)
                return
            }
            const bf = 495 / (1.0324 - 0.19077 * Math.log10(waist - neck) + 0.15456 * Math.log10(h)) - 450
            setCalculatedBF(Math.max(2, bf).toFixed(1))
        } else {
            if (!h || !waist || !neck || !hip || (waist + hip) <= neck) {
                setCalculatedBF(null)
                return
            }
            const bf = 495 / (1.29579 - 0.35004 * Math.log10(waist + hip - neck) + 0.22100 * Math.log10(h)) - 450
            setCalculatedBF(Math.max(2, bf).toFixed(1))
        }
    }, [formData])

    const { mutate } = useOptimisticMutation({
        actionName: 'update-student-profile',
        entity: ENTITIES.STUDENT_DETAIL,
        entityId: initialData?.id || 'me',
        queryKey: QUERY_KEYS.student.metrics(initialData?.id || 'me'),
        mutationFn: async (variables: { obj: any }) => variables,
        onMutate: (variables) => {
            const previousMetrics = queryClient.getQueryData(QUERY_KEYS.student.metrics(initialData?.id))
            queryClient.setQueryData(QUERY_KEYS.student.metrics(initialData?.id), (old: any) => {
                if(!old) return old
                return { ...old, ...variables.obj, _optimistic: true }
            })
            return { previousMetrics }
        },
        onSuccess: () => {
            toast({ title: "Protocolo Atualizado!", description: "Suas métricas de elite foram calculadas e salvas." })
        },
        onError: (err, variables, ctx) => {
            queryClient.setQueryData(QUERY_KEYS.student.metrics(initialData?.id), ctx?.previousMetrics)
            toast({ variant: "destructive", title: "Erro inesperado", description: "Falha ao sincronizar métricas." })
        }
    })

    function handleSubmit(e: React.FormEvent) {
        e.preventDefault()
        const obj = {
            ...formData,
            body_fat: calculatedBF
        }
        mutate({ obj })
    }

    return (
        <Surface variant="glass" padding={STORE_TOKENS.PADDING.CONTAINER} rounded={STORE_TOKENS.RADIUS.SYSTEM} border="subtle">
            <form onSubmit={handleSubmit}>
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    
                    {/* Basic Info */}
                    <Grid mdCols={3} gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Input 
                            label="IDADE"
                            icon={<Icon icon={User} size="xs" />}
                            value={studentAge ? `${studentAge} anos` : '--'}
                            disabled
                            placeholder="--"
                        />
                        <Input
                            label="ALTURA (CM)"
                            icon={<Icon icon={Ruler} size="xs" />}
                            type="number"
                            placeholder="Ex: 180"
                            value={formData.height}
                            onChange={e => setFormData(prev => ({ ...prev, height: e.target.value }))}
                        />
                        <Input
                            label="PESO (KG)"
                            icon={<Icon icon={Weight} size="xs" />}
                            type="number"
                            placeholder="Ex: 80"
                            value={formData.weight}
                            onChange={e => setFormData(prev => ({ ...prev, weight: e.target.value }))}
                        />
                    </Grid>

                    {/* Navy Seal Measurements */}
                    <Box 
                        padding={STORE_TOKENS.PADDING.CONTAINER} 
                        bg={STORE_TOKENS.COLORS.SUCCESS as any} 
                        bgOpacity={STORE_TOKENS.OPACITY.LOW} 
                        border 
                        borderColor={STORE_TOKENS.COLORS.SUCCESS as any} 
                        borderOpacity={STORE_TOKENS.OPACITY.MEDIUM}
                        rounded={STORE_TOKENS.RADIUS.SYSTEM} 
                        position="relative" 
                        overflow="hidden" 
                    >
                        <Box position="absolute" pin="right" top={0} padding={STORE_TOKENS.PADDING.CONTAINER} opacity={STORE_TOKENS.OPACITY.SUBTLE}>
                            <Icon icon={Target} size="xl" color={STORE_TOKENS.COLORS.SUCCESS} />
                        </Box>

                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER} position="relative" zIndex={STORE_TOKENS.Z_INDEX.CONTENT}>
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT} wrap="wrap">
                                    <Font
                                        variant="tiny"
                                        weight="black"
                                        italic
                                        uppercase
                                        tracking="widest"
                                        {...{
                                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                        }}>
                                        Medições Antropométricas
                                    </Font>
                                    <Badge label="Precisão Máxima" color={STORE_TOKENS.COLORS.SUCCESS} variant="glass" size="xs" />
                                </Stack>
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    italic
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                    }}>
                                    Insira suas medidas exatas com fita métrica para o cálculo de elite.
                                </Font>
                            </Stack>

                            <Grid mdCols={3} gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <Input
                                    label="PESCOÇO (CM)"
                                    type="number"
                                    placeholder="Ex: 40"
                                    value={formData.neck_cm}
                                    onChange={e => setFormData(prev => ({ ...prev, neck_cm: e.target.value }))}
                                />
                                <Input
                                    label="CINTURA - UMBIGO (CM)"
                                    type="number"
                                    placeholder="Ex: 82"
                                    value={formData.waist_cm}
                                    onChange={e => setFormData(prev => ({ ...prev, waist_cm: e.target.value }))}
                                />
                                {formData.sex === 'female' && (
                                    <Input
                                        label="QUADRIL (CM)"
                                        type="number"
                                        placeholder="Ex: 95"
                                        value={formData.hip_cm}
                                        onChange={e => setFormData(prev => ({ ...prev, hip_cm: e.target.value }))}
                                    />
                                )}
                            </Grid>
                        </Stack>
                    </Box>

                    {/* Sex & Activity & Status Grid */}
                    <Grid mdCols={2} gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <FormSwitch
                                label="GÊNERO BIOLÓGICO"
                                options={[
                                    { label: 'MASCULINO', value: 'male' },
                                    { label: 'FEMININO', value: 'female' }
                                ]}
                                value={formData.sex}
                                onChange={(v) => setFormData(prev => ({ ...prev, sex: v }))}
                                color={STORE_TOKENS.COLORS.SUCCESS}
                            />

                            <FormSelect
                                label="NÍVEL DE ATIVIDADE"
                                value={formData.activity_level}
                                onChange={(v) => setFormData(prev => ({ ...prev, activity_level: v }))}
                                options={[
                                    { value: 'sedentary', label: 'Sedentário (Nenhum exercício)' },
                                    { value: 'light', label: 'Leve (1-3 dias/semana)' },
                                    { value: 'moderate', label: 'Moderado (3-5 dias/semana)' },
                                    { value: 'active', label: 'Intenso (6-7 dias/semana)' },
                                    { value: 'athlete', label: 'Elite (Atleta prof.)' }
                                ]}
                            />
                        </Stack>

                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER} justify="end">
                            {/* Navy Seal Result Card */}
                            <Box 
                                padding={STORE_TOKENS.PADDING.CONTAINER} 
                                rounded={STORE_TOKENS.RADIUS.SYSTEM} 
                                border 
                                transition 
                                bg={calculatedBF ? (STORE_TOKENS.COLORS.SUCCESS as any) : (STORE_TOKENS.COLORS.BACKGROUND as any)}
                                bgOpacity={calculatedBF ? STORE_TOKENS.OPACITY.LOW : STORE_TOKENS.OPACITY.SUBTLE}
                                borderColor={calculatedBF ? (STORE_TOKENS.COLORS.SUCCESS as any) : (STORE_TOKENS.COLORS.DIVIDER.STANDARD as any)}
                                borderOpacity={calculatedBF ? STORE_TOKENS.OPACITY.MEDIUM : undefined}
                                opacity={calculatedBF ? STORE_TOKENS.OPACITY.FULL : STORE_TOKENS.OPACITY.MODAL}
                            >
                                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                                    <Stack direction="row" align="center" justify="between">
                                        <Font
                                            variant="sub-tiny"
                                            weight="black"
                                            uppercase
                                            tracking="widest"
                                            {...{
                                                color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                            }}>
                                            Estimativa Navy Seal
                                        </Font>
                                        {calculatedBF && <Icon icon={Check} color={STORE_TOKENS.COLORS.SUCCESS} size="sm" />}
                                    </Stack>

                                    <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Stack direction="row" align="baseline" gap={STORE_TOKENS.SPACING.NONE}>
                                            <Font
                                                variant="h3"
                                                weight="black"
                                                italic
                                                {...{
                                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                }}>
                                                {calculatedBF || '--.-'}
                                            </Font>
                                            <Font
                                                variant="body"
                                                weight="black"
                                                italic
                                                {...{
                                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                }}>
                                                %
                                            </Font>
                                        </Stack>
                                        
                                        <Box display={{ base: 'none', lg: 'block' }} padding={STORE_TOKENS.PADDING.NONE}>
                                            <Box width="px" height="full" bg={STORE_TOKENS.COLORS.WHITE as any} bgOpacity={STORE_TOKENS.OPACITY.SUBTLE} />
                                        </Box>

                                        <Box flex1 display={{ base: 'none', lg: 'block' }}>
                                            <Stack gap={STORE_TOKENS.SPACING.NONE}>
                                                <Font
                                                    variant="h3"
                                                    weight="black"
                                                    uppercase
                                                    italic
                                                    {...{
                                                        color: !calculatedBF ? STORE_TOKENS.COLORS.TEXT.MUTED : 
                                                        parseFloat(calculatedBF) < 10 ? 'emerald' : 
                                                        parseFloat(calculatedBF) < 15 ? 'blue' : 
                                                        parseFloat(calculatedBF) < 20 ? 'amber' : 'red',
                                                    }}>
                                                    {calculatedBF ? (parseFloat(calculatedBF) < 10 ? 'ELITE' : parseFloat(calculatedBF) < 15 ? 'ATLETA' : parseFloat(calculatedBF) < 20 ? 'FITNESS' : 'INICIANTE') : 'Aguardando Medições'}
                                                </Font>
                                            </Stack>
                                        </Box>
                                    </Stack>
                                </Stack>
                            </Box>

                            <Button 
                                type="submit" 
                                disabled={!calculatedBF} 
                                variant="primary" 
                                size="lg" 
                                fullWidth 
                                gap={STORE_TOKENS.SPACING.ELEMENT}
                            >
                                Salvar Dados Antropométricos
                                <Icon icon={ArrowRight} size="sm" />
                            </Button>
                        </Stack>
                    </Grid>

                </Stack>
            </form>
        </Surface>
    );
}

'use client'

import React from 'react'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { ErgogenicsList } from '@/components/store/intermediary/ergogenics-list'
import { FlaskConical } from 'lucide-react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getStudentErgogenics, getTodayErgogenicLogs, toggleErgogenicLog } from '@/actions/ergogenics-actions'
import { Box } from '@/components/store/base/box'

interface StudentBioactivesManagementProps {
    userId: string
}

/**
 * StudentBioactivesManagement (Smart): Manages ergogenic data and logs.
 * Now functional with toggle capabilities.
 */
export function StudentBioactivesManagement({ userId }: StudentBioactivesManagementProps) {
    const queryClient = useQueryClient()

    const { data: items, isLoading } = useQuery<any[]>({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        queryFn: async () => {
            const res = await getStudentErgogenics(userId)
            return Array.isArray(res) ? res : []
        },
        staleTime: 1000 * 60 * 5,
        refetchOnMount: false,
    })

    const { data: logs } = useQuery<any[]>({
        queryKey: QUERY_KEYS.ergogenics.logs(userId),
        queryFn: () => getTodayErgogenicLogs(userId),
        staleTime: 1000 * 60 * 5,
        refetchOnMount: false,
    })

    const toggleMutation = useMutation({
        mutationFn: ({ id, currentStatus }: { id: string, currentStatus: boolean }) =>
            toggleErgogenicLog(userId, id, !currentStatus),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.ergogenics.logs(userId) })
        }
    })

    if (isLoading) return <RegistrySection title="BIOATIVOS DE HOJE" subtitle="Gestão diária de protocolos auxiliares." icon={FlaskConical}><Box /></RegistrySection>

    // Timezone logic for Brazil
    const today = (() => {
        try {
            const brazilTime = new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })
            return new Date(brazilTime).getDay()
        } catch {
            return new Date().getDay()
        }
    })()

    const todayItems = Array.isArray(items) ? items.filter((item: any) => {
        const days = Array.isArray(item.application_days) ? item.application_days : []
        return days.map((d: any) => Number(d)).includes(today)
    }) : []

    if (todayItems.length === 0) {
        return (
            <RegistrySection title="BIOATIVOS DE HOJE" subtitle="Gestão diária de protocolos auxiliares." icon={FlaskConical}>
                <ErgogenicsList items={[]} status="empty" />
            </RegistrySection>
        )
    }

    return (
        <RegistrySection
            title="BIOATIVOS DE HOJE"
            subtitle="Gestão diária de protocolos auxiliares."
            icon={FlaskConical}
        >
            <ErgogenicsList
                items={todayItems.map((item: any) => ({
                    id: item.id,
                    name: item.name.toUpperCase(),
                    dosage: `${(item.weekly_dosage / (item.application_days?.length || 1)).toFixed(2)} ${item.unit?.toUpperCase() || 'MG'}`,
                    isCompleted: !!logs?.some((l: any) => l.ergogenic_id === item.id)
                }))}
                status="active"
                onToggle={(id, currentStatus) => toggleMutation.mutate({ id, currentStatus })}
            />
        </RegistrySection>
    )
}

'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getStudentCardioAssignments, getCardioLibrary } from '@/actions/cardio-actions'
import { getStudentProfile, getStudentTrainer } from '@/actions/student-actions'
import { useRealtimeSync } from '@/hooks/use-realtime-sync'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { CardioManagementSectionContent } from '@/components/store/sections/cardio-management-section-content'
import { Stack } from '@/components/store/base/stack'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Grid } from '@/components/store/base/grid'

interface StudentCardioManagementSmartProps {
    userId: string
}

export function StudentCardioManagementSmart({ userId }: StudentCardioManagementSmartProps) {
    // 1. Data Fetching
    const { data: profile } = useQuery({
        queryKey: QUERY_KEYS.student.details(userId),
        queryFn: () => getStudentProfile(userId),
        staleTime: 1000 * 60 * 5
    })

    const { data: trainerLink } = useQuery({
        queryKey: QUERY_KEYS.profile.trainer(userId),
        queryFn: () => getStudentTrainer(userId),
        staleTime: 1000 * 60 * 5
    })

    const { data: assignments = [] } = useQuery({
        queryKey: QUERY_KEYS.cardio.all(userId),
        queryFn: () => getStudentCardioAssignments(userId),
        staleTime: 1000 * 60 * 5
    })

    const isAutoTrainingActive = profile?.auto_training_status === 'active' || profile?.auto_training_status === 'trial'
    const hasTrainer = !!trainerLink
    const isAutoMode = isAutoTrainingActive && !hasTrainer

    const { data: libraryCardios = [] } = useQuery({
        queryKey: QUERY_KEYS.cardio.library(userId),
        queryFn: () => getCardioLibrary(userId),
        enabled: isAutoMode,
        staleTime: 1000 * 60 * 5
    })

    // 2. Realtime Sync
    useRealtimeSync({
        table: 'assigned_cardios',
        queryKey: QUERY_KEYS.cardio.all(userId),
        filter: `student_id=eq.${userId}`
    })

    useRealtimeSync({
        table: 'cardios',
        queryKey: QUERY_KEYS.cardio.library(userId),
        filter: `trainer_id=eq.${userId}`
    })

    // 3. Logic: Group assignments and determine display data
    let displayCardios = []

    if (isAutoMode) {
        const assignmentsByCardio = assignments.reduce((acc: any, curr: any) => {
            const cId = curr.cardio_id
            if (!cId) return acc
            if (!acc[cId]) acc[cId] = []

            if (curr.days_of_week && Array.isArray(curr.days_of_week)) {
                curr.days_of_week.forEach((d: number) => {
                    if (!acc[cId].includes(d)) acc[cId].push(d)
                })
            } else if (curr.day_of_week !== null && curr.day_of_week !== undefined) {
                if (!acc[cId].includes(curr.day_of_week)) acc[cId].push(curr.day_of_week)
            }
            return acc
        }, {})

        displayCardios = libraryCardios.map(c => ({
            ...c,
            assigned_cardios: (assignmentsByCardio[c.id] || []).map((d: number) => ({ day_of_week: d }))
        }))
    } else {
        const grouped = assignments.reduce((acc: any, curr: any) => {
            const cId = curr.cardio_id || curr.id
            if (!cId) return acc
            if (!acc[cId]) {
                acc[cId] = {
                    ...(curr.cardio || curr),
                    assigned_cardios: []
                }
            }

            const addDay = (d: number) => {
                if (!acc[cId].assigned_cardios.some((a: any) => a.day_of_week === d)) {
                    acc[cId].assigned_cardios.push({ day_of_week: d })
                }
            }

            if (curr.days_of_week && Array.isArray(curr.days_of_week)) {
                curr.days_of_week.forEach((d: number) => addDay(d))
            } else if (curr.day_of_week !== null && curr.day_of_week !== undefined) {
                addDay(curr.day_of_week)
            }

            return acc
        }, {})
        displayCardios = Object.values(grouped)
    }

    return (
        <Grid cols={{ base: 1, md: 12 }} gap={STORE_TOKENS.SPACING.SECTION} fullWidth flex1>
            {/* Cardio Management */}
            <Stack mdColSpan={12} flex1 gap={STORE_TOKENS.SPACING.SECTION}>
                <RegistrySection>
                    <CardioManagementSectionContent 
                        userId={userId}
                        cardios={displayCardios}
                        mode={isAutoMode ? 'auto' : 'personal'}
                    />
                </RegistrySection>
            </Stack>
        </Grid>
    )
}

'use client'

import React, { useState } from 'react'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Stack } from '@/components/store/base/stack'
import { CardioTimerCard } from '@/components/store/intermediary/cardio-timer-card'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Activity, ChevronLeft, ChevronRight } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTodayCardio, getCardioStatus } from '@/actions/cardio-actions'
import { Button } from '@/components/store/base/button'
import { Icon } from '@/components/store/base/icon'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { 
    startCardioSession, 
    updateCardioSession, 
    finishCardioSession, 
    getActiveCardioSession 
} from '@/actions/cardio-actions'
import { useQueryClient } from '@tanstack/react-query'
import { useToast } from '@/hooks/use-toast'
import { Modal } from '@/components/store/advanced/modal'

interface StudentCardioTrackerProps {
    userId: string
}

/**
 * StudentCardioTracker (Smart): Manages cardio protocols and status.
 * Uses duration_minutes and suggested_intensity from database.
 */
export function StudentCardioTracker({ userId }: StudentCardioTrackerProps) {
    const { toast } = useToast()
    const queryClient = useQueryClient()
    const [currentIndex, setCurrentIndex] = useState(0)
    
    // Player State
    const [status, setStatus] = useState<'idle' | 'running' | 'paused'>('idle')
    const [seconds, setSeconds] = useState(0)
    const [logId, setLogId] = useState<string | null>(null)
    const [isConfirmOpen, setIsConfirmOpen] = useState(false)
    const timerRef = React.useRef<NodeJS.Timeout | null>(null)
    const lastSyncRef = React.useRef<{ seconds: number, status: string }>({ seconds: 0, status: 'idle' })

    const { data: cardios, isLoading } = useQuery<any[]>({
        queryKey: QUERY_KEYS.cardio.today(userId),
        queryFn: () => getTodayCardio(userId),
        staleTime: 1000 * 60 * 5,
    })

    const { data: cardioLogs } = useQuery<any[]>({
        queryKey: QUERY_KEYS.cardio.logs(userId),
        queryFn: () => getCardioStatus(userId),
        staleTime: 1000 * 60 * 5,
    })

    const { data: activeSession } = useQuery({
        queryKey: QUERY_KEYS.cardio.session,
        queryFn: () => getActiveCardioSession(),
        staleTime: 1000 * 30
    })

    // Sync local state with activeSession
    React.useEffect(() => {
        if (activeSession && status === 'idle') {
            const assignment = cardios?.find(c => c.id === activeSession.assigned_cardio_id)
            if (assignment) {
                const idx = cardios?.findIndex(c => c.id === assignment.id) ?? 0
                setCurrentIndex(idx)
                
                setLogId(activeSession.id)
                let currentElapsed = activeSession.elapsed_seconds || 0
                
                if (activeSession.is_running) {
                    const lastResumed = new Date(activeSession.last_resumed_at || activeSession.last_heartbeat_at).getTime()
                    const diff = Math.floor((Date.now() - lastResumed) / 1000)
                    currentElapsed += Math.max(0, diff)
                }
                
                setSeconds(currentElapsed)
                setStatus(activeSession.is_running ? 'running' : 'paused')
                
                if (activeSession.is_running) {
                    startTimer(Date.now() - (currentElapsed * 1000))
                }
            }
        }
    }, [activeSession, cardios])

    // Periodic Sync Effect
    React.useEffect(() => {
        if (!logId || status === 'idle') return

        const syncInterval = setInterval(() => {
            const hasStatusChanged = lastSyncRef.current.status !== status
            const hasTimeProgressed = Math.abs(lastSyncRef.current.seconds - seconds) >= 10

            if (hasStatusChanged || hasTimeProgressed) {
                updateCardioSession(logId, seconds, status === 'running')
                lastSyncRef.current = { seconds, status }
            }
        }, 10000)

        return () => clearInterval(syncInterval)
    }, [logId, status, seconds])

    // Auto stop when timer finishes
    React.useEffect(() => {
        if (status === 'running' && logId) {
            const currentCardio = cardios?.[currentIndex]
            if (currentCardio) {
                const targetSeconds = (currentCardio.duration_minutes || 30) * 60
                if (seconds >= targetSeconds) {
                    stopTimer()
                    setStatus('idle')
                    setSeconds(0)
                    setLogId(null)
                    
                    finishCardioSession(logId, 'Concluído automaticamente', undefined, 100).then((res) => {
                        if (res.success) {
                            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.cardio.logs(userId) })
                            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.cardio.session })
                            toast({
                                title: "Sucesso",
                                description: "Cardio concluído automaticamente por atingir o tempo!"
                            })
                        }
                    })
                }
            }
        }
    }, [seconds, status, logId, cardios, currentIndex, userId, queryClient, toast])

    function startTimer(virtualStart: number) {
        if (timerRef.current) clearInterval(timerRef.current)
        timerRef.current = setInterval(() => {
            const diff = Math.floor((Date.now() - virtualStart) / 1000)
            setSeconds(diff)
        }, 1000)
    }

    function stopTimer() {
        if (timerRef.current) clearInterval(timerRef.current)
        timerRef.current = null
    }

    async function handleStart() {
        const currentCardio = cardios?.[currentIndex]
        if (!currentCardio) return

        if (!logId) {
            const res = await startCardioSession(currentCardio.id)
            if (res.success && res.logId) {
                setLogId(res.logId)
                setStatus('running')
                startTimer(Date.now())
            } else {
                toast({
                    title: "Erro",
                    description: "Erro ao iniciar sessão",
                    variant: "destructive"
                })
            }
        } else {
            setStatus('running')
            updateCardioSession(logId, seconds, true)
            startTimer(Date.now() - (seconds * 1000))
        }
    }

    function handlePause() {
        setStatus('paused')
        stopTimer()
        if (logId) {
            updateCardioSession(logId, seconds, false)
        }
    }

    async function handleStop() {
        if (!logId) return
        setIsConfirmOpen(true)
    }

    async function handleStopConfirm() {
        if (!logId) return
        const currentCardio = cardios?.[currentIndex]
        const targetSeconds = (currentCardio?.duration_minutes || 30) * 60
        const progress = Math.min(Math.round((seconds / targetSeconds) * 100), 100)

        const res = await finishCardioSession(logId, undefined, undefined, progress)
        if (res.success) {
            setStatus('idle')
            setSeconds(0)
            setLogId(null)
            stopTimer()
            setIsConfirmOpen(false)
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.cardio.logs(userId) })
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.cardio.session })
            toast({
                title: "Sucesso",
                description: "Cardio finalizado!"
            })
        } else {
            toast({
                title: "Erro",
                description: "Erro ao finalizar sessão",
                variant: "destructive"
            })
        }
    }

    function formatTime(s: number, targetMins: number) {
        const targetSecs = targetMins * 60
        const remaining = Math.max(targetSecs - s, 0)
        const mins = Math.floor(remaining / 60)
        const secs = remaining % 60
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
    }

    if (isLoading) return <RegistrySection title="CARDIO DE HOJE" icon={Activity}><Box className="animate-pulse h-48 bg-zinc-900/50 rounded-3xl" /></RegistrySection>

    if (!cardios || cardios.length === 0) {
        return (
            <RegistrySection title="CARDIO DE HOJE" icon={Activity}>
                <CardioTimerCard
                    title="SEM CARDIO"
                    duration="0 MIN"
                    intensity="-"
                    remainingTime="00:00"
                    estimatedBurn="0"
                    status="empty"
                />
            </RegistrySection>
        )
    }

    const currentCardio = cardios[currentIndex] || cardios[0]
    const completedLog = cardioLogs?.find(l => l.assigned_cardio_id === currentCardio.id && l.status === 'completed')
    const isCompleted = !!completedLog

    const next = () => {
        if (status !== 'idle') return
        setCurrentIndex(prev => (prev + 1) % cardios.length)
    }
    const prev = () => {
        if (status !== 'idle') return
        setCurrentIndex(prev => (prev - 1 + cardios.length) % cardios.length)
    }

    const targetMinutes = currentCardio.duration_minutes || 0
    const displayMinutes = isCompleted ? Math.round((completedLog.elapsed_seconds || 0) / 60) : targetMinutes
    const progress = Math.min((seconds / (targetMinutes * 60)) * 100, 100)

    return (
        <RegistrySection
            title="CARDIO DE HOJE"
            subtitle="Monitoramento de atividades aeróbicas e cronômetros."
            icon={Activity}
            rightElement={cardios.length > 1 && status === 'idle' ? (
                <Stack direction="row" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Button variant="outline-zinc" isIconOnly size="sm" onClick={prev}>
                        <Icon icon={ChevronLeft} size="xs" />
                    </Button>
                    <Button variant="outline-zinc" isIconOnly size="sm" onClick={next}>
                        <Icon icon={ChevronRight} size="xs" />
                    </Button>
                </Stack>
            ) : undefined}
        >
            <CardioTimerCard
                title={currentCardio.cardio?.name?.toUpperCase() || currentCardio.name?.toUpperCase() || 'ATIVIDADE AERÓBICA'}
                duration={`${displayMinutes} MIN`}
                intensity={currentCardio.suggested_intensity?.toUpperCase() || 'MODERADA'}
                remainingTime={isCompleted ? "00:00" : formatTime(seconds, targetMinutes)}
                estimatedBurn={currentCardio.estimated_calories?.toString() || '0'}
                status={isCompleted ? 'completed' : 'not_started'}
                isRunning={status === 'running'}
                progress={progress}
                onPlay={handleStart}
                onPause={handlePause}
                onStop={handleStop}
            />
            <Modal
                isOpen={isConfirmOpen}
                onClose={() => setIsConfirmOpen(false)}
                onConfirm={handleStopConfirm}
                title="Encerrar Atividade?"
                subtitle="Deseja realmente finalizar a atividade de cardio atual?"
                confirmLabel="Finalizar"
                cancelLabel="Continuar"
                variant="red"
                confirmVariant="outline-red"
            >
                <Font
                    variant="description"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                    }}>
                    Você realizou {Math.floor(seconds / 60)} minuto(s) de atividade. Ao encerrar agora, o progresso será salvo proporcionalmente.
                </Font>
            </Modal>
        </RegistrySection>
    );
}

'use client';
import { STORE_TOKENS } from '@/components/store/constants/tokens';

import { useState, useEffect } from 'react'
import { Modal } from '@/components/store/advanced/modal'
import { Font } from '@/components/store/base/font'
import { Stack } from '@/components/store/base/stack'
import { Sparkles } from 'lucide-react'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

interface StudentDashboardModalProps {
    userId: string
    showModal: boolean
    hasTrainer: boolean
}

export function StudentDashboardModals({ userId, showModal, hasTrainer }: StudentDashboardModalProps) {
    const [isModalOpen, setIsModalOpen] = useState(false)
    const [isImpersonating, setIsImpersonating] = useState(false)

    useEffect(() => {
        if (showModal && !hasTrainer) {
            setIsModalOpen(true)
        }

        // Check impersonation status
        const cookies = document.cookie.split('; ')
        const imp = cookies.find(c => c.startsWith('rt_impersonating='))?.split('=')[1]
        setIsImpersonating(imp === 'true')
    }, [showModal, hasTrainer])

    useEffect(() => {
        const handleOpen = () => setIsModalOpen(true)
        window.addEventListener('open-auto-training-onboarding', handleOpen)
        return () => window.removeEventListener('open-auto-training-onboarding', handleOpen)
    }, [])

    const { mutate: acceptMutate } = useOptimisticMutation({
        actionName: 'enable-auto-training-trial',
        entity: ENTITIES.USER,
        entityId: userId,
        queryKey: QUERY_KEYS.student.all(userId),
        mutationFn: async () => {
             const { enableAutoTrainingTrialForCurrentUser } = await import('@/actions/auto-training-actions')
             return await enableAutoTrainingTrialForCurrentUser()
        },
        onMutate: () => setIsModalOpen(false)
    })

    const { mutate: rejectMutate } = useOptimisticMutation({
        actionName: 'dismiss-auto-training',
        entity: ENTITIES.USER,
        entityId: userId,
        queryKey: QUERY_KEYS.student.all(userId),
        mutationFn: async () => {
             const { dismissAutoTrainingForSession } = await import('@/actions/auto-training-actions')
             return await dismissAutoTrainingForSession(userId)
        },
        onMutate: () => setIsModalOpen(false)
    })

    const handleAccept = async () => acceptMutate(undefined)
    const handleReject = async () => rejectMutate(undefined)
    const handleClose = () => setIsModalOpen(false)

    return (
        <Modal
            isOpen={isModalOpen && !isImpersonating}
            onClose={handleReject}
            title="Experimente o Auto Treino"
            subtitle="Inteligência Artificial para sua Performance"
            icon={Sparkles}
            confirmLabel="Iniciar Teste Grátis"
            cancelLabel="Agora Não"
            onConfirm={handleAccept}
            variant="orange"
            confirmVariant="primary"
        >
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="body"
                        weight="bold"
                        {...{
                            color: "white",
                        }}>
                        Monte seu treino, cardio e dieta de forma inteligente!
                    </Font>
                    <Font
                        variant="description"
                        {...{
                            color: "zinc-400",
                        }}>
                        O Auto Treino utiliza nossa IA avançada para construir protocolos personalizados sob medida para o seu corpo e rotina.
                    </Font>
                </Stack>
                <Stack gap={STORE_TOKENS.SPACING.NONE}>
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        tracking="widest"
                        {...{
                            color: "primary",
                        }}>
                        ✓ IMPORTAÇÃO IA DE PDFS (TREINO/DIETA)
                    </Font>
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        tracking="widest"
                        {...{
                            color: "primary",
                        }}>
                        ✓ PLAYER DE TREINO PROFISSIONAL
                    </Font>
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        tracking="widest"
                        {...{
                            color: "primary",
                        }}>
                        ✓ GESTÃO DE CARDIO E ERGOGÊNICOS
                    </Font>
                </Stack>
            </Stack>
        </Modal>
    );
}

