        staleTime: 1000 * 60 * 5
    })

    const { data: trainerLink } = useQuery({
        queryKey: QUERY_KEYS.profile.trainer(userId),
        queryFn: () => getStudentTrainer(userId),
        staleTime: 1000 * 60 * 5
    })

    const { data: ergogenicsData = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        queryFn: async () => {
            const res = await getStudentErgogenics(userId)
            if (Array.isArray(res)) return res
            return []
        },
        staleTime: 1000 * 60 * 5
    })

    const ergogenics = Array.isArray(ergogenicsData) ? ergogenicsData : []

    const isAutoMode = !trainerLink

    // 2. Realtime Sync
    useRealtimeSync({
        table: 'ergogenics',
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        filter: `student_id=eq.${userId}`
    })

    React.useEffect(() => {
        const handler = (e: any) => {
            if (e.detail?.type === 'create_ergogenic') {
                openAction('create_ergogenic', {})
            }
        }
        window.addEventListener('open-ergogenic-action', handler)
        return () => window.removeEventListener('open-ergogenic-action', handler)
    }, [])

    // 3. Mutations
    const { mutate: deleteMutation } = useOptimisticMutation({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        entity: ENTITIES.ERGOGENIC,
        actionName: 'delete-ergogenic',
        mutationFn: async ({ id }: { id: string }) => {
            const res = await deleteErgogenic(id, userId)
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const { mutate: duplicateMutation } = useOptimisticMutation({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        entity: ENTITIES.ERGOGENIC,
        actionName: 'duplicate-ergogenic',
        mutationFn: async ({ item }: { item: any }) => {
            const { id, created_at, updated_at, ...data } = item
            const res = await addErgogenic({ 
                ...data, 
                name: `${item.name} (Cópia)`,
                student_id: userId 
            })
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const { mutate: assignMutation } = useOptimisticMutation({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        entity: ENTITIES.ERGOGENIC,
        actionName: 'assign-ergogenic',
        mutationFn: async ({ ergogenicId, days }: { ergogenicId: string, days: number[] }) => {
            const res = await updateErgogenic(ergogenicId, userId, { application_days: days })
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const { mutate: createMutation } = useOptimisticMutation({
        queryKey: QUERY_KEYS.ergogenics.all(userId),
        entity: ENTITIES.ERGOGENIC,
        actionName: 'add-ergogenic',
        mutationFn: async (data: any) => {
            const res = await addErgogenic({ ...data, student_id: userId })
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const handleConfirm = (data?: any) => {
        if (!actionModal.data && actionModal.type !== ('create_ergogenic' as any)) return

        switch (actionModal.type) {
            case 'confirm_delete':
                deleteMutation({ id: actionModal.data.id })
                break
            case 'confirm_duplicate':
                duplicateMutation({ item: actionModal.data })
                break
            case 'assign_ergogenic':
                if (Array.isArray(data)) {
                    assignMutation({ ergogenicId: actionModal.data.id, days: data })
                }
                break
            case ('create_ergogenic' as any):
                createMutation(data)
                break
        }
        closeAction()
    }

    const openAction = (type: RegistryActionType, data?: any) => {
        setActionModal({ 
            isOpen: true, 
            type, 
            data: { 
                ...data, 
                item: data?.name, 
                dosage: data?.weekly_dosage,
                selectedDays: data?.application_days || [] 
            } 
        })
    }

    const closeAction = () => setActionModal(prev => ({ ...prev, isOpen: false }))

    return (
        <RegistrySection>
            <ErgogenicManagementSectionContent 
                items={ergogenics}
                mode={isAutoMode ? 'auto' : 'personal'}
                onEdit={(item) => openAction('edit_ergogenic', item)}
                onDelete={(item) => openAction('confirm_delete', item)}
                onDuplicate={(item) => openAction('confirm_duplicate', item)}
                onSchedule={(item) => openAction('assign_ergogenic', item)}
            />

            <RegistryActionModal 
                isOpen={actionModal.isOpen}
                onClose={closeAction}
                type={actionModal.type}
                onConfirm={handleConfirm}
                initialData={actionModal.data}
                isLoading={false}
            />
        </RegistrySection>
    )
}

'use client'

import React, { useMemo } from 'react'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { DietAdherenceCard } from '@/components/store/advanced/diet-adherence-card'
import { Utensils } from 'lucide-react'
import { useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { useStudentDailyDiet } from '@/lib/dal'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { ENTITIES } from '@/lib/outbox-db'
import { Box } from '@/components/store/base/box'

interface StudentNutritionAdherenceProps {
    userId: string
}

/**
 * StudentNutritionAdherence (Smart): Manages diet adherence and macros.
 * fully local-first offline-ready. Granular item tracking and dynamic sychronous progress.
 */
export function StudentNutritionAdherence({ userId }: StudentNutritionAdherenceProps) {
    const queryClient = useQueryClient()
    const todayQueryKey = QUERY_KEYS.diets.today(userId)

    const { data: diet, isLoading } = useStudentDailyDiet(userId)

    const mealMutation = useOptimisticMutation({
        actionName: 'toggle-meal-group',
        queryKey: todayQueryKey,
        entity: ENTITIES.MEAL,
        onMutate: (variables: any) => {
            queryClient.setQueryData(todayQueryKey, (old: any) => {
                if (!old || !old.meals) return old
                return {
                    ...old,
                    meals: old.meals.map((m: any) => {
                        if (m.id === variables.mealId) {
                            const newStatus = !variables.currentStatus
                            return {
                                ...m,
                                is_checked: newStatus,
                                meal_items: (m.meal_items || []).map((i: any) => ({ ...i, is_checked: newStatus }))
                            }
                        }
                        return m
                    })
                }
            })
        }
    })

    const itemMutation = useOptimisticMutation({
        actionName: 'toggle-meal-item',
        queryKey: todayQueryKey,
        entity: ENTITIES.MEAL_ITEM,
        onMutate: (variables: any) => {
            queryClient.setQueryData(todayQueryKey, (old: any) => {
                if (!old || !old.meals) return old
                return {
                    ...old,
                    meals: old.meals.map((m: any) => {
                        const items = m.meal_items || []
                        const hasItem = items.some((i: any) => i.id === variables.itemId)
                        if (hasItem) {
                            const newItems = items.map((i: any) => {
                                if (i.id === variables.itemId) {
                                    return { ...i, is_checked: !variables.currentStatus }
                                }
                                return i
                            })
                            const allChecked = newItems.every((i: any) => i.is_checked)
                            return {
                                ...m,
                                is_checked: allChecked,
                                meal_items: newItems
                            }
                        }
                        return m
                    })
                }
            })
        }
    })

    const stats = useMemo(() => {
        if (!diet || !diet.meals) return null

        const allItems = diet.meals.flatMap((m: any) => m.meal_items || [])
        const totalItems = allItems.length
        const completedItems = allItems.filter((i: any) => i.is_checked).length

        // Macros calculation
        const totals = diet.meals.reduce((acc: any, meal: any) => {
            const items = meal.meal_items || []
            return {
                p: acc.p + items.reduce((s: any, i: any) => s + (i.is_substituted ? (i.substituted_protein || 0) : (i.protein || 0)), 0),
                c: acc.c + items.reduce((s: any, i: any) => s + (i.is_substituted ? (i.substituted_carbs || 0) : (i.carbs || 0)), 0),
                g: acc.g + items.reduce((s: any, i: any) => s + (i.is_substituted ? (i.substituted_fat || 0) : (i.fat || 0)), 0),
                f: acc.f + items.reduce((s: any, i: any) => s + (i.is_substituted ? (i.substituted_fiber || 0) : (i.fiber || 0)), 0),
            }
        }, { p: 0, c: 0, g: 0, f: 0 })

        const calories = (totals.p * 4) + (totals.c * 4) + (totals.g * 9)

        return {
            totalItems: totalItems, // Dynamic progress per item
            completedItems: completedItems,
            percentage: totalItems > 0 ? (completedItems / totalItems) * 100 : 0,
            macros: {
                calories,
                protein: totals.p,
                carbs: totals.c,
                fat: totals.g,
                fiber: totals.f
            }
        }
    }, [diet])

    if (isLoading) return <RegistrySection title="DIETA DE HOJE" subtitle="Acompanhamento nutricional e macros." icon={Utensils}><Box /></RegistrySection>

    if (!diet || !stats) {
        return (
            <RegistrySection title="DIETA DE HOJE" subtitle="Acompanhamento nutricional e macros." icon={Utensils}>
                <DietAdherenceCard
                    completedItems={0}
                    totalItems={0}
                    percentage={0}
                    macros={{ calories: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 }}
                    meals={[]}
                    status="empty"
                />
            </RegistrySection>
        )
    }

    return (
        <RegistrySection
            title="DIETA DE HOJE"
            subtitle="Acompanhamento nutricional e macros."
            icon={Utensils}
        >
            <DietAdherenceCard
                completedItems={stats.completedItems}
                totalItems={stats.totalItems}
                percentage={stats.percentage}
                macros={stats.macros}
                meals={diet.meals}
                onToggleMeal={(mealId, currentStatus) => mealMutation.mutate({ mealId, currentStatus })}
                onToggleItem={(itemId, currentStatus) => itemMutation.mutate({ itemId, currentStatus })}
                status="active"
            />
        </RegistrySection>
    )
}

'use client'

import React, { useState, useActionState } from 'react'
import { useFormStatus } from 'react-dom'
import { submitOnboarding } from '@/actions/onboarding-actions'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Grid } from '@/components/store/base/grid'
import { Input } from '@/components/store/base/input'
import { FormSelect } from '@/components/store/base/form-select'
import { FormCheckbox } from '@/components/store/base/form-checkbox'
import { Textarea } from '@/components/store/base/textarea'
import { Button } from '@/components/store/base/button'
import { Box } from '@/components/store/base/box'
import { Icon } from '@/components/store/base/icon'
import { 
    Activity, 
    Target, 
    ShieldCheck, 
    Ruler, 
    Weight, 
    Code, 
    Zap, 
    Calendar,
    ChevronRight,
    ChevronLeft,
    Loader2
} from 'lucide-react'
import { DomainStepCard } from '../intermediary/domain-step-card'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { RegistryProvider } from './registry-context'

const initialState = {
    message: '',
    errors: {} as Record<string, string[]>
}

/**
 * StudentOnboardingForm: Orchestrates the multi-step form composition.
 * - Encapsulates all inputs, selects, and checkboxes for the onboarding flow.
 * - Handles the internal validation structure and grouping.
 * - Responsibility: Onboarding domain logic and form flow.
 */
export function StudentOnboardingForm({ defaultTrainerCode = '' }: { defaultTrainerCode?: string }) {
    const [state, formAction] = useActionState(submitOnboarding, initialState)
    const [step, setStep] = useState(1)
    
    // Step 1 States
    const [height, setHeight] = useState('')
    const [startingWeight, setStartingWeight] = useState('')
    const [estimatedBf, setEstimatedBf] = useState('')
    const [displayBirthDate, setDisplayBirthDate] = useState('')
    const [birthDate, setBirthDate] = useState('')

    // Step 2 States
    const [activityLevel, setActivityLevel] = useState('moderate')
    const [goal, setGoal] = useState('')

    // Step 3 States
    const [steroidUse, setSteroidUse] = useState(false)
    const [observations, setObservations] = useState('')
    const [imageAuth, setImageAuth] = useState('false')
    const [trainerCode, setTrainerCode] = useState(defaultTrainerCode)

    // Handle Date conversion from DD/MM/YYYY to YYYY-MM-DD
    const handleBirthDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value
        setDisplayBirthDate(value)

        // The date mask returns DD/MM/YYYY. If it has 10 characters:
        if (value.length === 10) {
            const parts = value.split('/')
            if (parts.length === 3) {
                const day = parts[0]
                const month = parts[1]
                const year = parts[2]
                setBirthDate(`${year}-${month}-${day}`)
            }
        } else {
            setBirthDate('')
        }
    }

    const nextStep = () => setStep((s) => Math.min(s + 1, 3))
    const prevStep = () => setStep((s) => Math.max(s - 1, 1))

    // Validations to disable buttons
    const isStep1Valid = height && startingWeight && birthDate
    const isStep2Valid = goal && goal.trim().length >= 3

    // Inner loading submit button
    function SubmitButton() {
        const { pending } = useFormStatus()
        return (
            <Button
                type="submit"
                variant="primary"
                size="lg"
                flex1
                disabled={pending}
            >
                <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    {pending ? (
                        <>
                            <Icon icon={Loader2} animate="spin" size="sm" color={STORE_TOKENS.COLORS.BLACK} />
                            <Font variant="sub-tiny" weight="black" uppercase tracking="widest">Finalizando...</Font>
                        </>
                    ) : (
                        <>
                            <Font variant="sub-tiny" weight="black" uppercase tracking="widest">Finalizar Cadastro</Font>
                            <Icon icon={ShieldCheck} size="sm" color={STORE_TOKENS.COLORS.BLACK} />
                        </>
                    )}
                </Stack>
            </Button>
        );
    }

    return (
        <RegistryProvider defaultColor="orange">
            <form
                action={formAction}
                noValidate
                {...{
                    className: "w-full",
                }}>
                {/* Hidden inputs to guarantee they are always submitted */}
                <Box as="input" type="hidden" name="height" value={height} />
                <Box as="input" type="hidden" name="startingWeight" value={startingWeight} />
                <Box as="input" type="hidden" name="estimatedBf" value={estimatedBf} />
                <Box as="input" type="hidden" name="birthDate" value={birthDate} />
                <Box as="input" type="hidden" name="goal" value={goal} />
                <Box as="input" type="hidden" name="activityLevel" value={activityLevel} />
                <Box as="input" type="hidden" name="imageAuth" value={imageAuth} />
                <Box as="input" type="hidden" name="trainerCode" value={trainerCode} />
                <Box as="input" type="hidden" name="observations" value={observations} />
                {steroidUse && <Box as="input" type="hidden" name="steroidUse" value="on" />}

                <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                    {/* Error Messages */}
                    {state?.message && (
                        <Box 
                            padding={STORE_TOKENS.PADDING.CONTAINER} 
                            rounded={STORE_TOKENS.RADIUS.SYSTEM} 
                            bg={STORE_TOKENS.COLORS.ERROR}
                            bgOpacity={STORE_TOKENS.OPACITY.SUBTLE}
                            border
                            borderColor={STORE_TOKENS.COLORS.ERROR}
                            borderOpacity={STORE_TOKENS.OPACITY.MEDIUM}
                            textAlign="center"
                        >
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Font
                                    variant="sub-tiny"
                                    weight="black"
                                    uppercase
                                    tracking="widest"
                                    {...{
                                        color: "error",
                                    }}>{state.message}</Font>
                                {state.errors && Object.keys(state.errors).length > 0 && (
                                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        {Object.entries(state.errors).map(([field, msgs]) => (
                                            <Font
                                                key={field}
                                                variant="sub-tiny"
                                                {...{
                                                    color: "error",
                                                }}>
                                                <Font
                                                    variant="sub-tiny"
                                                    weight="bold"
                                                    {...{
                                                        color: "error",
                                                    }}>{field}:</Font> {msgs?.join(', ')}
                                            </Font>
                                        ))}
                                    </Stack>
                                )}
                            </Stack>
                        </Box>
                    )}

                    {/* STEP 1: Biometrics */}
                    {step === 1 && (
                        <DomainStepCard 
                            index={1}
                            title="Biometria de Elite" 
                            description="Dados corporais fundamentais para o cálculo de protocolos."
                            icon={Activity}
                            accentColor="orange"
                        >
                            <Grid cols={{ base: 1, md: 2 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <Input 
                                    id="height"
                                    label="Altura (cm)" 
                                    placeholder="Ex: 175" 
                                    type="number"
                                    value={height}
                                    onChange={(e) => setHeight(e.target.value)}
                                    icon={<Ruler size={16} />}
                                />
                                <Input 
                                    id="startingWeight"
                                    label="Peso Atual (kg)" 
                                    placeholder="Ex: 80.5" 
                                    type="number"
                                    step="0.1"
                                    value={startingWeight}
                                    onChange={(e) => setStartingWeight(e.target.value)}
                                    icon={<Weight size={16} />}
                                />
                                <Input 
                                    id="estimatedBf"
                                    label="Gordura Estimada (%)" 
                                    placeholder="Opcional" 
                                    type="number"
                                    step="0.1"
                                    value={estimatedBf}
                                    onChange={(e) => setEstimatedBf(e.target.value)}
                                    icon={<Zap size={16} />}
                                />
                                <Input 
                                    id="displayBirthDate"
                                    label="Data de Nascimento" 
                                    placeholder="DD/MM/AAAA" 
                                    mask="date"
                                    value={displayBirthDate}
                                    onChange={handleBirthDateChange}
                                    icon={<Calendar size={16} />}
                                />
                            </Grid>
                        </DomainStepCard>
                    )}

                    {/* STEP 2: Lifestyle & Goal */}
                    {step === 2 && (
                        <DomainStepCard 
                            index={2}
                            title="Perfil Metabólico" 
                            description="Seu ritmo atual e onde você quer chegar."
                            icon={Target}
                            accentColor="orange"
                        >
                            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <FormSelect 
                                    label="Nível de Atividade"
                                    placeholder="Selecione seu ritmo..."
                                    value={activityLevel}
                                    onChange={setActivityLevel}
                                    options={[
                                        { value: 'sedentary', label: 'Sedentário', description: 'Pouco ou nenhum exercício' },
                                        { value: 'light', label: 'Leve', description: '1-3 dias por semana' },
                                        { value: 'moderate', label: 'Moderado', description: '3-5 dias por semana' },
                                        { value: 'active', label: 'Ativo', description: '6-7 dias por semana' },
                                        { value: 'athlete', label: 'Elite', description: 'Atleta Profissional' },
                                    ]}
                                />
                                <Input 
                                    id="goal"
                                    label="Objetivo Principal" 
                                    placeholder="Ex: Hipertrofia Máxima, Definição..." 
                                    value={goal}
                                    onChange={(e) => setGoal(e.target.value)}
                                    icon={<Target size={16} />}
                                />
                            </Stack>
                        </DomainStepCard>
                    )}

                    {/* STEP 3: Governança & Vínculo */}
                    {step === 3 && (
                        <DomainStepCard 
                            index={3}
                            title="Governança & Vínculo" 
                            description="Dados de segurança e conexão com seu treinador."
                            icon={ShieldCheck}
                            accentColor="orange"
                        >
                            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                                <Textarea 
                                    id="observations"
                                    label="Observações Médicas / Lesões"
                                    placeholder="Ex: Dores no joelho, cirurgias, limitações..."
                                    rows={4}
                                    value={observations}
                                    onChange={(e) => setObservations(e.target.value)}
                                />

                                <FormCheckbox 
                                    name="steroidUse"
                                    label="FAÇO USO DE RECURSOS ERGOGÊNICOS" 
                                    description="Informação confidencial para ajuste fino de volume e intensidade pelo seu treinador."
                                    color={STORE_TOKENS.COLORS.BRAND}
                                    checked={steroidUse}
                                    onChange={setSteroidUse}
                                />

                                <Input 
                                    id="trainerCode"
                                    label="Código do Personal" 
                                    placeholder="Ex: TREINADOR123" 
                                    value={trainerCode}
                                    onChange={(e) => setTrainerCode(e.target.value)}
                                    icon={<Code size={16} />}
                                />
                            </Stack>
                        </DomainStepCard>
                    )}

                    {/* Actions Navigation Bar */}
                    <Stack direction={{ base: 'col', md: 'row' }} gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth>
                        {step > 1 && (
                            <Button 
                                type="button" 
                                variant="outline-primary" 
                                size="lg" 
                                onClick={prevStep}
                            >
                                <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                    <Icon icon={ChevronLeft} size="sm" />
                                    <Font variant="sub-tiny" weight="black" uppercase tracking="widest">Voltar</Font>
                                </Stack>
                            </Button>
                        )}
                        
                        {step < 3 ? (
                            <Button 
                                type="button" 
                                variant="primary" 
                                size="lg" 
                                flex1
                                disabled={step === 1 ? !isStep1Valid : !isStep2Valid}
                                onClick={nextStep}
                            >
                                <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                    <Font variant="sub-tiny" weight="black" uppercase tracking="widest">Próximo</Font>
                                    <Icon icon={ChevronRight} size="sm" />
                                </Stack>
                            </Button>
                        ) : (
                            <SubmitButton />
                        )}
                    </Stack>
                </Stack>
            </form>
        </RegistryProvider>
    );
}

'use client';
import { STORE_TOKENS } from '@/components/store/constants/tokens';

import { Button } from '@/components/store/base/button'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { CreditCard } from 'lucide-react'
import { useToast } from "@/hooks/use-toast"
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { ENTITIES } from '@/lib/outbox-db'
import { QUERY_KEYS } from '@/lib/query-keys'

export function StudentPaymentButtons() {
    const { toast } = useToast()

    const { mutate, isPending } = useOptimisticMutation({
        actionName: 'create-asaas-subscription',
        entity: ENTITIES.SUBSCRIPTION,
        entityId: 'new',
        queryKey: QUERY_KEYS.student.all('me'),
        mutationFn: async (variables: { tier: string, type: string }) => {
            const { createAsaasSubscription } = await import('@/actions/asaas-actions')
            return await createAsaasSubscription(variables.tier as any, variables.type as any)
        },
        onMutate: () => {
            toast({
                title: "Gerando pagamento...",
                description: `Aguarde um instante enquanto preparamos seu checkout...`
            })
        },
        onSuccess: (res) => {
            if (res.success && res.invoiceUrl) {
                window.location.href = res.invoiceUrl
            } else if (res.error) {
                toast({ variant: 'destructive', title: 'Erro no Asaas', description: res.error })
            }
        }
    })

    const handleAsaas = (type: 'PIX' | 'BOLETO' | 'CREDIT_CARD') => {
        mutate({ tier: 'auto_training', type })
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
            <Button
                onClick={() => handleAsaas('CREDIT_CARD')}
                disabled={isPending}
                loading={isPending}
                variant="emerald"
                fullWidth
                paddingY={STORE_TOKENS.PADDING.CONTAINER}
