interface StudentProfileSummaryProps {
    name: string
    email: string
    avatarUrl?: string | null
    userId?: string
}

/**
 * StudentProfileSummary: Advanced component for the main profile identification card.
 * Extracted from StudentProfileSectionContent.
 * Preserves exact alignment, padding, and token usage.
 */
export function StudentProfileSummary({ name, email, avatarUrl, userId }: StudentProfileSummaryProps) {
    const { toast } = useToast()
    const router = useRouter()
    const [isUploading, setIsUploading] = useState(false)

    const handleFileSelect = async (file: File) => {
        setIsUploading(true)
        toast({
            title: "Salvando foto...",
            description: "Aguarde enquanto sua imagem de perfil está sendo processada."
        })

        try {
            const formData = new FormData()
            formData.append('file', file)

            const res = await uploadAvatar(formData)
            if (res.success) {
                toast({
                    title: "Foto atualizada!",
                    description: "Sua foto de perfil foi salva com sucesso."
                })
                router.refresh()
            } else {
                toast({
                    variant: "destructive",
                    title: "Erro ao salvar foto",
                    description: res.error || "Tente novamente mais tarde."
                })
            }
        } catch (error: any) {
            toast({
                variant: "destructive",
                title: "Erro inesperado",
                description: error.message || "Ocorreu um erro no upload."
            })
        } finally {
            setIsUploading(false)
        }
    }

    return (
        <Surface variant="glass" padding={STORE_TOKENS.PADDING.CONTAINER} rounded={STORE_TOKENS.RADIUS.SYSTEM} border="none">
            <Stack align="center" gap={STORE_TOKENS.SPACING.CONTAINER}>
                <FileUpload 
                    label="FOTO DE PERFIL" 
                    variant="profile" 
                    currentImageUrl={avatarUrl ?? undefined}
                    onFileSelect={handleFileSelect} 
                    isUploading={isUploading}
                />

                <Stack align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="h3"
                        align="center"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                        }}>
                        {name}
                    </Font>
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        tracking="widest"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.MUTED,
                        }}>
                        {email}
                    </Font>
                </Stack>

                {userId ? (
                    <Link
                        href={`/aluno/${userId}`}
                        target="_blank"
                        {...{
                            className: "w-full",
                        }}>
                        <Button variant="outline-orange" fullWidth size="lg">
                            <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Icon icon={ShieldCheck} size="xs" />
                                <Font variant="body-sm" weight="black" uppercase italic>VER PERFIL PÚBLICO</Font>
                            </Stack>
                        </Button>
                    </Link>
                ) : (
                    <Button variant="outline-orange" fullWidth size="lg" disabled>
                        <Stack direction="row" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                            <Icon icon={ShieldCheck} size="xs" />
                            <Font variant="body-sm" weight="black" uppercase italic>VER PERFIL PÚBLICO</Font>
                        </Stack>
                    </Button>
                )}
            </Stack>
        </Surface>
    );
}

import { createClient } from '@/lib/supabase/server'
import { getStudentFullMetrics } from '@/actions/metrics-actions'
import { getAdherenceHistory } from '@/actions/tracking-actions'
import { StudentPublicProfileMain } from '@/components/store/advanced/student-public-profile-main'
import { StudentPublicPhotos } from '@/components/store/advanced/student-public-photos'
import { StudentPublicMetrics } from '@/components/store/advanced/student-public-metrics'

export async function StudentProgressPageContent({ userId }: { userId: string }) {
    const supabase = await createClient()

    // Fetch real data
    const fullMetrics = await getStudentFullMetrics(userId)
    const adherenceHistory = await getAdherenceHistory(30)

    const [profileResult, trainerLinkResult, progressPhotosResult] = await Promise.all([
        supabase
            .from('profiles')
            .select('id, full_name, avatar_url, created_at')
            .eq('id', userId)
            .single(),
        supabase
            .from('trainer_students')
            .select(`
                active,
                trainer:profiles!trainer_id(
                    id, full_name, avatar_url, trainer_code
                )
            `)
            .eq('student_id', userId)
            .eq('active', true)
            .maybeSingle(),
        supabase
            .from('progress_photos')
            .select('id, front_url, back_url, side_right_url, side_left_url, created_at')
            .eq('student_id', userId)
            .order('created_at', { ascending: false })
    ])

    const profile = profileResult.data
    const trainerLink = trainerLinkResult.data
    const progressPhotos = progressPhotosResult.data || []

    const trainerData = trainerLink?.trainer as any

    if (!profile) return null

    // ── Compose evolution tab content ──────────────────────────────────────────
    const evolutionContent = (
        <StudentPublicMetrics
            fullMetrics={fullMetrics}
            adherenceHistory={adherenceHistory || []}
            steroidUse={!!fullMetrics.details?.steroid_use}
        />
    )

    const photosContent = (
        <StudentPublicPhotos
            studentId={userId}
            isOwner={true}
            studentName={profile.full_name}
            photos={progressPhotos}
            isStudentView={true}
        />
    )

    return (
        <StudentPublicProfileMain
            profile={profile}
            trainerData={trainerData}
            evolutionContent={evolutionContent}
            historyContent={null}
            photosContent={photosContent}
        />
    )
}

'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { getStudentTrainer } from '@/actions/student-actions'
