    const { toast } = useToast()
    const router = useRouter()

    const { data: termsStatus, isLoading: loadingTerms } = useQuery({
        queryKey: ['terms-status'],
        queryFn: async () => getTermsStatus(),
        staleTime: 1000 * 60 * 5
    })

    const { data: trialData, isLoading: loadingTrial } = useQuery({
        queryKey: ['auto-training-trial'],
        queryFn: async () => getAutoTrainingTrialInfoForCurrentUser(),
        enabled: isOpen && !hasTrainer,
        staleTime: 1000 * 60 * 5
    })

    const { mutate: startTrial } = useOptimisticMutation({
        actionName: 'enable-auto-training-trial',
        entity: ENTITIES.SETTINGS,
        queryKey: ['auto-training-trial'],
        mutationFn: async () => enableAutoTrainingTrialForCurrentUser(),
        onMutate: () => {
            const previous = queryClient.getQueryData(['auto-training-trial'])
            queryClient.setQueryData(['auto-training-trial'], (old: any) => ({
                ...old,
                auto_training_status: 'trial',
                auto_training_trial_used: true,
                auto_training_trial_end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()
            }))
            return { previous }
        },
        onSuccess: () => {
            toast({ title: "Trial Ativado!", description: "Aproveite seus 7 dias de Auto-Training." })
            setIsOpen(false)
            router.refresh()
            setTimeout(() => {
                window.dispatchEvent(new CustomEvent('open-auto-training-onboarding'))
            }, 100)
        },
        onError: (err, variables, ctx) => {
            queryClient.setQueryData(['auto-training-trial'], ctx?.previous)
            toast({ variant: "destructive", title: "Erro ao ativar trial", description: "Tente novamente em alguns instantes." })
        }
    })

    useEffect(() => {
        const handleOpen = () => {
            setIsOpen(true)
            // Re-check standalone mode when modal opens
            const isStandalone = window.matchMedia('(display-mode: standalone)').matches ||
                (window.navigator as any).standalone === true ||
                document.referrer.includes('android-app://')

            if (isStandalone) {
                setPwaInstalled(true)
            }
        }
        window.addEventListener('open-settings', handleOpen)

        // Initial check
        if (typeof window !== 'undefined') {
            const isStandalone = window.matchMedia('(display-mode: standalone)').matches ||
                (window.navigator as any).standalone === true
            if (isStandalone) setPwaInstalled(true)

            if ('Notification' in window && Notification.permission === 'granted') {
                setNotifications('on')
            }
        }

        return () => window.removeEventListener('open-settings', handleOpen)
    }, [])

    const enableAutoTrainingTrial = () => {
        if (isTrialActive) return
        startTrial({})
    }

    const now = Date.now()
    const trialInfo = trialData
    const trialEndMs = trialInfo?.auto_training_trial_end ? new Date(trialInfo.auto_training_trial_end).getTime() : null
    const isTrialActive = trialInfo?.auto_training_status === 'trial' && !!trialEndMs && now <= trialEndMs
    const daysRemaining = isTrialActive && trialEndMs ? Math.max(0, Math.ceil((trialEndMs - now) / (1000 * 60 * 60 * 24))) : 0
    const hasUsedTrial = !!trialInfo?.auto_training_trial_used

    let autoTreinoStatus: 'available' | 'trial_active' | 'subscription_active' | 'used' = 'available'
    if (trialInfo?.auto_training_status === 'active') autoTreinoStatus = 'subscription_active'
    else if (isTrialActive) autoTreinoStatus = 'trial_active'
    else if (hasUsedTrial) autoTreinoStatus = 'used'

    return (
        <>
            <Modal
                isOpen={isOpen}
                onClose={() => setIsOpen(false)}
                title="CONFIGURAÇÕES DO SISTEMA"
                subtitle="Gerencie suas preferências e recursos premium."
                icon={Settings2}
                variant="primary"
                confirmLabel="SALVAR PREFERÊNCIAS"
                onConfirm={() => setIsOpen(false)}
            >
                <Box position="relative">
                    {(loadingTerms || loadingTrial) && (
                        <Box
                            position="absolute"
                            pin="inset"
                            zIndex={STORE_TOKENS.Z_INDEX.OVERLAY}
                            display="flex"
                            align="center"
                            justify="center"
                            rounded={STORE_TOKENS.RADIUS.SYSTEM}
                            bg={STORE_TOKENS.COLORS.BLACK}
                            bgOpacity={STORE_TOKENS.OPACITY.MEDIUM}
                        >
                            <Icon icon={Loader2} color={STORE_TOKENS.COLORS.SUCCESS} size="md" animate="spin" />
                        </Box>
                    )}

                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>

                        {!pwaInstalled && (
                            <SettingsActionCard
                                icon={Smartphone}
                                title="APP REPTRAIL"
                                subtitle="INSTALE PARA ACESSO RÁPIDO"
                                actionLabel="INSTALAR"
                                buttonVariant="outline-blue"
                                actionIcon={Download}
                                onAction={() => {
                                    setIsPwaModalOpen(true)
                                }}
                                {...{
                                    color: "blue",
                                }} />
                        )}

                        <SettingsActionCard
                            icon={Bell}
                            title="NOTIFICAÇÕES PUSH"
                            subtitle="RECEBA ALERTAS DE TREINOS E DIETAS"
                            actionLabel={notifications === 'on' ? 'CONFIGURAR' : 'ATIVAR'}
                            buttonVariant="outline-orange"
                            actionIcon={Bell}
                            onAction={() => {
                                setIsOpen(false)
                                setIsNotificationModalOpen(true)
                            }}
                            {...{
                                color: "orange",
                            }} />

                        {!isTrainer && !hasTrainer && (
                            <>
                                {autoTreinoStatus === 'available' && (
                                    <SettingsActionCard
                                        icon={Zap}
                                        surfaceVariant="glass"
                                        title="TESTE GRÁTIS DISPONÍVEL"
                                        subtitle="EXPERIMENTE POR 7 DIAS SEM CUSTOS"
                                        actionLabel="HABILITAR"
                                        buttonVariant="outline-emerald"
                                        actionIcon={Zap}
                                        onAction={enableAutoTrainingTrial}
                                        {...{
                                            color: "emerald",
                                        }} />
                                )}

                                {autoTreinoStatus === 'subscription_active' && (
                                    <SettingsActionCard
                                        icon={Crown}
                                        title="AUTO-TREINO ATIVO"
                                        subtitle="VOCÊ POSSUI ACESSO TOTAL ÀS FUNCIONALIDADES"
                                        actionLabel="GERENCIAR"
                                        actionIcon={CheckCircle2}
                                        buttonVariant="outline-emerald"
                                        onAction={() => {
                                            setIsOpen(false)
                                            router.push('/dashboard/student/profile')
                                        }}
                                        {...{
                                            color: "emerald",
                                        }} />
                                )}

                                {autoTreinoStatus === 'trial_active' && (
                                    <SettingsActionCard
                                        icon={Clock}
                                        title="TESTE EM ANDAMENTO"
                                        subtitle={`VOCÊ TEM ${daysRemaining} DIAS RESTANTES`}
                                        actionLabel="ATIVO"
                                        actionIcon={CheckCircle2}
                                        buttonVariant="outline-emerald"
                                        onAction={() => { }}
                                        disabled
                                        {...{
                                            color: "emerald",
                                        }} />
                                )}

                                {autoTreinoStatus === 'used' && (
                                    <SettingsActionCard
                                        icon={Zap}
                                        surfaceVariant="glass"
                                        title="TESTE INDISPONÍVEL"
                                        subtitle="VOCÊ JÁ UTILIZOU SEU PERÍODO DE TESTE"
                                        actionLabel="ASSINAR"
                                        buttonVariant="outline-zinc"
                                        actionIcon={CreditCard}
                                        onAction={() => {
                                            setIsOpen(false)
                                            window.dispatchEvent(new CustomEvent('open-asaas', { detail: { tier: 'auto_training' } }))
                                        }}
                                        {...{
                                            color: "zinc",
                                        }} />
                                )}
                            </>
                        )}

                        <SettingsActionCard
                            icon={Trash2}
                            title="ZONA CRÍTICA"
                            subtitle="AÇÃO IRREVERSÍVEL E PERMANENTE"
                            actionLabel="DELETAR"
                            buttonVariant="outline-red"
                            actionIcon={Trash2}
                            onAction={() => {
                                setIsOpen(false)
                                setIsDeleteModalOpen(true)
                            }}
                            {...{
                                color: "red",
                            }} />

                    </Stack>
                </Box>
            </Modal>
            {/* Confirmation Modals */}
            <Modal
                isOpen={isPwaModalOpen}
                onClose={() => setIsPwaModalOpen(false)}
                title="INSTALAR APLICATIVO"
                subtitle="Tenha o RepTrail sempre com você."
                icon={Download}
                variant="emerald"
                confirmLabel="INSTALAR AGORA"
                onConfirm={() => {
                    toast({ title: "Instalando...", description: "O aplicativo está sendo instalado no seu dispositivo." })
                    setPwaInstalled(true)
                    setIsPwaModalOpen(false)
                }}
            >
                <Font
                    variant="body-sm"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                    }}>
                    Ao instalar o PWA, você terá acesso rápido ao RepTrail direto da tela inicial do seu celular, com carregamento mais rápido e experiência de aplicativo nativo.
                </Font>
            </Modal>
            <Modal
                isOpen={isNotificationModalOpen}
                onClose={() => {
                    setNotifications('off')
                    setIsNotificationModalOpen(false)
                }}
                title="ATIVAR NOTIFICAÇÕES"
                subtitle="Fique por dentro das novidades."
                icon={Bell}
                variant="blue"
                confirmLabel="PERMITIR"
                onConfirm={async () => {
                    if (!('Notification' in window)) {
                        toast({ variant: 'destructive', title: "Não suportado", description: "Seu navegador não suporta notificações push." })
                        setIsNotificationModalOpen(false)
                        return
                    }

                    const permission = await Notification.requestPermission()

                    if (permission === 'granted') {
                        toast({ title: "Notificações ativadas", description: "Você receberá alertas importantes do seu treinador." })
                        setNotifications('on')
                    } else {
                        toast({ variant: 'destructive', title: "Permissão negada", description: "Você não receberá notificações até permitir nas configurações do navegador." })
                        setNotifications('off')
                    }
                    setIsNotificationModalOpen(false)
                }}
            >
                <Font
                    variant="body-sm"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                    }}>
                    Permita que o RepTrail envie notificações push para avisar sobre novos treinos, feedbacks de dieta e mensagens importantes do seu personal.
                </Font>
            </Modal>
            <Modal
                isOpen={isDeleteModalOpen}
                onClose={() => {
                    setIsDeleteModalOpen(false)
                    setDeletePassword('')
                }}
                title="EXCLUIR CONTA"
                subtitle="Ação irreversível."
                icon={Trash2}
                variant="red"
                confirmLabel="Excluir"
                isLoading={isDeleting}
                onConfirm={() => {
                    if (!deletePassword) {
                        toast({ variant: 'destructive', title: "Senha obrigatória", description: "Digite sua senha para confirmar a exclusão." })
                        return
                    }
                    setIsDeleting(true)
                    setTimeout(() => {
                        toast({ title: "Conta excluída", description: "Sua conta e todos os dados foram removidos com sucesso." })
                        setIsDeleting(false)
                        setIsDeleteModalOpen(false)
                        router.push('/login')
                    }, 1500)
                }}
            >
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Box
                        padding={STORE_TOKENS.PADDING.ELEMENT}
                        rounded={STORE_TOKENS.RADIUS.SYSTEM}
                        border
                        borderColor={STORE_TOKENS.COLORS.ERROR}
                        borderOpacity={STORE_TOKENS.OPACITY.MEDIUM}
                        bg={STORE_TOKENS.COLORS.ERROR}
                        bgOpacity={STORE_TOKENS.OPACITY.SUBTLE}
                    >
                        <Font
                            variant="body-sm"
                            {...{
                                color: "red",
                            }}>
                            Atenção: Ao excluir sua conta, todos os seus protocolos, histórico de treinos e métricas serão apagados <Font weight='bold'>para sempre</Font>. Esta ação não pode ser desfeita.
                        </Font>
                    </Box>
                    <Input
                        type="password"
                        label="SENHA DE CONFIRMAÇÃO"
                        placeholder="Digite sua senha"
                        value={deletePassword}
                        onChange={(e) => setDeletePassword(e.target.value)}
                    />
                </Stack>
            </Modal>
        </>
    );
}

'use client'

import React, { useState } from 'react'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Stack } from '@/components/store/base/stack'
import { ProtocolCard } from '@/components/store/intermediary/protocol-card'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Dumbbell, ChevronLeft, ChevronRight } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTodayWorkout } from '@/actions/workout-actions'
import { useRealtimeSync } from '@/hooks/use-realtime-sync'
import { Button } from '@/components/store/base/button'
import { Icon } from '@/components/store/base/icon'
import { Box } from '@/components/store/base/box'
import { useRouter } from 'next/navigation'

interface StudentTrainingProtocolsProps {
    userId: string
}

/**
 * StudentTrainingProtocols (Smart): Manages training protocol data and carousel logic.
 * Preserves the exact query and realtime behavior of the legacy WorkoutCard.
 */
export function StudentTrainingProtocols({ userId }: StudentTrainingProtocolsProps) {
    const router = useRouter()
    const [currentIndex, setCurrentIndex] = useState(0)

    // Preserve Realtime Sync
    useRealtimeSync({
        table: 'assigned_workouts',
        queryKey: QUERY_KEYS.workouts.today(userId),
        filter: `student_id=eq.${userId}`
    })

    const { data: workouts, isLoading } = useQuery<any[]>({
        queryKey: QUERY_KEYS.workouts.today(userId),
        queryFn: () => getTodayWorkout(userId),
        staleTime: 1000 * 60 * 5,
        refetchOnMount: false,
    })

    if (isLoading) return <RegistrySection title="TREINO DE HOJE" subtitle="Protocolos de musculação e treinamento de força." icon={Dumbbell}><Box /></RegistrySection>

    if (!workouts || workouts.length === 0) {
        return (
            <RegistrySection title="TREINO DE HOJE" subtitle="Protocolos de musculação e treinamento de força." icon={Dumbbell}>
                <ProtocolCard
                    title="DIA DE DESCANSO"
                    subtitle="Nenhum protocolo de treino para hoje."
                    icon={Dumbbell}
                    status="empty"
                />
            </RegistrySection>
        )
    }

    const currentWorkout = (workouts && workouts.length > 0) ? (workouts[currentIndex] || workouts[0]) : null

    if (!currentWorkout || !currentWorkout.id || !currentWorkout.name) {
        return (
            <RegistrySection title="TREINO DE HOJE" subtitle="Protocolos de musculação e treinamento de força." icon={Dumbbell}>
                <ProtocolCard
                    title="DIA DE DESCANSO"
                    subtitle="Nenhum protocolo de treino para hoje."
                    icon={Dumbbell}
                    status="empty"
                />
            </RegistrySection>
        )
    }

    const status = currentWorkout.status || 'not_started'
    const logId = currentWorkout.logId || null

    const next = () => setCurrentIndex(prev => (prev + 1) % workouts.length)
    const prev = () => setCurrentIndex(prev => (prev - 1 + workouts.length) % workouts.length)

    const handleAction = () => {
        const href = (status === 'completed' && logId)
            ? `/dashboard/student/workout-log/${logId}/review`
            : `/dashboard/student/workout/${currentWorkout?.id || 'new'}`
        router.push(href)
    }

    return (
        <RegistrySection
            title="TREINO DE HOJE"
            subtitle="Protocolos de musculação e treinamento de força."
            icon={Dumbbell}
            rightElement={workouts.length > 1 ? (
                <Stack direction="row" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Button variant="outline-zinc" isIconOnly size="sm" onClick={prev}>
                        <Icon icon={ChevronLeft} size="xs" />
                    </Button>
                    <Button variant="outline-zinc" isIconOnly size="sm" onClick={next}>
                        <Icon icon={ChevronRight} size="xs" />
                    </Button>
                </Stack>
            ) : undefined}
        >
            <ProtocolCard
                title={currentWorkout.name.toUpperCase()}
                subtitle={`${currentWorkout.workout_exercises?.length || 0} EXERCÍCIOS • ${status === 'completed' ? 'CONCLUÍDO' : 'FOCO DO DIA'}`}
                icon={Dumbbell}
                status={status as any}
                logId={logId}
                userId={userId}
                workoutId={currentWorkout.id}
                onAction={handleAction}
                statusLabel={workouts.length > 1 ? `TREINO ${currentIndex + 1}/${workouts.length}` : undefined}
            />
        </RegistrySection>
    )
}

'use client'

import { useState } from 'react'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'
import { Button } from '@/components/store/base/button'
import { Input } from '@/components/store/base/input'
import { Box, BoxColor } from '@/components/store/base/box'
import { Stack } from '@/components/store/base/stack'
import { Font, FontColor } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Separator } from '@/components/store/base/separator'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { ChevronLeft, CheckCircle, Save, Dumbbell } from 'lucide-react'
import Link from 'next/link'
import { useToast } from '@/hooks/use-toast'
import { useRouter } from 'next/navigation'

interface Load {
    id: string
    exercise_id: string
    weight_kg: number
    reps_performed: number
    set_type: string
    notes?: string
    exercise: { id: string; name: string }
}

interface WorkoutLogReviewProps {
    logId: string
    userId: string
    workoutName: string
    completedAt: string
    loads: Load[]
}

const setTypeConfig: Record<string, { label: string; color: FontColor; bg: BoxColor; borderOpacity: number }> = {
    WARMUP: { label: 'Aquec.', color: 'amber', bg: 'amber', borderOpacity: 20 },
    FEEDER: { label: 'Feeder', color: 'blue', bg: 'blue', borderOpacity: 20 },
    WORKING: { label: 'Trab.', color: 'emerald', bg: 'emerald', borderOpacity: 20 },
}

const DEFAULT_SET_TYPE = { label: 'Desconhecido', color: 'zinc' as FontColor, bg: 'zinc' as BoxColor, borderOpacity: 20 }

export function WorkoutLogReview({ logId, userId, workoutName, completedAt, loads }: WorkoutLogReviewProps) {
    const { toast } = useToast()
    const router = useRouter()
    const queryClient = useQueryClient()

    // Local state: map of loadId -> { weight, reps }
    const [edits, setEdits] = useState<Record<string, { weight: string; reps: string }>>(() => {
        const init: Record<string, { weight: string; reps: string }> = {}
        if (Array.isArray(loads)) {
            loads.forEach(l => {
                if (l && l.id) {
                    init[l.id] = { weight: String(l.weight_kg ?? 0), reps: String(l.reps_performed ?? 0) }
                }
            })
        }
        return init
    })

    const { mutate: updateMutation } = useOptimisticMutation({
        queryKey: QUERY_KEYS.workouts.logs(userId),
        entity: ENTITIES.WORKOUT_LOG,
        actionName: 'update-load-entry',
        mutationFn: async () => { }, // Single-writer
    })

    // Group loads by exercise name
    const grouped = (Array.isArray(loads) ? loads : []).reduce((acc, load) => {
        if (!load) return acc
        const name = load.exercise?.name || 'Exercício'
        if (!acc[name]) acc[name] = []
        acc[name].push(load)
        return acc
    }, {} as Record<string, Load[]>)

    const handleSaveAll = () => {
        Object.entries(edits).forEach(([loadId, { weight, reps }]) => {
            const w = parseFloat(weight)
            const r = parseInt(reps)
            if (isNaN(w) || isNaN(r)) return

            updateMutation({ loadId, weightKg: w, repsPerformed: r })
        })

        toast({ title: 'Salvo!', description: 'Alterações enviadas para sincronização.' })
        router.push('/dashboard/student')
    }

    const date = new Date(completedAt).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' })
    const time = new Date(completedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })

    return (
        <Box display="flex" justify="center" fullWidth>
            <Box maxWidth="lg" display="flex" direction="col" gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                {/* Header */}
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Button variant="ghost" size="xs" gap={STORE_TOKENS.SPACING.NONE} asChild justify="start">
                        <Link href="/dashboard/student">
                            <Icon icon={ChevronLeft} size="xs" />
                            Voltar
                        </Link>
                    </Button>

                    <Box display="flex" align="start" gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <Box padding={STORE_TOKENS.PADDING.ELEMENT} bg={STORE_TOKENS.COLORS.SUCCESS} bgOpacity={STORE_TOKENS.OPACITY.SUBTLE} rounded={STORE_TOKENS.RADIUS.SYSTEM} border borderColor={STORE_TOKENS.COLORS.SUCCESS} borderOpacity={STORE_TOKENS.OPACITY.MEDIUM}>
                            <Icon icon={CheckCircle} size="md" color={STORE_TOKENS.COLORS.SUCCESS} />
                        </Box>
                        <Stack gap={STORE_TOKENS.SPACING.NONE}>
                            <Font
                                variant="h3"
                                weight="black"
                                uppercase
                                italic
                                {...{
                                    color: "white",
                                }}>
                                {workoutName}
                            </Font>
                            <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.NONE}>
                                <Icon icon={CheckCircle} size="xs" color={STORE_TOKENS.COLORS.SUCCESS} />
                                <Font
                                    variant="sub-tiny"
                                    weight="bold"
                                    uppercase
                                    tracking="widest"
                                    {...{
                                        color: "zinc-400",
                                    }}>
                                    Revisado em {date} às {time} • {Array.isArray(loads) ? loads.length : 0} séries
                                </Font>
                            </Box>
                        </Stack>
                    </Box>
                </Stack>

                {/* Exercises */}
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    {Object.entries(grouped).map(([exerciseName, exerciseLoads]) => (
                        <Box key={exerciseName} bg={STORE_TOKENS.COLORS.BACKGROUND} bgOpacity={STORE_TOKENS.OPACITY.LOW} border borderColor={STORE_TOKENS.COLORS.BACKGROUND} borderOpacity={STORE_TOKENS.OPACITY.SUBTLE} rounded={STORE_TOKENS.RADIUS.SYSTEM} overflow="hidden" display="flex" direction="col">
                            {/* Exercise title */}
                            <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.NONE} padding={STORE_TOKENS.PADDING.ELEMENT} bg={STORE_TOKENS.COLORS.BACKGROUND} bgOpacity={STORE_TOKENS.OPACITY.SUBTLE}>
                                <Icon icon={Dumbbell} size="sm" color={STORE_TOKENS.COLORS.BRAND} opacity={STORE_TOKENS.OPACITY.OVERLAY} />
                                <Font
                                    variant="body-sm"
                                    weight="black"
                                    uppercase
                                    italic
                                    {...{
                                        color: "white",
                                    }}>
                                    {exerciseName}
                                </Font>
                            </Box>
                            <Separator opacity={STORE_TOKENS.OPACITY.LOW} />

                            {/* Sets */}
                            <Box display="flex" direction="col">
                                {exerciseLoads.map((load, setIdx) => {
                                    const cfg = setTypeConfig[load.set_type] ?? DEFAULT_SET_TYPE
                                    const edit = edits[load.id] || { weight: '0', reps: '0' }
                                    const isLast = setIdx === exerciseLoads.length - 1

                                    return (
                                        <Stack key={load.id} gap={STORE_TOKENS.SPACING.NONE}>
                                            <Box
                                                display="flex"
                                                align="center"
                                                gap={STORE_TOKENS.SPACING.CONTAINER}
                                                padding={STORE_TOKENS.PADDING.ELEMENT}
                                            >
                                                {/* Set type badge */}
                                                <Box
                                                    bg={cfg.bg}
                                                    bgOpacity={STORE_TOKENS.OPACITY.SUBTLE}
                                                    border
                                                    borderColor={cfg.bg}
                                                    borderOpacity={STORE_TOKENS.OPACITY.SHELF}
                                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                                    padding={STORE_TOKENS.PADDING.ELEMENT}
                                                    shrink={0}
                                                >
                                                    <Font
                                                        variant="sub-tiny"
                                                        weight="black"
                                                        uppercase
                                                        {...{
                                                            color: cfg.color,
                                                        }}>
                                                        {cfg.label}
                                                    </Font>
