import { EmptyState } from '@/components/store/intermediary/empty-state'

type PhotoType = 'front_url' | 'back_url' | 'side_right_url' | 'side_left_url'

interface PhotoSet {
    id: string
    front_url?: string
    back_url?: string
    side_right_url?: string
    side_left_url?: string
    created_at: string
}

interface UnifiedProgressGalleryProps {
    photos: PhotoSet[]
    mode?: 'student' | 'trainer' | 'public'
    studentName?: string
    studentId?: string
}

export function UnifiedProgressGallery({ photos, mode = 'public', studentName, studentId }: UnifiedProgressGalleryProps) {
    const [activeFilter, setActiveFilter] = useState<PhotoType | 'all'>('all')
    const [selectedPhotoIndex, setSelectedPhotoIndex] = useState<number | null>(null)
    const [hoveredSetId, setHoveredSetId] = useState<string | null>(null)
    const [editingSetId, setEditingSetId] = useState<string | null>(null)
    const [editDate, setEditDate] = useState('')
    const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null)
    const [isPending, startTransition] = useTransition()
    const { toast } = useToast()

    const filters: { label: string, value: PhotoType | 'all' }[] = [
        { label: 'Todas', value: 'all' },
        { label: 'Frente', value: 'front_url' },
        { label: 'Costas', value: 'back_url' },
        { label: 'Lado D', value: 'side_right_url' },
        { label: 'Lado E', value: 'side_left_url' },
    ]

    const typeLabels: Record<string, string> = {
        'front_url': 'Frente',
        'back_url': 'Costas',
        'side_right_url': 'Lado Dir.',
        'side_left_url': 'Lado Esq.'
    }

    // 1. Sort photo sets by date (newest first)
    const sortedSets = [...photos].sort((a, b) =>
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
    )

    // 2. Flat list of all individual photos for the lightbox navigation
    const allItems: { url: string, type: PhotoType, date: string, setId: string }[] = []
    sortedSets.forEach(set => {
        if (set.front_url) allItems.push({ url: set.front_url, type: 'front_url', date: set.created_at, setId: set.id })
        if (set.back_url) allItems.push({ url: set.back_url, type: 'back_url', date: set.created_at, setId: set.id })
        if (set.side_right_url) allItems.push({ url: set.side_right_url, type: 'side_right_url', date: set.created_at, setId: set.id })
        if (set.side_left_url) allItems.push({ url: set.side_left_url, type: 'side_left_url', date: set.created_at, setId: set.id })
    })

    // 3. Filtered items for display
    const filteredItems = activeFilter === 'all'
        ? allItems
        : allItems.filter(item => item.type === activeFilter)

    const queryClient = useQueryClient()

    const { mutate: deleteMutate } = useOptimisticMutation({
        actionName: 'delete-progress-photo',
        entity: ENTITIES.PROGRESS_PHOTO,
        entityId: 'delete-photo',
        queryKey: QUERY_KEYS.student.photos(studentId || 'me'),
        mutationFn: async (variables: { photoId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(QUERY_KEYS.student.photos(studentId || 'me'))
            queryClient.setQueryData(QUERY_KEYS.student.photos(studentId || 'me'), (old: any) =>
                Array.isArray(old) ? old.filter((item: any) => item.id !== variables.photoId) : old
            )
            return { previous }
        },
        onSuccess: () => {
            toast({ title: "Removido!", description: "O registro de fotos está sendo removido." })
        },
        onError: (err, variables, ctx) => {
            queryClient.setQueryData(QUERY_KEYS.student.photos(studentId || 'me'), ctx?.previous)
            toast({ variant: "destructive", title: "Erro", description: "Falha ao remover." })
        }
    })

    const { mutate: updateDateMutate } = useOptimisticMutation({
        actionName: 'update-progress-photo-date',
        entity: ENTITIES.PROGRESS_PHOTO,
        entityId: 'update-photo',
        queryKey: QUERY_KEYS.student.photos(studentId || 'me'),
        mutationFn: async (variables: { photoId: string, newDate: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(QUERY_KEYS.student.photos(studentId || 'me'))
            queryClient.setQueryData(QUERY_KEYS.student.photos(studentId || 'me'), (old: any) =>
                Array.isArray(old) ? old.map((item: any) => item.id === variables.photoId ? { ...item, created_at: variables.newDate } : item) : old
            )
            setEditingSetId(null)
            return { previous }
        },
        onSuccess: () => {
            toast({ title: "Data atualizada!", description: "A data será refletida em todo o sistema em instantes." })
        },
        onError: (err, variables, ctx) => {
            queryClient.setQueryData(QUERY_KEYS.student.photos(studentId || 'me'), ctx?.previous)
            toast({ variant: "destructive", title: "Erro", description: "Falha ao atualizar data." })
        }
    })

    function handleDelete(setId: string) {
        setDeleteTargetId(setId)
    }

    function confirmDelete() {
        if (!deleteTargetId) return
        deleteMutate({ photoId: deleteTargetId })
        setDeleteTargetId(null)
    }

    function handleDateSave(setId: string) {
        if (!editDate) return
        updateDateMutate({ photoId: setId, newDate: new Date(editDate).toISOString() })
    }

    function startEditing(id: string, currentDate: string) {
        setEditingSetId(id)
        setEditDate(new Date(currentDate).toISOString().split('T')[0])
    }

    const canEdit = mode === 'student'

    if (photos.length === 0) {
        return (
            <EmptyState
                icon={Camera}
                title="NENHUMA FOTO ENCONTRADA"
                description="Nenhum registro de progresso físico foi anexado a este perfil."
            />
        )
    }

    const renderPhotoCard = (item: { url: string, type: PhotoType, date: string, setId: string }, index: number) => {
        return (
            <Box
                key={`${item.url}-${index}`}
                display="flex"
                direction="col"
                gap={STORE_TOKENS.SPACING.ELEMENT}
                onMouseEnter={() => setHoveredSetId(item.setId)}
                onMouseLeave={() => setHoveredSetId(null)}
                group
            >
                <Box
                    onClick={() => setSelectedPhotoIndex(index)}
                    position="relative"
                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                    overflow="hidden"
                    border
                    borderColor={STORE_TOKENS.COLORS.WHITE}
                    borderOpacity={STORE_TOKENS.OPACITY.LOW}
                    bg={STORE_TOKENS.COLORS.BACKGROUND}
                    cursor="pointer"
                    aspectRatio="3/4"
                    transition
                    hoverScale={98}
                    shadow="xl"
                    groupHoverBorderColor={STORE_TOKENS.COLORS.BRAND}
                >
                    <Image
                        src={item.url}
                        alt="Progresso"
                        fill
                        sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
                        {...{
                            className: "object-cover grayscale group-hover:grayscale-0 transition-all duration-700",
                        }} />
                    {/* Floating Badge Overlay (Top Left) */}
                    <Box position="absolute" top={2.5} left={2.5} pointerEvents="none">
                        <Badge variant="solid" color={STORE_TOKENS.COLORS.BRAND} label={typeLabels[item.type]} size="xs" />
                    </Box>

                    {/* Centered Hover Zoom Icon Overlay */}
                    <Box
                        position="absolute"
                        pin="inset"
                        display="flex"
                        align="center"
                        justify="center"
                        bg={STORE_TOKENS.COLORS.BLACK}
                        bgOpacity={STORE_TOKENS.OPACITY.HIGH}
                        opacity={STORE_TOKENS.OPACITY.NONE}
                        groupHoverOpacity={STORE_TOKENS.OPACITY.FULL}
                        transition
                        pointerEvents="none"
                    >
                        <Box
                            width={40}
                            height={40}
                            rounded={STORE_TOKENS.RADIUS.FULL}
                            bg={STORE_TOKENS.COLORS.BRAND}
                            bgOpacity={STORE_TOKENS.OPACITY.MEDIUM}
                            border={true}
                            borderColor={STORE_TOKENS.COLORS.BRAND}
                            borderOpacity={STORE_TOKENS.OPACITY.MODAL}
                            display="flex"
                            align="center"
                            justify="center"
                            scale={90}
                            groupHoverScale={100}
                            transition
                        >
                            <Icon icon={Maximize2} size="xs" color={STORE_TOKENS.COLORS.BRAND} />
                        </Box>
                    </Box>
                </Box>
            </Box>
        );
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
            {/* Header / Filter Section */}
            <Box
                display="flex"
                direction={{ base: 'col', md: 'row' }}
                align={{ base: 'stretch', md: 'center' }}
                justify="between"
                gap={STORE_TOKENS.SPACING.CONTAINER}
                padding={STORE_TOKENS.PADDING.NONE}
            >
                <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT} wrap="wrap" fullWidth>
                    <Icon icon={Filter} size="xs" color={STORE_TOKENS.COLORS.TEXT.SECONDARY} />
                    {filters.map((f) => {
                        const isActive = activeFilter === f.value
                        return (
                            <Box key={f.value} grow={1} shrink={0} display="flex">
                                <Button
                                    variant={isActive ? 'outline-primary' : 'outline-zinc'}
                                    size="xs"
                                    fullWidth={true}
                                    onClick={() => setActiveFilter(f.value)}
                                >
                                    {f.label}
                                </Button>
                            </Box>
                        )
                    })}
                </Box>

            </Box>
            <Separator opacity={STORE_TOKENS.OPACITY.SUBTLE} />
            {/* Gallery Content */}
            {activeFilter === 'all' ? (
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                    {sortedSets.map((set, idx) => {
                        const isEditing = editingSetId === set.id
                        const sessionPhotos = []
                        if (set.front_url) sessionPhotos.push({ url: set.front_url, type: 'front_url' as PhotoType, date: set.created_at, setId: set.id })
                        if (set.back_url) sessionPhotos.push({ url: set.back_url, type: 'back_url' as PhotoType, date: set.created_at, setId: set.id })
                        if (set.side_right_url) sessionPhotos.push({ url: set.side_right_url, type: 'side_right_url' as PhotoType, date: set.created_at, setId: set.id })
                        if (set.side_left_url) sessionPhotos.push({ url: set.side_left_url, type: 'side_left_url' as PhotoType, date: set.created_at, setId: set.id })

                        return (
                            <React.Fragment key={set.id}>
                                {idx > 0 && <Separator opacity={STORE_TOKENS.OPACITY.LOW} />}
                                <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                                    {/* Session Header */}
                                    <Stack
                                        direction={{ base: 'col', md: 'row' }}
                                        align={{ base: 'start', md: 'center' }}
                                        justify="between"
                                        gap={STORE_TOKENS.SPACING.CONTAINER}
                                        fullWidth
                                    >
                                        <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                            <Box
                                                padding={STORE_TOKENS.PADDING.ELEMENT}
                                                rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                                bg={STORE_TOKENS.COLORS.BRAND}
                                                bgOpacity={STORE_TOKENS.OPACITY.SUBTLE}
                                                display="flex"
                                                align="center"
                                                justify="center"
                                            >
                                                <Icon icon={Calendar} size="md" color={STORE_TOKENS.COLORS.BRAND} />
                                            </Box>
                                            <Font
                                                variant="body"
                                                weight="black"
                                                uppercase
                                                italic
                                                {...{
                                                    color: "white",
                                                }}>
                                                Atualização de {new Date(set.created_at).toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' })}
                                            </Font>
                                        </Box>

                                        <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                            {canEdit && (
                                                <>
                                                    {isEditing ? (
                                                        <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT} animateIn="slide-right">
                                                            <Input
                                                                type="date"
                                                                value={editDate}
                                                                onChange={(e) => setEditDate(e.target.value)}
                                                                width={150}
                                                                size="sm"
                                                            />
                                                            <Box display="flex" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                                                <Button
                                                                    size="sm"
                                                                    variant="primary"
                                                                    onClick={() => handleDateSave(set.id)}
                                                                >
                                                                    Salvar
                                                                </Button>
                                                                <Button
                                                                    size="sm"
                                                                    variant="close"
                                                                    isIconOnly
                                                                    rounded={STORE_TOKENS.RADIUS.FULL}
                                                                    onClick={() => setEditingSetId(null)}
                                                                >
                                                                    <Icon icon={X} size="xs" />
                                                                </Button>
                                                            </Box>
                                                        </Box>
                                                    ) : (
                                                        <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                                            <Button
                                                                variant="outline-zinc"
                                                                size="sm"
                                                                onClick={() => startEditing(set.id, set.created_at)}
                                                                gap={STORE_TOKENS.SPACING.ELEMENT}
                                                            >
                                                                <Icon icon={Pencil} size="xs" />
                                                                Editar Data
                                                            </Button>
                                                            <Button
                                                                variant="outline-zinc"
                                                                size="sm"
                                                                isIconOnly
                                                                rounded={STORE_TOKENS.RADIUS.FULL}
                                                                onClick={() => handleDelete(set.id)}
                                                            >
                                                                <Icon icon={X} size="xs" />
                                                            </Button>
                                                        </Box>
                                                    )}
                                                </>
                                            )}
                                        </Box>
                                    </Stack>

                                    {/* Photos Grid for this session (4 per row on md/lg screens) */}
                                    <Grid cols={{ base: 1, md: 4 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                                        {sessionPhotos.map((photo, pIdx) => {
                                            const globalIdx = allItems.findIndex(ai => ai.url === photo.url)
                                            return renderPhotoCard({ ...photo, date: set.created_at, setId: set.id }, globalIdx)
                                        })}
                                    </Grid>
                                </Stack>
                            </React.Fragment>
                        );
                    })}
                </Stack>
            ) : (
                /* Photos Grid for filtered view (4 per row on md/lg screens) */
                (<Grid cols={{ base: 1, md: 4 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                    {filteredItems.map((item, i) => {
                        const isEditing = editingSetId === item.setId

                        return (
                            <Stack key={`${item.url}-${i}`} gap={STORE_TOKENS.SPACING.ELEMENT}>
                                {renderPhotoCard(item, i)}
                                {canEdit && (
                                    <Box display="flex" align="center" justify="between" padding={STORE_TOKENS.PADDING.NONE}>
                                        {isEditing ? (
                                            <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth animateIn="zoom">
                                                <Input
                                                    type="date"
                                                    value={editDate}
                                                    onChange={(e) => setEditDate(e.target.value)}
                                                    size="sm"
                                                    color={STORE_TOKENS.COLORS.BACKGROUND}
                                                />
                                                <Box display="flex" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                                    <Button
                                                        size="xs"
                                                        isIconOnly
                                                        variant="outline-emerald"
                                                        onClick={() => handleDateSave(item.setId)}
                                                    >
                                                        <Icon icon={Check} size="xs" />
                                                    </Button>
                                                    <Button
                                                        size="xs"
                                                        isIconOnly
                                                        variant="outline-red"
                                                        onClick={() => setEditingSetId(null)}
                                                    >
                                                        <Icon icon={X} size="xs" />
                                                    </Button>
                                                </Box>
                                            </Box>
                                        ) : (
                                            <Box display="flex" align="center" justify="between" fullWidth group>
                                                <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.NONE}>
                                                    <Icon icon={Calendar} size="xs" color={STORE_TOKENS.COLORS.TEXT.SECONDARY} />
                                                    <Font
                                                        variant="sub-tiny"
                                                        weight="black"
                                                        uppercase
                                                        tracking="widest"
                                                        {...{
                                                            color: "zinc-400",
                                                        }}>
                                                        {new Date(item.date).toLocaleDateString()}
                                                    </Font>
                                                </Box>
                                                <Box opacity={STORE_TOKENS.OPACITY.NONE} groupHoverOpacity={STORE_TOKENS.OPACITY.FULL} transition>
                                                    <Button
                                                        variant="ghost"
                                                        size="xs"
                                                        isIconOnly
                                                        onClick={() => startEditing(item.setId, item.date)}
                                                    >
                                                        <Icon icon={Pencil} size="xs" />
                                                    </Button>
                                                </Box>
                                            </Box>
                                        )}
                                    </Box>
                                )}
                            </Stack>
                        );
                    })}
                </Grid>)
            )}
            {/* Lightbox Modal */}
            <Modal
                isOpen={selectedPhotoIndex !== null}
                onClose={() => setSelectedPhotoIndex(null)}
                title={selectedPhotoIndex !== null ? typeLabels[filteredItems[selectedPhotoIndex].type] : 'Visualização'}
                subtitle={selectedPhotoIndex !== null ? new Date(filteredItems[selectedPhotoIndex].date).toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' }) : ''}
                icon={Camera}
                hideCancel={true}
                confirmLabel="Fechar"
                onConfirm={() => setSelectedPhotoIndex(null)}
                noPadding
            >
                {selectedPhotoIndex !== null && (
                    <Box
                        position="relative"
                        display="flex"
                        align="center"
                        justify="center"
                        fullWidth
                        bg={STORE_TOKENS.COLORS.BACKGROUND}
                        bgOpacity={STORE_TOKENS.OPACITY.SHELF}
                        padding={STORE_TOKENS.PADDING.CONTAINER}
                    >
                        <Box
                            position="relative"
                            aspectRatio="3/4"
                            fullWidth
                            maxWidth={{ base: 'sm', md: 'md' }}
                            overflow="hidden"
                            rounded={STORE_TOKENS.RADIUS.SYSTEM}
                        >
                            <Image
                                src={filteredItems[selectedPhotoIndex].url}
                                alt="Visualização"
                                fill
                                sizes="(max-width: 768px) 100vw, 50vw"
                                priority
                                {...{
                                    className: "object-cover",
                                }} />
                        </Box>

                        {/* Controls/Navigation inside content box */}
                        {selectedPhotoIndex > 0 && (
                            <Box
                                position="absolute"
                                left={2.5}
                                top={0}
                                bottom={0}
                                display="flex"
                                align="center"
                            >
                                <Button
                                    variant="outline-zinc"
                                    isIconOnly
                                    onClick={(e) => {
                                        e.stopPropagation()
                                        setSelectedPhotoIndex(selectedPhotoIndex - 1)
                                    }}
                                >
                                    <Icon icon={ChevronLeft} size="sm" />
                                </Button>
                            </Box>
                        )}

                        {selectedPhotoIndex < filteredItems.length - 1 && (
                            <Box
                                position="absolute"
                                right={2.5}
                                top={0}
                                bottom={0}
                                display="flex"
                                align="center"
                            >
                                <Button
                                    variant="outline-zinc"
                                    isIconOnly
                                    onClick={(e) => {
                                        e.stopPropagation()
                                        setSelectedPhotoIndex(selectedPhotoIndex + 1)
                                    }}
                                >
                                    <Icon icon={ChevronRight} size="sm" />
                                </Button>
                            </Box>
                        )}

                        {/* Extra athlete info */}
                        {studentName && (
                            <Box
                                position="absolute"
                                bottom={2.5}
                                left={0}
                                right={0}
                                display="flex"
                                justify="center"
                                pointerEvents="none"
                            >
                                <Box
                                    bg={STORE_TOKENS.COLORS.BLACK}
                                    bgOpacity={STORE_TOKENS.OPACITY.MODAL}
                                    padding={STORE_TOKENS.PADDING.ELEMENT}
                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                    pointerEvents="auto"
                                >
                                    <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                                        <Font
                                            variant="sub-tiny"
                                            weight="bold"
                                            uppercase
                                            tracking="widest"
                                            {...{
                                                color: "zinc-400",
                                            }}>Atleta:</Font>
                                        <Font
                                            variant="sub-tiny"
                                            weight="black"
                                            uppercase
                                            italic
                                            {...{
                                                color: "primary",
                                            }}>
                                            {studentName}
                                        </Font>
                                    </Stack>
                                </Box>
                            </Box>
                        )}
                    </Box>
                )}
            </Modal>
            {/* Deletion Confirmation Modal */}
            <Modal
                isOpen={deleteTargetId !== null}
                onClose={() => setDeleteTargetId(null)}
                title="Excluir Registro"
                subtitle="Esta ação removerá permanentemente esta atualização de fotos do seu histórico."
                icon={X}
                variant="red"
                confirmLabel="Remover"
                cancelLabel="Cancelar"
                onConfirm={confirmDelete}
            >
                <Box padding={STORE_TOKENS.PADDING.NONE}>
                    <Font
                        variant="body"
                        align="center"
                        {...{
                            color: "zinc-400",
                        }}>
                        Tem certeza que deseja remover este registro de fotos? Essa ação não poderá ser desfeita.
                    </Font>
                </Box>
            </Modal>
        </Stack>
    );
}

'use client'

import React from 'react'
import { Stack } from '@/components/store/base/stack'
import { Inline } from '@/components/store/base/layout'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Input } from '@/components/store/base/input'
import { Button } from '@/components/store/base/button'
import { Icon } from '@/components/store/base/icon'
import { GlassPanel, Surface } from '@/components/store/base/surface'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { AssignmentBadge } from '@/components/store/intermediary/assignment-badge'
import { Pencil, Check, X, Calendar, Dumbbell, BarChart3, Users2, HeartHandshake, Zap, Users, ClipboardList, Activity, TrendingUp, Sparkles, Utensils, FlaskConical, FileUp, Flame, CreditCard, UserCheck, LayoutDashboard, LucideIcon } from 'lucide-react'
import { RegistryActionModal } from '@/components/store/advanced/registry-action-modal'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { assignWorkout } from '@/actions/workout-actions'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

const iconMap: Record<string, LucideIcon> = {
    BarChart3, Users2, HeartHandshake, Zap, Users, ClipboardList, Activity, TrendingUp, Sparkles, Utensils, Dumbbell, FlaskConical, FileUp, Flame, CreditCard, UserCheck, LayoutDashboard
}

interface WorkoutBuilderHeaderProps {
    workoutId: string
    name: string
    description: string
    isEditing: boolean
    setIsEditing: (val: boolean) => void
    editName: string
    setEditName: (val: string) => void
    editDesc: string
    setEditDesc: (val: string) => void
    onSave: () => void
    onCancel: () => void
    showAssignmentBadge?: boolean
    canAssign?: boolean
    assignments?: any[]
    students?: any[]
    contextLabel?: string
    icon?: string
    contextColor?: string
}

export function WorkoutBuilderHeader({
    workoutId,
    name,
    description,
    isEditing,
    setIsEditing,
    editName,
    setEditName,
    editDesc,
    setEditDesc,
    onSave,
    onCancel,
    showAssignmentBadge = true,
    canAssign = true,
    assignments = [],
    students = [],
    contextLabel,
    icon,
    contextColor
}: WorkoutBuilderHeaderProps) {
    const [isAssignModalOpen, setIsAssignModalOpen] = React.useState(false)

    const { mutate: assignMutation } = useOptimisticMutation({
        queryKey: ['workout'],
        entity: ENTITIES.WORKOUT,
        actionName: 'assign-workout',
        mutationFn: async ({ workoutId, day, studentId }: { workoutId: string, day: number, studentId: string }) => {
            const res = await assignWorkout(workoutId, studentId, day)
            if (res.error) throw new Error(res.error)
            return res
        }
    })

    const handleAssignConfirm = (data?: any) => {
        if (!data || !data.student_id) return

        const { selectedDays, student_id } = data
        if (Array.isArray(selectedDays)) {
            selectedDays.forEach(day => {
                assignMutation({ workoutId, day, studentId: student_id })
            })
        }
        setIsAssignModalOpen(false)
    }
    const IconComp = icon ? (iconMap[icon] || Dumbbell) : null

    return (
        <Stack
            direction={{ base: 'col', md: 'row' }}
            align={{ base: 'stretch', md: 'start' }}
            justify="between"
            gap={STORE_TOKENS.SPACING.SECTION}
            fullWidth
        >
            <Box flex1>
                {isEditing ? (
                    <GlassPanel padding={STORE_TOKENS.SPACING.CONTAINER}>
                        <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Font
                                    variant="sub-tiny"
                                    uppercase
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                    }}>Nome do Treino</Font>
                                <Input
                                    value={editName}
                                    onChange={e => setEditName(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Enter') onSave(); if (e.key === 'Escape') onCancel() }}
                                    placeholder="Ex: Hipertrofia A - Peito/Tríceps"
                                    size="lg"
                                    autoFocus
                                />
                            </Stack>
                            <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Font
                                    variant="sub-tiny"
                                    uppercase
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                    }}>Descrição (Opcional)</Font>
                                <Input
                                    value={editDesc}
                                    onChange={e => setEditDesc(e.target.value)}
                                    onKeyDown={e => { if (e.key === 'Escape') onCancel() }}
                                    placeholder="Ex: Foco na contração e descanso rápido"
                                />
                            </Stack>
                            <Stack direction={{ base: 'col', md: 'row' }} gap={STORE_TOKENS.SPACING.ELEMENT}>
                                <Button
                                    variant="outline-emerald"
                                    onClick={onSave}
                                    gap={STORE_TOKENS.SPACING.ELEMENT}
                                    fullWidth={{ base: true, md: false }}
                                >
                                    <Icon icon={Check} size="xs" />
                                    Salvar
                                </Button>
                                <Button
                                    variant="outline-red"
                                    onClick={onCancel}
                                    gap={STORE_TOKENS.SPACING.ELEMENT}
                                    fullWidth={{ base: true, sm: false }}
                                >
                                    <Icon icon={X} size="xs" />
                                    Cancelar
                                </Button>
                            </Stack>
                        </Stack>
                    </GlassPanel>
                ) : (
                    <Box
                        display="flex"
                        align="start"
                        gap={STORE_TOKENS.SPACING.ELEMENT}
                        cursor="pointer"
                        onClick={() => setIsEditing(true)}
                    >
                        <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                            {contextLabel && IconComp && (
                                <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                    <Icon icon={IconComp} color={contextColor as any || STORE_TOKENS.COLORS.SUCCESS} size="lg" />
                                    <Font
                                        variant="auxiliary"
                                        uppercase
                                        {...{
                                            color: contextColor as any || STORE_TOKENS.COLORS.SUCCESS,
                                        }}>{contextLabel}</Font>
                                </Inline>
                            )}
                            <Inline align="center" gap={STORE_TOKENS.SPACING.TINY}>
                                <Font
                                    variant="h1"
                                    uppercase
                                    {...{
                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                    }}>{name}</Font>
                                <Box
                                    padding={STORE_TOKENS.SPACING.TINY}
                                    rounded={STORE_TOKENS.RADIUS.SYSTEM}
                                    hoverBg={STORE_TOKENS.COLORS.BACKGROUND}
                                    display="flex"
                                    align="center"
                                    justify="center"
                                    // EXCEPTION: Icon button hover states in base component layer
                                >
                                    <Icon icon={Pencil} size="sm" color={STORE_TOKENS.COLORS.BRAND} />
                                </Box>
                            </Inline>
                            <Font
                                variant="description"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                }}>{description || 'Sem descrição'}</Font>


                        </Stack>
                    </Box>
                )}
            </Box>
            {canAssign && !isEditing && (
                <Stack direction={{ base: 'col', md: 'row' }} align={{ base: 'stretch', md: 'center' }} justify="end" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    {showAssignmentBadge && assignments && assignments.length > 0 && (
                        <AssignmentBadge
                            studentName={assignments[0]?.student?.full_name || 'Aluno'}
                            studentAvatarUrl={assignments[0]?.student?.avatar_url}
                            daysOfWeek={assignments[0]?.days_of_week}
                            variant="warning"
                        />
                    )}
                    <Box shrink={0} display="flex" justify="center">
                        <Button variant="outline-orange" size="lg" shine fullWidth={{ base: true, md: false }} onClick={() => setIsAssignModalOpen(true)}>
                            <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                <Icon icon={Calendar} size="sm" color={STORE_TOKENS.COLORS.BRAND} />
                                {assignments?.length ? "Gerenciar Atribuição" : "Atribuir"}
                            </Inline>
                        </Button>
                    </Box>
                    <RegistryActionModal
                        isOpen={isAssignModalOpen}
                        onClose={() => setIsAssignModalOpen(false)}
                        type="assign_training"
                        onConfirm={handleAssignConfirm}
                        students={students}
                        initialData={{
                            student_id: assignments?.[0]?.student_id,
                            selectedDays: assignments?.[0]?.days_of_week || []
                        }}
                    />
                </Stack>
            )}
        </Stack>
    );
}

'use client'

import React from 'react'
import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { Font } from '@/components/store/base/font'
import { Input } from '@/components/store/base/input'
import { Button } from '@/components/store/base/button'
import { Icon } from '@/components/store/base/icon'
import { GlassPanel, Card, Surface } from '@/components/store/base/surface'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { PlusCircle, Search, Plus } from 'lucide-react'


interface WorkoutBuilderSearchProps {
    searchQuery: string
    isSearching: boolean
    searchResults: any[]
    onSearch: (e: React.ChangeEvent<HTMLInputElement>) => void
    onAddExercise: (ex: any) => void
    onAddCustom: () => void
}

export function WorkoutBuilderSearch({
    searchQuery,
    isSearching,
    searchResults,
    onSearch,
    onAddExercise,
    onAddCustom
}: WorkoutBuilderSearchProps) {
    return (
        <GlassPanel 
            padding={STORE_TOKENS.SPACING.CONTAINER} 
            border="subtle"
            position="relative"
            // eslint-disable-next-line no-restricted-syntax
            zIndex={searchResults.length > 0 ? STORE_TOKENS.Z_INDEX.OVERLAY : undefined}
        >
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                {/* Relative container around input to position the dropdown overlay */}
                {/* eslint-disable-next-line no-restricted-syntax */}
                <Box position="relative" width="full" zIndex={searchResults.length > 0 ? STORE_TOKENS.Z_INDEX.OVERLAY : 'auto'}>
                    <Input
                        icon={<Icon icon={Search} size="sm" />}
                        placeholder="Busque por exercícios (ex: Supino, Agachamento...)"
                        value={searchQuery}
                        onChange={onSearch}
                        size="lg"
                    />

                    {/* Standard absolute Card dropdown matching FormSelect exactly */}
                    {searchResults.length > 0 && (
                        <Card 
                            position="absolute" 
                            top="calc(100% + 4px)" 
                            left={0} 
                            right={0} 
                            zIndex={STORE_TOKENS.Z_INDEX.OVERLAY} 
                            border="subtle"
                            padding={STORE_TOKENS.PADDING.NONE}
                            overflow="auto"
                        >
                            <Stack gap={STORE_TOKENS.SPACING.NONE}>
                                {searchResults.map((ex) => (
                                    <Box
                                        key={ex.id}
                                        as="button"
                                        type="button"
                                        onClick={() => onAddExercise(ex)}
                                        display="flex"
                                        align="center"
                                        justify="between"
                                        fullWidth
                                        padding={STORE_TOKENS.PADDING.ELEMENT}
                                        transition
                                        hoverBg={STORE_TOKENS.COLORS.WHITE}
                                        hoverBgOpacity={STORE_TOKENS.OPACITY.LOW}
                                        cursor="pointer"
                                    >
                                        <Stack direction="col" gap={STORE_TOKENS.SPACING.ELEMENT} align="start">
                                            <Font
                                                variant="label-caps"
                                                {...{
                                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                }}>
                                                {ex.name}
                                            </Font>
                                            <Font
                                                variant="sub-tiny"
                                                {...{
                                                    color: STORE_TOKENS.COLORS.TEXT.DIM,
                                                }}>
                                                {ex.is_system_default ? 'BIBLIOTECA' : 'PERSONALIZADO'}
                                            </Font>
                                        </Stack>
                                        <Icon icon={Plus} size="xs" color={STORE_TOKENS.COLORS.TEXT.MUTED} />
                                    </Box>
                                ))}
                            </Stack>
                        </Card>
                    )}
                </Box>

                {searchQuery.length >= 2 && !isSearching && searchResults.length === 0 && (
                    <Surface 
                        variant="sunken" 
                        padding={STORE_TOKENS.PADDING.CONTAINER} 
                        rounded={STORE_TOKENS.RADIUS.SYSTEM} 
                        border="subtle"
                    >
                        <Stack direction={{ base: 'col', md: 'row' }} align={{ base: 'stretch', md: 'center' }} justify="between" gap={STORE_TOKENS.SPACING.ELEMENT}>
                            <Font
                                variant="body"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.MUTED,
                                }}>
                                "{<Font
                                variant="body"
                                weight="bold"
                                {...{
                                    color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                }}>{searchQuery}</Font>}" não encontrado na biblioteca.
                            </Font>
                            <Button
                                variant="outline-blue"
                                onClick={onAddCustom}
                                shrink={0}
                                size="sm"
                            >
                                <Icon icon={Plus} size="xs" color={STORE_TOKENS.COLORS.INFO} />
                                Criar Novo Exercício
                            </Button>
                        </Stack>
                    </Surface>
                )}
            </Stack>
        </GlassPanel>
    );
}

// Inline helper wrapping component conforming to design rules
function InlineWrapper({ children }: { children: React.ReactNode }) {
    return (
        <Box display="flex" align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
            {children}
        </Box>
    )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useToast } from '@/hooks/use-toast'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { getWorkoutDetails, searchExercises } from '@/actions/workout-actions'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

import { Stack } from '@/components/store/base/stack'
import { Box } from '@/components/store/base/box'
import { GlassPanel } from '@/components/store/base/surface'
import { Separator } from '@/components/store/base/separator'
import { Inline } from '@/components/store/base/layout'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { Button } from '@/components/store/base/button'
import { Badge } from '@/components/store/base/badge'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Loader2, ArrowLeft, Dumbbell } from 'lucide-react'
import Link from 'next/link'
import { EmptyState } from '@/components/store/intermediary/empty-state'

import { WorkoutBuilderHeader } from './workout-builder-header'
import { WorkoutBuilderExerciseCard } from './workout-builder-exercise-card'
import { WorkoutBuilderSearch } from './workout-builder-search'

interface WorkoutBuilderSmartProps {
    workout: any
    students?: any[]
    backHref?: string
    canAssign?: boolean
    showAssignmentBadge?: boolean
    hideHeader?: boolean
    contextLabel?: string
    icon?: string
    contextColor?: string
}

export function WorkoutBuilderSmart({
    workout: initialWorkout,
    students = [],
    backHref = '/dashboard/trainer/workouts',
    canAssign = true,
    showAssignmentBadge = true,
    hideHeader = false,
    contextLabel,
    icon,
    contextColor
}: WorkoutBuilderSmartProps) {
    const { toast } = useToast()
    const queryClient = useQueryClient()
    const queryKey = QUERY_KEYS.workouts.detail(initialWorkout.id)

    const { data: workoutData } = useQuery({
        queryKey,
        queryFn: () => getWorkoutDetails(initialWorkout.id),
        initialData: initialWorkout,
    })

    const workout = workoutData as any | null
    const exercises = workout?.workout_exercises || []

    const [searchQuery, setSearchQuery] = useState('')
    const [searchResults, setSearchResults] = useState<any[]>([])
    const [isSearching, setIsSearching] = useState(false)
    const [draggedId, setDraggedId] = useState<string | null>(null)

    const [isEditingMeta, setIsEditingMeta] = useState(false)
    const [editName, setEditName] = useState(workout?.name || '')
    const [editDesc, setEditDesc] = useState(workout?.description || '')

    useEffect(() => {
        if (!isEditingMeta && workout) {
            setEditName(workout.name)
            setEditDesc(workout.description || '')
        }
    }, [workout?.name, workout?.description, isEditingMeta])

    // MUTATIONS
    const { mutate: reorderMutate } = useOptimisticMutation({
        actionName: 'update-workout-exercises-order',
        entity: ENTITIES.WORKOUT,
        entityId: workout?.id || '',
        queryKey,
        mutationFn: async (variables: { orderedIds: string[] }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => {
                const exs = [...(old?.workout_exercises || [])]
                const sorted = variables.orderedIds.map(id => exs.find(ex => ex.id === id)).filter(Boolean)
                return { ...old, workout_exercises: sorted }
            })
            return { previous }
        }
    })

    const { mutate: mutateMeta } = useOptimisticMutation({
        actionName: 'update-workout-meta',
        entity: ENTITIES.WORKOUT,
        entityId: workout?.id || '',
        queryKey,
        mutationFn: async (variables: { id: string, name: string, description: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({ ...old, ...variables }))
            return { previous }
        },
        onSuccess: () => setIsEditingMeta(false)
    })

    const { mutate: addExerciseMutate } = useOptimisticMutation({
        actionName: 'add-exercise-to-workout',
        entity: ENTITIES.WORKOUT,
        entityId: workout?.id || '',
        queryKey,
        mutationFn: async (variables: { exerciseId: string, workoutId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            const exerciseToAdd = searchResults.find(ex => ex.id === variables.exerciseId)
            if (exerciseToAdd) {
                queryClient.setQueryData(queryKey, (old: any) => ({
                    ...old,
                    workout_exercises: [...(old?.workout_exercises || []), {
                        id: `temp-${Date.now()}`,
                        workout_id: workout?.id || '',
                        exercise_id: variables.exerciseId,
                        exercise: exerciseToAdd,
                        warmup_sets: 0, warmup_reps: '15', warmup_rest_seconds: 60,
                        feeder_sets: 0, feeder_reps: '10', feeder_rest_seconds: 60,
                        working_sets: 3, reps: '10-12', rest_seconds: 90,
                        notes: ''
                    }]
                }))
            }
            return { previous }
        },
        onSuccess: () => {
            setSearchQuery('')
            setSearchResults([])
        }
    })

    const { mutate: addCustomMutate } = useOptimisticMutation({
        actionName: 'create-new-exercise',
        entity: ENTITIES.WORKOUT,
        entityId: workout?.id || '',
        queryKey,
        mutationFn: async (variables: { name: string }) => variables,
        onSuccess: () => {
            setSearchQuery('')
            setSearchResults([])
            toast({ title: "Exercício criado", description: "O exercício será adicionado ao treino após o processamento." })
        }
    })

    const { mutate: removeMutate } = useOptimisticMutation({
        actionName: 'remove-exercise-from-workout',
        entity: ENTITIES.WORKOUT_EXERCISE,
        entityId: 'remove',
        queryKey,
        mutationFn: async (variables: { id: string, workoutId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                workout_exercises: (old?.workout_exercises || []).filter((ex: any) => ex.id !== variables.id)
            }))
            return { previous }
        }
    })

    const { mutate: updateMutate } = useOptimisticMutation({
        actionName: 'update-workout-exercise',
        entity: ENTITIES.WORKOUT_EXERCISE,
        entityId: 'update',
        queryKey,
        mutationFn: async (variables: { id: string, data: any, workoutId: string }) => variables,
        onMutate: (variables) => {
            const previous = queryClient.getQueryData(queryKey)
            queryClient.setQueryData(queryKey, (old: any) => ({
                ...old,
                workout_exercises: (old?.workout_exercises || []).map((ex: any) =>
                    ex.id === variables.id ? { ...ex, ...variables.data } : ex
                )
            }))
            return { previous }
        }
    })

    if (!workout) {
        return (
            <Box display="flex" direction="col" align="center" justify="center" minHeight="lg" gap={STORE_TOKENS.SPACING.SECTION}>
                <Icon icon={Loader2} size="lg" color={STORE_TOKENS.COLORS.SUCCESS} spin />
                <Stack align="center" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="heading"
                        uppercase
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                        }}>Sincronizando Dados...</Font>
                    <Font
                        variant="description"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.MUTED,
                        }}>Preparando sua biblioteca de exercícios</Font>
                </Stack>
            </Box>
        );
    }

    // HANDLERS
    function handleDragStart(e: React.DragEvent, id: string) {
        setDraggedId(id)
        if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move'
    }

    function handleDragOver(e: React.DragEvent, targetId: string) {
        e.preventDefault()
        if (e.dataTransfer) e.dataTransfer.dropEffect = 'move'
        if (!draggedId || draggedId === targetId) return

        const draggedIndex = exercises.findIndex((ex: any) => ex.id === draggedId)
        const targetIndex = exercises.findIndex((ex: any) => ex.id === targetId)
        if (draggedIndex === -1 || targetIndex === -1) return

        const newOrder = [...exercises]
        const [removed] = newOrder.splice(draggedIndex, 1)
        newOrder.splice(targetIndex, 0, removed)

        queryClient.setQueryData(queryKey, (old: any) => ({ ...old, workout_exercises: newOrder }))
    }

    function handleDragEnd() {
        if (!draggedId || !workout) return
        setDraggedId(null)
        reorderMutate({
            orderedIds: exercises.map((ex: any) => ex.id),
            workoutId: workout.id
        })
    }

    async function handleSearch(e: React.ChangeEvent<HTMLInputElement>) {
        const query = e.target.value
        setSearchQuery(query)
        if (query.length < 2) {
            setSearchResults([])
            return
        }
        setIsSearching(true)
        const results = await searchExercises(query)
        setSearchResults(results)
        setIsSearching(false)
    }

    return (
        <Stack gap={{ base: STORE_TOKENS.SPACING.SECTION, md: STORE_TOKENS.SPACING.SECTION }}>
            {!hideHeader && (
                <WorkoutBuilderHeader
                    workoutId={workout.id}
                    name={workout.name}
                    description={workout.description}
                    isEditing={isEditingMeta}
                    setIsEditing={setIsEditingMeta}
                    editName={editName}
                    setEditName={setEditName}
                    editDesc={editDesc}
                    setEditDesc={setEditDesc}
                    onSave={() => mutateMeta({ id: workout.id, name: editName, description: editDesc })}
                    onCancel={() => {
                        setEditName(workout.name)
                        setEditDesc(workout.description || '')
                        setIsEditingMeta(false)
                    }}
                    showAssignmentBadge={showAssignmentBadge}
                    canAssign={canAssign}
                    assignments={workout.assignments}
                    students={students}
                    contextLabel={contextLabel}
                    icon={icon}
                    contextColor={contextColor}
                />
            )}
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                <Stack direction={{ base: 'col', md: 'row' }} align={{ base: 'start', md: 'center' }} justify="between" gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="heading"
                        uppercase
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                        }}>
                        Exercícios no Treino
                    </Font>
                    <Badge
                        label={`Número de exercícios: ${exercises.length}`}
                        variant="glass"
                        color={contextColor as any || STORE_TOKENS.COLORS.BRAND}
                        size="sm"
                        rounded={STORE_TOKENS.RADIUS.SYSTEM}
                    />
                </Stack>

                {exercises.length > 0 ? (
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        {exercises.map((item: any) => (
                            <WorkoutBuilderExerciseCard
                                key={item.id}
                                item={item}
                                isDragged={draggedId === item.id}
                                onDragStart={handleDragStart}
                                onDragOver={handleDragOver}
                                onDragEnd={handleDragEnd}
                                onRemove={(id) => removeMutate({ id, workoutId: workout.id })}
                                onUpdate={(id, data) => updateMutate({ id, data, workoutId: workout.id })}
                            />
                        ))}
                    </Stack>
                ) : (
                    <EmptyState
                        icon={Dumbbell}
                        title="NENHUM EXERCÍCIO ADICIONADO"
                        description="Use a busca abaixo para começar."
                    />
                )}
            </Stack>
            <WorkoutBuilderSearch
                searchQuery={searchQuery}
                isSearching={isSearching}
                searchResults={searchResults}
                onSearch={handleSearch}
                onAddExercise={(ex) => addExerciseMutate({ exerciseId: ex.id, workoutId: workout.id })}
                onAddCustom={() => addCustomMutate({ name: searchQuery })}
            />
            <Box display="flex" justify="center">
                <Button
                    asChild
                    variant="outline-zinc"
                    fullWidth={{ base: true, sm: false }}
                    paddingY={STORE_TOKENS.SPACING.ELEMENT}
                    paddingX={STORE_TOKENS.SPACING.CONTAINER}
                    gap={STORE_TOKENS.SPACING.ELEMENT}
                >
                    <Link href={backHref}>
                        <Icon icon={ArrowLeft} size="xs" />
                        Voltar para a Biblioteca de Treinos
                    </Link>
                </Button>
            </Box>
        </Stack>
    );
}

'use client';
import { STORE_TOKENS } from '@/components/store/constants/tokens';

import React, { useState } from 'react'
import { FormSelect } from '@/components/store/base/form-select'
import { useToast } from '@/hooks/use-toast'
import { Loader2 } from 'lucide-react'
import { Stack } from '@/components/store/base/stack'
import { Icon } from '@/components/store/base/icon'
import { Box } from '@/components/store/base/box'
import { useOptimisticMutation } from '@/hooks/use-optimistic-mutation'
import { useQueryClient } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { ENTITIES } from '@/lib/outbox-db'

interface WorkoutDaySelectorProps {
    userId: string
    assignmentId: string
    dayOfWeek: number | null
}

/**
 * WorkoutDaySelector: A modern, design-system-compliant dropdown to schedule student workouts.
 * Uses FormSelect and adheres to the Atomic Design Rules.
 */
export function WorkoutDaySelector({ userId, assignmentId, dayOfWeek }: WorkoutDaySelectorProps) {
    const { toast } = useToast()
    const queryClient = useQueryClient()
    const [currentDay, setCurrentDay] = useState(dayOfWeek === null ? 'none' : String(dayOfWeek))

    const options = [
        { label: 'Sem Dia Definido', value: 'none' },
        { label: 'Segunda-feira', value: '1' },
        { label: 'Terça-feira', value: '2' },
        { label: 'Quarta-feira', value: '3' },
        { label: 'Quinta-feira', value: '4' },
        { label: 'Sexta-feira', value: '5' },
        { label: 'Sábado', value: '6' },
        { label: 'Domingo', value: '0' },
    ]

    const { mutate: updateDayMutation, isPending } = useOptimisticMutation({
        actionName: 'update-student-workout-day',
        queryKey: QUERY_KEYS.workouts.all(userId),
        entity: ENTITIES.ASSIGNED_WORKOUT,
        entityId: assignmentId,
        onMutate: (variables: any) => {
            // Optimistic update of the workouts list query
            queryClient.setQueryData(QUERY_KEYS.workouts.all(userId), (old: any) => {
                if (!old) return old;
                return old.map((aw: any) => {
                    if (aw.id === variables.assignmentId) {
                        return { ...aw, day_of_week: variables.dayOfWeek };
                    }
                    return aw;
                });
            });

            toast({
                title: 'Cronograma atualizado!',
                description: variables.dayOfWeek === null 
                    ? 'Treino definido como sem dia fixo.' 
                    : `Treino agendado para ${options.find(o => o.value === String(variables.dayOfWeek))?.label || 'o dia selecionado'}.`,
            });
        },
        onError: (err: any) => {
            toast({
                title: 'Falha ao atualizar!',
                description: err.message || 'Houve um erro ao salvar o novo dia.',
            });
        }
    })

    const handleChange = (val: string) => {
        setCurrentDay(val)
        const targetDay = val === 'none' ? null : parseInt(val)
        updateDayMutation({ assignmentId, dayOfWeek: targetDay })
    }

    return (
        <Box width={240}>
            <Stack direction="row" align="center" gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth>
                {isPending && <Icon icon={Loader2} size="xs" color={STORE_TOKENS.COLORS.BRAND} spin />}
                <FormSelect
                    options={options}
                    value={currentDay}
                    onChange={handleChange}
                    placeholder="Agendar Dia"
                />
            </Stack>
        </Box>
    );
}

