'use client'

import React, { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { Box } from '@/components/store/base/box'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Button } from '@/components/store/base/button'
import { Input } from '@/components/store/base/input'
import { ModalOverlay, ModalContainer } from '@/components/store/base/layout'
import { Icon } from '@/components/store/base/icon'
import { useRegistry } from '@/components/store/advanced/registry-context'
import { ArrowRight, Loader2 } from 'lucide-react'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

interface LeadCaptureModalProps {
  isOpen: boolean
  onOpenChange: (open: boolean) => void
  trainerName?: string
  trainerCode?: string
}

export function LandingLeadModal({ isOpen, onOpenChange, trainerName, trainerCode }: LeadCaptureModalProps) {
  const { primaryColor } = useRegistry()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [fullName, setFullName] = useState('')
  const [whatsapp, setWhatsapp] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)
  const router = useRouter()
  const supabase = createClient()

  const [animateState, setAnimateState] = useState<'closed' | 'open'>('closed')

  useEffect(() => {
    if (isOpen) {
      setAnimateState('open')
    } else {
      setAnimateState('closed')
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError(null)

    try {
      const { error: signUpError, data } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            full_name: fullName,
            whatsapp: whatsapp,
            role: 'student',
          },
        },
      })
      if (signUpError) throw signUpError

      // Guarantee the name is saved regardless of trigger behavior
      if (data?.user?.id) {
        await supabase
          .from('profiles')
          .update({ full_name: fullName, whatsapp: whatsapp })
          .eq('id', data.user.id)
      }

      // Success state
      setSuccess(true)

      // Wait a moment for the user to see the success message
      setTimeout(() => {
        onOpenChange(false)
        if (trainerCode) {
          router.push(`/personal/${trainerCode.toUpperCase().trim()}`)
        } else {
          router.push('/dashboard/student')
        }
      }, 1500)

    } catch (err: any) {
      setError(err.message)
    } finally {
      if (!success) setLoading(false)
    }
  }

  if (!isOpen) return null

  return (
    <ModalOverlay onClose={() => onOpenChange(false)} animateState={animateState}>
      <ModalContainer animateState={animateState}>
        <Box 
          bg={STORE_TOKENS.COLORS.BACKGROUND} 
          bgOpacity={STORE_TOKENS.OPACITY.SURFACE}
          padding={STORE_TOKENS.PADDING.CONTAINER}
          rounded={STORE_TOKENS.RADIUS.SYSTEM}
          border
          borderColor={STORE_TOKENS.COLORS.BACKGROUND}
          borderOpacity={STORE_TOKENS.OPACITY.MEDIUM}
          maxWidth="auth-form"
          width="full"
          position="relative"
          overflow="hidden"
          shadow="xl"
        >
          <Box position="relative" zIndex={STORE_TOKENS.Z_INDEX.CONTENT}>
            {!success ? (
              <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                
                {/* Header text */}
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT} align="center" textAlign="center">
                  <Font variant="h3" color={STORE_TOKENS.COLORS.TEXT.PRIMARY} uppercase italic align="center">
                    Crie sua conta Grátis
                  </Font>
                  <Font variant="body-sm" color={STORE_TOKENS.COLORS.TEXT.SECONDARY} align="center">
                    {trainerName
                      ? `Para entrar em contato com ${trainerName}, você precisa de uma conta no RepTrail.`
                      : 'Junte-se ao RepTrail para acessar os melhores treinadores.'}
                  </Font>
                </Stack>

                {/* Form fields */}
                <Box as="form" onSubmit={handleSubmit} width="full">
                  <Stack gap={STORE_TOKENS.SPACING.CONTAINER} fullWidth>
                    {error && (
                      <Box 
                        padding={STORE_TOKENS.PADDING.ELEMENT} 
                        bg={STORE_TOKENS.COLORS.ERROR} 
                        bgOpacity={STORE_TOKENS.OPACITY.SUBTLE} 
                        border 
                        borderColor={STORE_TOKENS.COLORS.ERROR} 
                        borderOpacity={STORE_TOKENS.OPACITY.MEDIUM} 
                        rounded={STORE_TOKENS.RADIUS.SYSTEM}
                      >
                        <Font variant="auxiliary" color={STORE_TOKENS.COLORS.ERROR} weight="black" uppercase tracking="wider">
                          {error}
                        </Font>
                      </Box>
                    )}

                    <Input
                      label="Nome Completo"
                      placeholder="Seu nome"
                      value={fullName}
                      onChange={(e: any) => setFullName(e.target.value)}
                      required
                    />

                    <Input
                      label="Email"
                      type="email"
                      placeholder="seu@email.com"
                      value={email}
                      onChange={(e: any) => setEmail(e.target.value)}
                      required
                    />

                    <Input
                      label="WhatsApp"
                      placeholder="(11) 99999-9999"
                      mask="phone"
                      value={whatsapp}
                      onChange={(e: any) => setWhatsapp(e.target.value)}
                      required
                    />

                    <Input
                      label="Senha"
                      type="password"
                      placeholder="••••••••"
                      value={password}
                      onChange={(e: any) => setPassword(e.target.value)}
                      required
                    />

                    <Box width="full">
                      <Button
                        type="submit"
                        variant="primary"
                        size="lg"
                        activeScale={95}
                        fullWidth
                        loading={loading}
                      >
                        <Box as="span" display="flex" align="center" justify="center" gap={STORE_TOKENS.SPACING.ELEMENT} cursor="pointer">
                          <Font variant="body" weight="medium">Criar Conta & Contatar</Font>
                          <Icon icon={ArrowRight} size="sm" />
                        </Box>
                      </Button>
                    </Box>
                  </Stack>
                </Box>

                {/* Bottom link */}
                <Box align="center" justify="center">
                  <Font variant="sub-tiny" color={STORE_TOKENS.COLORS.TEXT.SECONDARY} align="center" weight="medium">
                    Já tem uma conta?{' '}
                    <Link href="/auth/login">
                      <Box as="span">Fazer Login</Box>
                    </Link>
                  </Font>
                </Box>
              </Stack>
            ) : (
              <Stack gap={STORE_TOKENS.SPACING.CONTAINER} align="center" justify="center">
                <Box 
                  width={80} 
                  height={80} 
                  bg={STORE_TOKENS.COLORS.BRAND} 
                  rounded={STORE_TOKENS.RADIUS.FULL} 
                  align="center" 
                  justify="center" 
                >
                  <Icon icon={ArrowRight} size="lg" color={STORE_TOKENS.COLORS.WHITE} />
                </Box>
                
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT} align="center" textAlign="center">
                  <Font variant="h3" color={STORE_TOKENS.COLORS.TEXT.PRIMARY} uppercase italic align="center">
                    Conta Criada!
                  </Font>
                  <Font variant="body-sm" color={STORE_TOKENS.COLORS.TEXT.SECONDARY} align="center">
                    Redirecionando você para {trainerName || 'o perfil'}...
                  </Font>
                </Stack>

                <Icon icon={Loader2} size="md" color={STORE_TOKENS.COLORS.BRAND} animate="spin" opacity={STORE_TOKENS.OPACITY.MODAL} />
              </Stack>
            )}
          </Box>
        </Box>
      </ModalContainer>
    </ModalOverlay>
  );
}

'use client'

import React, { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Stack } from '@/components/store/base/stack'
import { Grid } from '@/components/store/base/grid'
import { Input } from '@/components/store/base/input'
import { StoreHeroCard } from '@/components/store/intermediary/store-hero-card'
import { StoreProductCard } from '@/components/store/intermediary/store-product-card'
import { ShoppingBag, Search } from 'lucide-react'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { FormSelect } from '@/components/store/base/form-select'
import { Box } from '@/components/store/base/box'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getStoreProducts, logProductClick } from '@/actions/store-actions'

/**
 * MarketplaceSectionContent: The composite content for the Marketplace & Performance section.
 * Fully data-driven via React Query + getStoreProducts action.
 */
export function MarketplaceSectionContent() {
    const [search, setSearch] = useState('')
    const [selectedCategory, setSelectedCategory] = useState('ALL')

    const { data: products = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.store.products,
        queryFn: getStoreProducts,
        staleTime: 1000 * 60 * 5 // 5 minutes
    })

    const categories = React.useMemo(() => {
        if (!products.length) return [{ label: 'TODAS AS CATEGORIAS', value: 'ALL' }]
        const cats = Array.from(new Set(products.map((p: any) => p.category).filter(Boolean)))
        return [
            { label: 'TODAS AS CATEGORIAS', value: 'ALL' },
            ...cats.map((c: any) => ({ label: String(c).toUpperCase(), value: String(c) }))
        ]
    }, [products])

    const filtered = products.filter((p: any) => {
        const q = search.toLowerCase()
        const matchesSearch = p.name?.toLowerCase().includes(q) ||
            p.description?.toLowerCase().includes(q) ||
            p.category?.toLowerCase().includes(q)
        
        const matchesCategory = selectedCategory === 'ALL' || p.category === selectedCategory
        
        return matchesSearch && matchesCategory
    })

    function handleBuy(product: any) {
        if (product.link_url) window.open(product.link_url, '_blank')
        logProductClick(product.id)
    }

    if (isLoading) {
        return <EmptyState icon={ShoppingBag} title="CARREGANDO..." description="BUSCANDO OS PRODUTOS DA LOJA." />
    }

    if (filtered.length === 0 && !isLoading) {
        return (
            <EmptyState
                icon={ShoppingBag}
                title="LOJA INDISPONÍVEL"
                description={search ? 'NENHUM PRODUTO ENCONTRADO PARA SUA BUSCA.' : 'NÃO HÁ PRODUTOS DISPONÍVEIS NO MOMENTO.'}
            />
        )
    }

    return (
        <Stack gap={STORE_TOKENS.SPACING.EMPTY_STATE}>
            <StoreHeroCard />
            {/* Search + Category Filter block */}
            <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                <Box 
                    display="flex" 
                    direction={{ base: 'col', md: 'row' }} 
                    gap={STORE_TOKENS.SPACING.ELEMENT}
                    fullWidth
                    align="center"
                >
                    <Box width={{ base: 'full', md: '70%' }}>
                        <Input
                            placeholder="Buscar por nome, descrição ou categoria..."
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            icon={<Search
                                {...{
                                    className: "w-4 h-4",
                                }} />}
                        />
                    </Box>
                    <Box width={{ base: 'full', md: '30%' }}>
                        <FormSelect
                            options={categories}
                            value={selectedCategory}
                            onChange={setSelectedCategory}
                            placeholder="CATEGORIAS"
                        />
                    </Box>
                </Box>

                {filtered.length === 0 ? (
                    <EmptyState
                        icon={ShoppingBag}
                        title="NENHUM RESULTADO"
                        description="NENHUM PRODUTO ENCONTRADO PARA SUA BUSCA."
                    />
                ) : (
                    <Grid cols={{ base: 1, md: 2, lg: 4 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                        {filtered.map((product: any) => (
                            <StoreProductCard
                                key={product.id}
                                id={String(product.id)}
                                name={product.name}
                                description={product.description || ''}
                                category={product.category || 'OFERTA'}
                                price={product.official_price || 0}
                                rating={product.rating || 5}
                                reviewsCount={product.reviews_count || 0}
                                imageUrl={product.image_url || ''}
                                linkUrl={product.link_url}
                                onBuy={() => handleBuy(product)}
                            />
                        ))}
                    </Grid>
                )}
            </Stack>
        </Stack>
    );
}

'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { Stack } from '@/components/store/base/stack'
import { Grid } from '@/components/store/base/grid'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Trophy, TrendingUp } from 'lucide-react'
import { RankingPodiumCard } from '@/components/store/intermediary/ranking-podium-card'
import { RankingListItem } from '@/components/store/intermediary/ranking-list-item'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTrainerRanking } from '@/actions/trainer-actions'

/**
 * RankingSectionContent: Composes Podium and General Ranking sections.
 * Fully data-driven via React Query + getTrainerRanking action.
 */
export function RankingSectionContent() {
    const { data: ranking = [], isLoading } = useQuery({
        queryKey: QUERY_KEYS.admin.trainers,
        queryFn: () => getTrainerRanking(),
        staleTime: 1000 * 60 * 5 // 5 minutes
    })

    if (isLoading) {
        return <EmptyState icon={Trophy} title="CARREGANDO..." description="BUSCANDO OS MELHORES TREINADORES." />
    }

    if (ranking.length === 0) {
        return (
            <EmptyState
                icon={Trophy}
                title="RANKING INDISPONÍVEL"
                description="AGUARDANDO O FECHAMENTO DO CICLO PARA GERAR O PÓDIO."
            />
        )
    }

    const podium = ranking.slice(0, 3)
    const generalList = ranking.slice(3)

    return (
        <Stack gap={STORE_TOKENS.SPACING.EMPTY_STATE}>
            {/* 1. Pódio Section */}
            <RegistrySection
                title="PÓDIO REPTRAIL"
                subtitle="O top 3 do momento na nossa comunidade."
                icon={TrendingUp}
            >
                <Grid cols={{ base: 1, md: 3 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                    {podium.map((trainer: any, idx: number) => (
                        <RankingPodiumCard
                            key={trainer.id}
                            rank={idx + 1}
                            trainer={trainer}
                        />
                    ))}
                </Grid>
            </RegistrySection>

            {/* 2. Classificação Geral Section (only if there are more than 3) */}
            {generalList.length > 0 && (
                <RegistrySection
                    title="CLASSIFICAÇÃO GERAL"
                    subtitle="Todos os treinadores certificados e ativos."
                    icon={Trophy}
                >
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                        {generalList.map((trainer: any, idx: number) => (
                            <RankingListItem
                                key={trainer.id}
                                rank={idx + 4}
                                trainer={trainer}
                            />
                        ))}
                    </Stack>
                </RegistrySection>
            )}
        </Stack>
    )
}

'use client'

import { useState } from 'react'
import { searchTrainers } from '@/actions/student-actions'
import { Search, Trophy } from 'lucide-react'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Stack } from '@/components/store/base/stack'
import { Surface } from '@/components/store/base/surface'
import { Box } from '@/components/store/base/box'
import { Grid } from '@/components/store/base/grid'
import { Input } from '@/components/store/base/input'
import { Font } from '@/components/store/base/font'
import { Icon } from '@/components/store/base/icon'
import { RankingPodiumCard } from '@/components/store/intermediary/ranking-podium-card'
import { fbqEvent } from '@/lib/meta-pixel'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { STORE_TOKENS } from '@/components/store/constants/tokens'

export function SearchPersonalSection() {
    const [filters, setFilters] = useState({
        query: '',
        region: '',
        specialty: '',
        sortBy: 'rating' as any
    })

    const { data: trainers = [], isLoading: loading } = useQuery({
        queryKey: QUERY_KEYS.search.trainers(filters),
        queryFn: async () => {
            const results = await searchTrainers(filters)
            if (filters.query || filters.region || filters.specialty) {
                fbqEvent("Lead", {
                    content_category: "Trainer Search",
                    search_string: filters.query,
                    region: filters.region,
                    specialty: filters.specialty
                });
            }
            return results
        },
        staleTime: 1000 * 60,
    })

    return (
        <Stack gap={{ base: STORE_TOKENS.SPACING.EMPTY_STATE as any, md: STORE_TOKENS.SPACING.SECTION }}>
            <RegistrySection
                title="Profissionais Disponíveis"
                subtitle={`${trainers.length} treinadores encontrados`}
                icon={Trophy}
            >
                <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                    <Box width="full">
                        <Input
                            placeholder="Nome, cidade ou especialidade..."
                            icon={<Icon icon={Search} size="xs" />}
                            value={filters.query}
                            onChange={e => setFilters(f => ({ ...f, query: e.target.value }))}
                            weight="bold"
                        />
                    </Box>

                    {loading ? (
                        <Grid cols={{ base: 1, md: 2, lg: 4 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                            {[1, 2, 4, 6].map(i => (
                                <Box key={i} bg={STORE_TOKENS.COLORS.BACKGROUND} bgOpacity={STORE_TOKENS.OPACITY.MODAL} height={300} fullWidth rounded={STORE_TOKENS.RADIUS.SYSTEM} />
                            ))}
                        </Grid>
                    ) : (
                        <Grid cols={{ base: 1, md: 2, lg: 4 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                            {trainers.map((trainer, index) => (
                                <RankingPodiumCard
                                    key={trainer.id}
                                    trainer={{
                                        ...trainer,
                                        rating: trainer.average_rating || 0,
                                        studentCount: trainer.studentCount || 0,
                                        score: trainer.score || 0
                                    }}
                                    rank={index + 1}
                                />
                            ))}
                        </Grid>
                    )}

                    {!loading && trainers.length === 0 && (
                        <Surface variant="glass" padding={STORE_TOKENS.PADDING.EMPTY_STATE as any} rounded={STORE_TOKENS.RADIUS.SYSTEM} border="dashed">
                            <Stack gap={STORE_TOKENS.SPACING.CONTAINER} align="center">
                                <Surface padding={STORE_TOKENS.PADDING.CONTAINER} bg={STORE_TOKENS.COLORS.BACKGROUND} rounded={STORE_TOKENS.RADIUS.FULL} border="subtle">
                                    <Icon icon={Search} size="lg" color={STORE_TOKENS.COLORS.TEXT.DIM} />
                                </Surface>
                                <Stack gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                    <Font
                                        variant="h3"
                                        weight="black"
                                        uppercase
                                        italic
                                        align="center"
                                        {...{
                                            color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                        }}>Nenhum rastro encontrado</Font>
                                    <Font
                                        variant="sub-tiny"
                                        weight="black"
                                        uppercase
                                        tracking="widest"
                                        align="center"
                                        {...{
                                            color: STORE_TOKENS.COLORS.TEXT.DIM,
                                        }}>
                                        Não encontramos treinadores com esses critérios.
                                    </Font>
                                </Stack>
                            </Stack>
                        </Surface>
                    )}
                </Stack>
            </RegistrySection>
        </Stack>
    );
}

'use client'

import React, { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Grid } from '@/components/store/base/grid'
import { Box } from '@/components/store/base/box'
import { Stack } from '@/components/store/base/stack'
import { Font } from '@/components/store/base/font'
import { Modal } from '@/components/store/advanced/modal'
import { AsaasPaymentModal } from '@/components/store/advanced/asaas-payment-modal'
import { StudentProfileSummary } from '@/components/store/advanced/student-profile-summary'
import { StudentSubscriptionStatus } from '@/components/store/advanced/student-subscription-status'
import { StudentProfileForm } from '@/components/store/advanced/student-profile-form'
import {
    Zap,
    AlertCircle,
    CheckCircle,
    XCircle
} from 'lucide-react'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getStudentProfile } from '@/actions/student-actions'

/**
 * StudentProfileSectionContent: A premium reconstruction of the student profile screen.
 * Fully data-driven via React Query + getStudentProfile action.
 */
export function StudentProfileSectionContent({
    userId,
    showVariants = false
}: {
    userId?: string
    showVariants?: boolean
}) {
    const [isTrialModalOpen, setIsTrialModalOpen] = useState(false)
    const [isCancelModalOpen, setIsCancelModalOpen] = useState(false)
    const [isAsaasModalOpen, setIsAsaasModalOpen] = useState(false)

    const { data: profile } = useQuery({
        queryKey: userId ? QUERY_KEYS.student.details(userId) : ['student-profile-no-id'],
        queryFn: () => getStudentProfile(userId!),
        enabled: !!userId
    })

    // Derive subscription status from backend data
    const subscriptionStatus: 'active' | 'trial_available' | 'expired' = (() => {
        const status = profile?.auto_training_status
        const trialEnd = profile?.auto_training_trial_end
        const now = new Date()

        if (status === 'active') return 'active'

        if (status === 'trial') {
            if (trialEnd && new Date(trialEnd) > now) {
                return 'active'
            }
            return 'expired'
        }

        if (status === 'trial_available') return 'trial_available'
        if (!profile?.auto_training_trial_used && status !== 'expired' && status !== 'disabled') {
            return 'trial_available'
        }

        return 'expired'
    })()

    const name = profile?.full_name || profile?.name || 'Carregando...'
    const email = profile?.email || ''
    const avatarUrl = profile?.avatar_url

    return (
        <>
            <Grid mdCols={12} gap={STORE_TOKENS.SPACING.SECTION} fullWidth>
                {/* Left Column: Profile Card & Statuses (4 cols) */}
                <Box mdColSpan={4}>
                    <Stack gap={STORE_TOKENS.SPACING.CONTAINER}>
                        <StudentProfileSummary
                            name={name}
                            email={email}
                            avatarUrl={avatarUrl}
                            userId={userId}
                        />

                        <StudentSubscriptionStatus
                            status={subscriptionStatus}
                            onActivateTrial={() => setIsTrialModalOpen(true)}
                            onCancelSubscription={() => setIsCancelModalOpen(true)}
                            onRenewSubscription={() => setIsAsaasModalOpen(true)}
                        />

                        {showVariants && (
                            <>
                                <StudentSubscriptionStatus
                                    status="trial_available"
                                    onActivateTrial={() => setIsTrialModalOpen(true)}
                                    onCancelSubscription={() => setIsCancelModalOpen(true)}
                                    onRenewSubscription={() => setIsAsaasModalOpen(true)}
                                />
                                <StudentSubscriptionStatus
                                    status="expired"
                                    onActivateTrial={() => setIsTrialModalOpen(true)}
                                    onCancelSubscription={() => setIsCancelModalOpen(true)}
                                    onRenewSubscription={() => setIsAsaasModalOpen(true)}
                                />
                            </>
                        )}
                    </Stack>
                </Box>

                {/* Right Column: Edit Form (8 cols) */}
                <Box mdColSpan={8}>
                    <StudentProfileForm userId={userId} profile={profile} />
                </Box>
            </Grid>
            {/* Confirmation Modals */}
            <Modal
                isOpen={isTrialModalOpen}
                onClose={() => setIsTrialModalOpen(false)}
                title="ATIVAR TESTE GRÁTIS"
                subtitle="Você terá acesso total por 7 dias."
                icon={Zap}
                variant="orange"
                confirmLabel="ATIVAR AGORA"
                confirmIcon={CheckCircle}
                onConfirm={() => setIsTrialModalOpen(false)}
            >
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="body-sm"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                        }}>
                        Ao ativar o período de teste, você terá acesso imediato a todas as ferramentas de Auto-Treino, Dieta e Ergogênicos do RepTrail.
                    </Font>
                    <Font
                        variant="sub-tiny"
                        weight="bold"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.MUTED,
                        }}>
                        * O teste é válido por 7 dias corridos e não requer cartão de crédito agora.
                    </Font>
                </Stack>
            </Modal>
            <Modal
                isOpen={isCancelModalOpen}
                onClose={() => setIsCancelModalOpen(false)}
                title="CANCELAR ASSINATURA"
                subtitle="Sentiremos sua falta na plataforma!"
                icon={AlertCircle}
                variant="red"
                confirmLabel="CONFIRMAR CANCELAMENTO"
                confirmIcon={XCircle}
                confirmVariant="outline-red"
                onConfirm={() => setIsCancelModalOpen(false)}
            >
                <Stack gap={STORE_TOKENS.SPACING.ELEMENT}>
                    <Font
                        variant="body-sm"
                        {...{
                            color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                        }}>
                        Tem certeza que deseja cancelar sua assinatura do Auto-Treino? Você perderá o acesso aos seus protocolos e histórico ao final do ciclo atual.
                    </Font>
                    <Font
                        variant="sub-tiny"
                        weight="black"
                        uppercase
                        italic
                        {...{
                            color: "red",
                        }}>
                        Esta ação não pode ser desfeita automaticamente.
                    </Font>
                </Stack>
            </Modal>
            <AsaasPaymentModal
                isOpen={isAsaasModalOpen}
                onClose={() => setIsAsaasModalOpen(false)}
                tier="auto_training"
                monthlyTotal={10.90}
                currentName={name}
            />
        </>
    );
}

