'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getStudentRelationship } from '@/actions/trainer-actions'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { WorkoutManagementSectionContent } from '@/components/store/sections/workout-management-section-content'
import { DietManagementSectionContent } from '@/components/store/sections/diet-management-section-content'
import { CardioManagementSectionContent } from '@/components/store/sections/cardio-management-section-content'
import { TrainerStudentErgogenicsSmart } from '@/components/store/advanced/trainer-student-ergogenics-smart'
import { TrainerRegistryHeaderActions } from '@/components/store/advanced/trainer-registry-header-actions'
import { Stack } from '@/components/store/base/stack'
import { Icon } from '@/components/store/base/icon'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Dumbbell, Utensils, Activity, Loader2 } from 'lucide-react'

interface TrainerStudentProtocolsSectionProps {
    relationshipId: string
    studentId: string
    trainerId: string
}

export function TrainerStudentProtocolsSection({
    relationshipId,
    studentId,
    trainerId,
}: TrainerStudentProtocolsSectionProps) {
    const { data: relationship, isLoading } = useQuery({
        queryKey: QUERY_KEYS.trainer.studentDetail(relationshipId),
        queryFn: () => getStudentRelationship(relationshipId),
        staleTime: 1000 * 60 * 5,
    })

    if (isLoading || !relationship || !relationship.student) {
        return (
            <Stack align="center" justify="center" padding={STORE_TOKENS.PADDING.SECTION} fullWidth>
                <Icon icon={Loader2} color={STORE_TOKENS.COLORS.BRAND} size="xl" spin />
            </Stack>
        );
    }

    const student = relationship.student

    // 1. Grouping Workouts
    const groupedWorkouts = (student.assigned_workouts || []).reduce((acc: any, curr: any) => {
        const wId = curr.workout?.id
        if (!wId) return acc
        if (!acc[wId]) {
            acc[wId] = {
                ...curr.workout,
                assigned_workouts: []
            }
        }
        acc[wId].assigned_workouts.push({ day_of_week: curr.day_of_week })
        return acc
    }, {})
    const displayWorkouts = Object.values(groupedWorkouts)

    // 2. Grouping Diets
    const groupedDiets = (student.assigned_diets || []).reduce((acc: any, curr: any) => {
        const dId = curr.diet_id || curr.diet?.id
        if (!dId) return acc
        if (!acc[dId]) {
            acc[dId] = {
                ...(curr.diet || curr),
                assigned_diets: []
            }
        }
        if (curr.days_of_week) {
            const days = Array.isArray(curr.days_of_week) ? curr.days_of_week : []
            acc[dId].assigned_diets.push(...days.map((d: number) => ({ day_of_week: d })))
        }
        return acc
    }, {})
    const displayDiets = Object.values(groupedDiets)

    // 3. Grouping Cardio
    const groupedCardios = (student.assigned_cardios || []).reduce((acc: any, curr: any) => {
        const cId = curr.cardio_id || curr.id
        if (!cId) return acc
        if (!acc[cId]) {
            acc[cId] = {
                ...(curr.cardio || curr),
                assigned_cardios: []
            }
        }
        const addDay = (d: number) => {
            if (!acc[cId].assigned_cardios.some((a: any) => a.day_of_week === d)) {
                acc[cId].assigned_cardios.push({ day_of_week: d })
            }
        }
        if (curr.days_of_week && Array.isArray(curr.days_of_week)) {
            curr.days_of_week.forEach((d: number) => addDay(d))
        } else if (curr.day_of_week !== null && curr.day_of_week !== undefined) {
            addDay(curr.day_of_week)
        }
        return acc
    }, {})
    const displayCardios = Object.values(groupedCardios)

    return (
        <Stack gap={STORE_TOKENS.SPACING.SECTION} fullWidth>
            <RegistrySection
                title="Treinamentos de Força"
                subtitle="Visualize, organize e prescreva os templates de treinamento de força ativos para o aluno."
                icon={Dumbbell}
                rightElement={
                    <TrainerRegistryHeaderActions
                        userId={trainerId}
                        variant="workout"
                        betaTesterMode={false}
                        hideImportPdf={true}
                    />
                }
            >
                <WorkoutManagementSectionContent
                    userId={studentId}
                    workouts={displayWorkouts}
                    mode="trainer"
                />
            </RegistrySection>

            <RegistrySection
                title="Protocolos Alimentares"
                subtitle="Planeje e gerencie as refeições, calorias e macros da rotina alimentar do aluno."
                icon={Utensils}
                rightElement={
                    <TrainerRegistryHeaderActions
                        userId={trainerId}
                        variant="diet"
                        betaTesterMode={false}
                        hideImportPdf={true}
                    />
                }
            >
                <DietManagementSectionContent
                    userId={studentId}
                    diets={displayDiets}
                    mode="trainer"
                />
            </RegistrySection>

            <RegistrySection
                title="Atividades Cardiorrespiratórias"
                subtitle="Defina metas de cardio, frequências semanais e intensidades sugeridas."
                icon={Activity}
                rightElement={
                    <TrainerRegistryHeaderActions
                        userId={trainerId}
                        variant="cardio"
                        betaTesterMode={false}
                        hideImportPdf={true}
                    />
                }
            >
                <CardioManagementSectionContent
                    userId={studentId}
                    cardios={displayCardios}
                    mode="trainer"
                />
            </RegistrySection>

            <TrainerStudentErgogenicsSmart effectiveStudentId={studentId} />
        </Stack>
    )
}

'use client'

import React, { useState, useCallback } from 'react'
import Link from 'next/link'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTrainerStudents } from '@/actions/trainer-actions'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { ActionableListCard } from '@/components/store/intermediary/actionable-list-card'
import { Input } from '@/components/store/base/input'
import { Stack } from '@/components/store/base/stack'
import { Inline } from '@/components/store/base/layout'
import { Font } from '@/components/store/base/font'
import { BaseAvatar } from '@/components/store/base/avatar'
import { Badge } from '@/components/store/base/badge'
import { Button } from '@/components/store/base/button'
import { Box } from '@/components/store/base/box'
import { Icon } from '@/components/store/base/icon'
import { EmptyState } from '@/components/store/intermediary/empty-state'
import { Modal } from '@/components/store/advanced/modal'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { Users, Search, ArrowUpRight, UserMinus, AlertTriangle } from 'lucide-react'

interface TrainerStudentsListSectionProps {
    userId: string
}

export function TrainerStudentsListSection({ userId }: TrainerStudentsListSectionProps) {
    const [search, setSearch] = useState('')
    const [deactivateTarget, setDeactivateTarget] = useState<any>(null)
    const [isDeactivating, setIsDeactivating] = useState(false)

    const { data: students = [] } = useQuery({
        queryKey: QUERY_KEYS.trainer.students(userId),
        queryFn: () => getTrainerStudents(userId),
    })

    const filteredStudents = students.filter((s: any) =>
        s.active && (
            (s.student?.full_name?.toLowerCase().includes(search.toLowerCase())) ||
            (s.student?.email?.toLowerCase().includes(search.toLowerCase()))
        )
    )

    const handleDeactivateConfirm = useCallback(async () => {
        if (!deactivateTarget) return
        setIsDeactivating(true)
        try {
            const { deactivateAndPurgeStudent } = await import('@/actions/trainer-actions')
            const result = await deactivateAndPurgeStudent(deactivateTarget.id, deactivateTarget.student_id)
            if (result.success) {
                window.location.reload()
            }
        } finally {
            setIsDeactivating(false)
            setDeactivateTarget(null)
        }
    }, [deactivateTarget])

    return (
        <>
            <RegistrySection
                title="Lista da Matrícula"
                subtitle="Gerencie seus alunos ativos e suas informações."
                icon={Users}
                rightElement={
                    <Box width={{ base: 'full', md: 'auto' }}>
                        <Input
                            type="text"
                            placeholder="Buscar aluno..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            icon={<Icon icon={Search} size="xs" />}
                        />
                    </Box>
                }
            >
                {filteredStudents.length > 0 ? (
                    <Stack gap={STORE_TOKENS.SPACING.ELEMENT} fullWidth>
                        {filteredStudents.map((item: any) => {
                            const todayDay = new Date().getDate()
                            const paymentDay = item.payment_day
                            const lastPayment = item.last_payment_date
                            const isPaidThisMonth = lastPayment &&
                                new Date(lastPayment).getMonth() === new Date().getMonth() &&
                                new Date(lastPayment).getFullYear() === new Date().getFullYear()

                            let paymentStatus = null
                            if (paymentDay && !isPaidThisMonth) {
                                if (todayDay === paymentDay) paymentStatus = 'due_today'
                                else if (todayDay > paymentDay) paymentStatus = 'overdue'
                            }

                            const avatarInitials = item.student?.full_name?.substring(0, 2) || 'AL'
                            const formattedValue = `R$ ${Number(item.monthly_fee).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
                            const formattedDay = item.payment_day ? `Dia ${item.payment_day}` : null

                            return (
                                <ActionableListCard
                                    key={item.id}
                                    badges={
                                        <Stack gap={STORE_TOKENS.SPACING.ELEMENT} align="end">
                                            <Inline gap={STORE_TOKENS.SPACING.ELEMENT} align="center">
                                                {item.is_new && (
                                                    <Badge label="Pendente" variant="glass" color={STORE_TOKENS.COLORS.INFO} size="xs" />
                                                )}
                                                {item.is_placeholder ? (
                                                    <Badge label="Aguardando Cadastro" variant="glass" color={STORE_TOKENS.COLORS.WARNING} size="xs" />
                                                ) : (
                                                    <Badge 
                                                        label={item.active ? 'Ativo' : 'Inativo'} 
                                                        variant={item.active ? 'glass' : 'outline'} 
                                                        color={item.active ? STORE_TOKENS.COLORS.SUCCESS : STORE_TOKENS.COLORS.BACKGROUND} 
                                                        size="xs" 
                                                    />
                                                )}
                                                {paymentStatus === 'overdue' && !item.is_placeholder && (
                                                    <Badge label="Atrasado" variant="glass" color={STORE_TOKENS.COLORS.ERROR} size="xs" />
                                                )}
                                                {paymentStatus === 'due_today' && !item.is_placeholder && (
                                                    <Badge label="Vence Hoje" variant="glass" color={STORE_TOKENS.COLORS.WARNING} size="xs" />
                                                )}
                                                <Badge label={formattedValue} variant="glass" color={STORE_TOKENS.COLORS.WARNING} size="xs" />
                                                {formattedDay && (
                                                    <Badge label={formattedDay} variant="glass" color={STORE_TOKENS.COLORS.ERROR} size="xs" />
                                                )}
                                            </Inline>
                                        </Stack>
                                    }
                                    actions={
                                        <>
                                            <Button 
                                                variant="outline-zinc" 
                                                size="sm" 
                                                rounded={STORE_TOKENS.RADIUS.FULL} 
                                                isIconOnly 
                                                hoverScale={110}
                                                activeScale={95}
                                                transition
                                                asChild
                                            >
                                                <Link
                                                    href={`/dashboard/trainer/students/${item.id}`}
                                                    aria-label="Abrir página do aluno"
                                                >
                                                    <Icon icon={ArrowUpRight} size="xs" />
                                                </Link>
                                            </Button>
                                            {item.active && (
                                                <Button 
                                                    variant="outline-red" 
                                                    size="sm" 
                                                    rounded={STORE_TOKENS.RADIUS.FULL} 
                                                    isIconOnly 
                                                    hoverScale={110}
                                                    activeScale={95}
                                                    transition
                                                    onClick={() => setDeactivateTarget(item)}
                                                >
                                                    <Icon icon={UserMinus} size="xs" />
                                                </Button>
                                            )}
                                        </>
                                    }
                                >
                                    <Inline
                                        gap={STORE_TOKENS.SPACING.CONTAINER}
                                        align="center"
                                        fullWidth
                                        {...{
                                            minWidth: 0,
                                        }}>
                                        <Box shrink={0}>
                                            <BaseAvatar src={item.student?.avatar_url || undefined} initials={avatarInitials} variant="zinc" size="md" />
                                        </Box>
                                        <Stack gap={STORE_TOKENS.SPACING.NONE} minWidth={0} flex1>
                                            <Box fullWidth minWidth={0} overflow="hidden">
                                                <Font
                                                    {...STORE_TOKENS.TYPOGRAPHY.HEADING}
                                                    variant={{ base: 'body-sm', md: 'body' }}
                                                    truncate
                                                    display="block"
                                                    {...{
                                                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                                                    }}>
                                                    {item.student?.full_name || 'Sem nome'}
                                                </Font>
                                            </Box>
                                            <Box fullWidth minWidth={0} overflow="hidden">
                                                <Font
                                                    {...STORE_TOKENS.TYPOGRAPHY.LABEL}
                                                    lowercase
                                                    truncate
                                                    display="block"
                                                    {...{
                                                        color: STORE_TOKENS.COLORS.TEXT.DIM,
                                                    }}>
                                                    {item.student?.email || 'Sem email'}
                                                </Font>
                                            </Box>
                                        </Stack>
                                    </Inline>
                                </ActionableListCard>
                            );
                        })}
                    </Stack>
                ) : (
                    <EmptyState
                        icon={Users}
                        title="Nenhum aluno encontrado"
                        description="Sua busca não retornou nenhum aluno ou você ainda não possui alunos ativos."
                        variant="zinc"
                    />
                )}
            </RegistrySection>
            <Modal
                isOpen={!!deactivateTarget}
                onClose={() => setDeactivateTarget(null)}
                title="Desativar Aluno"
                subtitle="Esta ação não pode ser desfeita facilmente."
                icon={AlertTriangle}
                variant="red"
                confirmLabel="Desativar"
                confirmVariant="outline-red"
                confirmIcon={UserMinus}
                cancelLabel="Cancelar"
                onConfirm={handleDeactivateConfirm}
                isLoading={isDeactivating}
            >
                <Font
                    variant="description"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.SECONDARY,
                    }}>
                    Tem certeza que deseja desativar <Font
                    variant="description"
                    weight="black"
                    {...{
                        color: STORE_TOKENS.COLORS.TEXT.PRIMARY,
                    }}>{deactivateTarget?.student?.full_name}</Font>? Isso removerá todos os treinos, dietas e cardios atribuídos por você.
                </Font>
            </Modal>
        </>
    );
}

'use client'

import React from 'react'
import { useQuery } from '@tanstack/react-query'
import { QUERY_KEYS } from '@/lib/query-keys'
import { getTrainerStudents, getTrainerProfile, getTrainerRanking } from '@/actions/trainer-actions'
import { Grid } from '@/components/store/base/grid'
import { STORE_TOKENS } from '@/components/store/constants/tokens'
import { StatsCard } from '@/components/store/intermediary/stats-card'
import { RegistrySection } from '@/components/store/advanced/registry-section'
import { Users, Wallet, Activity, BarChart3 } from 'lucide-react'

interface TrainerStudentsMetricsSectionProps {
    userId: string
}

export function TrainerStudentsMetricsSection({ userId }: TrainerStudentsMetricsSectionProps) {
    const { data: students = [] } = useQuery({
        queryKey: QUERY_KEYS.trainer.students(userId),
        queryFn: () => getTrainerStudents(userId),
    })
    const { data: profile } = useQuery({
        queryKey: QUERY_KEYS.trainer.profile(userId),
        queryFn: () => getTrainerProfile(userId),
    })
    const { data: fullRanking = [] } = useQuery({
        queryKey: QUERY_KEYS.trainer.ranking(),
        queryFn: getTrainerRanking,
    })

    const currentTier = (profile?.plan_tier as 'on_demand' | 'start' | 'pro' | 'elite') || 'on_demand'
    const TIER_LIMITS = {
        on_demand: 5,
        start: 10,
        pro: 50,
        elite: Infinity
    }
    const limit = TIER_LIMITS[currentTier] || 5
    const limitDisplay = limit === Infinity ? '∞' : String(limit)

    const userRankIndex = fullRanking.findIndex((t: any) => t.id === userId)
    const userRank = userRankIndex !== -1 ? userRankIndex + 1 : '-'

    const activeStudentsCount = students.filter((s: any) => s.active).length
    const totalRevenue = students.filter((s: any) => s.active).reduce((acc: number, curr: any) => acc + (Number(curr.monthly_fee) || 0), 0)

    return (
        <RegistrySection
            title="Resumo Financeiro"
            subtitle="Visão geral dos seus indicadores de desempenho."
            icon={BarChart3}
        >
            <Grid cols={{ base: 1, md: 3 }} gap={STORE_TOKENS.SPACING.CONTAINER}>
                <StatsCard
                    label="Alunos Ativos"
                    value={`${activeStudentsCount} / ${limitDisplay}`}
                    icon={Users}
                    {...{
                        color: "primary",
                    }} />
                <StatsCard
                    label="Receita Mensal"
                    value={`R$ ${totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`}
                    icon={Wallet}
                    {...{
                        color: "primary",
                    }} />
                <StatsCard
                    label="Ranking Geral"
                    value={`${userRank}º`}
                    icon={Activity}
                    {...{
                        color: "primary",
                    }} />
            </Grid>
        </RegistrySection>
    );
}

import { useMutation, useQueryClient, QueryKey } from '@tanstack/react-query'
import { outboxDB, EntityType } from '@/lib/outbox-db'
import { syncEngine } from '@/lib/sync-engine'

interface UseOptimisticMutationOptions<TData, TVariables, TContext> {
    queryKey: QueryKey
    actionName: string
    entity: EntityType
    entityId?: string
    mutationFn?: (variables: TVariables) => Promise<TData>
    updateFn?: (oldData: any, variables: TVariables) => any
    onMutate?: (variables: TVariables) => Promise<TContext> | TContext
    onSuccess?: (data: TData, variables: TVariables, context: any) => void
    onError?: (error: Error, variables: TVariables, context: any) => void
    onSettled?: (data: TData | undefined, error: Error | null, variables: TVariables, context: any) => void
    additionalQueryKeys?: QueryKey[]
}

/**
 * Enhanced Local-First hook for optimistic mutations using TanStack Query + Persistent Outbox.
 * Enforces Strong Consistency via clientMutationId and localClientId.
 */
export function useOptimisticMutation<TData = any, TVariables = any, TContext = any>({
    queryKey,
    actionName,
    entity,
    entityId: providedEntityId,
    updateFn,
    onMutate,
    onSuccess,
    onError,
    onSettled,
    additionalQueryKeys = [],
}: UseOptimisticMutationOptions<TData, TVariables, TContext>) {
    const queryClient = useQueryClient()

    return useMutation({
        mutationFn: async (variables: any) => {
            return variables as any
        },
        onMutate: (rawVariables: any) => {
            // ─── PHASE 1: IDENTITY (SYNCHRONOUS) ──────────────────────────────────
            const clientMutationId = crypto.randomUUID()
            
            // Persistent Client ID (Sync access)
            let localClientId = typeof window !== 'undefined' ? localStorage.getItem('reptrail_client_id') : null
            if (!localClientId && typeof window !== 'undefined') {
                localClientId = crypto.randomUUID()
                localStorage.setItem('reptrail_client_id', localClientId)
            }

            // Determine if it's a creation action that needs an ID
            const isCreation = !rawVariables.id && !actionName.includes('delete') && !actionName.includes('update')
            const entityId = (providedEntityId && providedEntityId !== 'new') 
                ? providedEntityId 
                : (isCreation ? crypto.randomUUID() : (rawVariables.id || 'none'))

            const variables = {
                ...rawVariables,
                clientMutationId,
                clientId: localClientId
            }

            if (isCreation) {
                variables.id = entityId
            }

            const previousData = queryKey ? queryClient.getQueryData(queryKey) : undefined

            // ─── OPTIMISTIC UPDATE (SYNCHRONOUS & INSTANT) ─────────────────────────
            // We update the cache in this same task to trigger React immediately
            if (updateFn && queryKey) {
                queryClient.setQueryData(queryKey, (oldData: any) => updateFn(oldData, variables))
            }

            // Perform Custom Side Effects (like toasts or manual cache updates) immediately
            if (onMutate) {
                onMutate(variables)
            }

            // ─── PHASE 2: BACKGROUND SIDE EFFECTS ─────────────────────────────────
            // Offload database I/O and query cancellation to the next macro-task
            // This ensures the browser can paint BEFORE doing heavy work
            setTimeout(() => {
                if (queryKey) {
                    queryClient.cancelQueries({ queryKey })
                }
                
                additionalQueryKeys.forEach(key => {
                    queryClient.cancelQueries({ queryKey: key })
                })

                // Outbox Enqueue (Background)
                outboxDB.enqueue({
                    id: crypto.randomUUID(), 
                    clientMutationId,
                    clientId: localClientId || 'server',
                    action: actionName,
                    payload: variables,
                    entity,
                    entityId,
                } as any).then(() => {
                    syncEngine.trigger()
                }).catch(err => {
                    console.error('[OptimisticMutation] Outbox Enqueue Error:', err)
                })
            }, 0)

            return { previousData, clientMutationId }
        },

        onSuccess: async (data: any, variables: any, context: any) => {
            if (onSuccess) onSuccess(data, variables, context)
        },
        onError: async (err, variables: any, context: any) => {
            if (context?.previousData && queryKey) {
                queryClient.setQueryData(queryKey, context.previousData)
            }
            if (onError) onError(err as Error, variables, context)
        },
        onSettled: (data, error, variables: any, context) => {
            if (onSettled) onSettled(data, error, variables, context)
        },
    })
}
